// Zusammenfassung Betriebliches Kostenwesen – eigene Formulierungen und eigene Schaubilder
(window.TEXTBAND=window.TEXTBAND||{}).KW={
 title:'Betriebliches Kostenwesen',
 src:'Zusammenfassung nach dem Lehrgangs-Textband',
 intro:'Kostenrechnung aus Meistersicht: Kosten planen, erfassen, auf Kostenstellen und Produkte verteilen, Abweichungen erklären und Kosten gezielt senken. In der Prüfung zählen saubere, nachvollziehbare Rechenwege (Plankosten und Abweichungen, BAB, Zuschlags- und Maschinenstundensatzkalkulation, Deckungsbeitrag, Investitions- und Prozesskostenrechnung, Zeitwirtschaft) und die Begründung von Maßnahmen.',
 ch:[
  {t:'Einführung: Rechnungswesen im Überblick',h:'Einführung',pg:1,b:[
    {p:'Steigender Kosten- und Preisdruck zwingt Betriebe, Material, Arbeit und Betriebsmittel wirtschaftlich zu kombinieren. Das Rechnungswesen liefert dafür die Zahlen: Es erfasst Güter- und Geldströme in Beschaffung, Fertigung und Absatz, wertet sie aus und macht sie steuerbar.'},
    {svg:{w:520,h:200,body:'<rect x="185" y="10" width="150" height="34" class="sk-body"/><text x="260" y="32" text-anchor="middle" class="sk-t acc">Rechnungswesen</text><line x1="260" y1="44" x2="260" y2="62" class="sk-l"/><line x1="70" y1="62" x2="445" y2="62" class="sk-l"/><line x1="70" y1="62" x2="70" y2="84" class="sk-l"/><line x1="195" y1="62" x2="195" y2="84" class="sk-l"/><line x1="320" y1="62" x2="320" y2="84" class="sk-l"/><line x1="445" y1="62" x2="445" y2="84" class="sk-l"/><rect x="10" y="84" width="120" height="76" class="sk-body"/><rect x="135" y="84" width="120" height="76" class="sk-body"/><rect x="260" y="84" width="120" height="76" class="sk-body"/><rect x="385" y="84" width="120" height="76" class="sk-body"/><text x="70" y="106" text-anchor="middle" class="sk-t acc">Buchführung</text><text x="70" y="126" text-anchor="middle" class="sk-t">extern</text><text x="70" y="146" text-anchor="middle" class="sk-t">Jahresabschluss</text><text x="195" y="106" text-anchor="middle" class="sk-t acc">KLR</text><text x="195" y="126" text-anchor="middle" class="sk-t">intern</text><text x="195" y="146" text-anchor="middle" class="sk-t">Betriebsergebnis</text><text x="320" y="106" text-anchor="middle" class="sk-t acc">Statistik</text><text x="320" y="126" text-anchor="middle" class="sk-t">intern</text><text x="320" y="146" text-anchor="middle" class="sk-t">Vergleiche</text><text x="445" y="106" text-anchor="middle" class="sk-t acc">Planung</text><text x="445" y="126" text-anchor="middle" class="sk-t">intern</text><text x="445" y="146" text-anchor="middle" class="sk-t">Budgets, Soll</text><text x="260" y="188" text-anchor="middle" class="sk-t">nur die Buchführung ist gesetzlich vorgeschrieben (HGB, AO)</text>',cap:'Die vier Teilbereiche des Rechnungswesens'}},
    {tab:[['Bereich','Aufgabe','Rechtsbindung'],['Finanz- bzw. Geschäftsbuchhaltung','alle Geschäftsvorfälle buchen, Inventur, Jahresabschluss','HGB (z. B. § 238 Buchführungspflicht, § 325 Offenlegung), AO, Steuerrecht'],['Kosten- und Leistungsrechnung','Kosten und Leistungen des Betriebszwecks erfassen, Betriebsergebnis, Kalkulation','frei; Ausnahme: Preise bei öffentlichen Aufträgen (Preisverordnung)'],['Statistik','Zahlen verdichten, Zeit-, Betriebs- und Soll-Ist-Vergleiche','frei'],['Planungsrechnung','Zukunftswerte planen (vom Absatzplan rückwärts), Budgets und Sollwerte','frei']]},
    {ul:['Externes Rechnungswesen informiert Außenstehende (Finanzamt, Banken, Lieferanten), internes Rechnungswesen die Unternehmensleitung und die Kostenstellenleiter','Nebenbuchhaltungen (Anlagen-, Material-, Lohn- und Gehaltsbuchhaltung) liefern Daten an Finanzbuchhaltung und KLR gleichermaßen','Planung läuft retrograd: vom Absatzplan zurück zu Fertigungsprogramm, Beschaffung und Personal','Statistik liefert Leistungs-, Qualitäts-, Kosten- und Personalstatistiken']},
    {ul:['Buchführungspflicht Einzelkaufleute: ab Umsatz > 800.000 € oder Gewinn > 80.000 € in zwei Folgejahren (§ 241a HGB, § 141 AO; Werte seit 2024)','Kleine Kapitalgesellschaften (§ 267 HGB, seit 2024: Bilanzsumme ≤ 7,5 Mio. €, Umsatz ≤ 15 Mio. €, ≤ 50 Beschäftigte; zwei von drei Merkmalen): keine Prüfungspflicht, verkürzte Offenlegung','Kapitalmarktorientierte Konzerne bilanzieren nach IFRS; das BilMoG hat das HGB-Bilanzrecht modernisiert (weniger Wahlrechte, Trennung von Steuerrecht)','Steuerrecht wandelt sich laufend (Zinsschranke § 4h EStG/§ 8a KStG, Optionsmodell für Personengesellschaften § 1a KStG seit 2022, degressive AfA zeitweise wieder zulässig)']},
    {bsp:{t:'Beispiel: Vom Unternehmensergebnis zum Betriebsergebnis',b:['Ein Zulieferbetrieb für Hydraulikteile weist in der GuV ein Jahresergebnis von 420.000 € aus.','Darin stecken betriebsfremde Posten: Erträge aus einer Beteiligung 60.000 €, Zinserträge 5.000 € und ein Verlust aus dem Verkauf von Wertpapieren 15.000 €.','Betriebsergebnis = 420.000 € − 60.000 € − 5.000 € + 15.000 € = 370.000 €.','Interpretation: Mit der eigentlichen Fertigung wurden 370.000 € erwirtschaftet. Nur diese Zahl sagt etwas über die Leistungskraft der Fertigung aus – sie ist Maßstab für Kostenstellenleiter und Kalkulation.']}},
    {merke:'Finanzbuchhaltung = Pflicht, vergangenheitsbezogen, Gesamtergebnis. KLR = freiwillig, zweckbezogen, Betriebsergebnis – und Grundlage für Kalkulation und Kostenkontrolle.'}
  ]},
  {t:'Aufgaben und Systeme der Kosten- und Leistungsrechnung',h:'Planung, Erfassung, Analyse und Bewertung der funktionsfeldbezogenen Kosten nach vorgegebenen Plandaten',pg:3,abb:[['Abb. 1.1 Organisatorische Gliederung des Rechnungswesens',4]],b:[
    {p:'Die KLR erfasst den bewerteten, periodenbezogenen Verbrauch von Gütern und Diensten für Herstellung und Absatz, ordnet ihn zu, wertet ihn aus und kontrolliert ihn. Ziel ist ein positives Betriebsergebnis: Erlöse größer als Kosten, Kosten so niedrig wie Technik und Organisation es erlauben.'},
    {ul:['Unterlagen zur Preisfindung: Kalkulation, Preisbeurteilung, Preiskontrolle','Unterlagen zur Wirtschaftlichkeit: Planung und Kontrolle von Kosten je Stelle und Produkt','Entscheidungsgrundlagen: Annahme oder Ablehnung von Aufträgen, Eigenfertigung oder Fremdbezug, Programmgestaltung','Kosten (bewerteter Verbrauch für den Betriebszweck) werden den Leistungen (Wert der erstellten Güter) gegenübergestellt – daher „Kosten- und Leistungsrechnung“']},
    {tab:[['Teilrechnung','Leitfrage','Ergebnis'],['Kostenartenrechnung','Welche Kosten sind entstanden?','Kosten nach Arten, Einzel-/Gemeinkosten, fix/variabel'],['Kostenstellenrechnung','Wo sind sie entstanden?','Gemeinkosten je Stelle (BAB), Zuschlags- und Verrechnungssätze'],['Kostenträgerrechnung','Wofür sind sie entstanden?','Selbstkosten je Stück (Kalkulation) und Betriebsergebnis je Periode']]},
    {tab:[['System','Zeitbezug','Eignung'],['Istkostenrechnung','Vergangenheit: tatsächliche Kosten','Nachkalkulation, Ergebnisermittlung'],['Normalkostenrechnung','Vergangenheit: Durchschnitt mehrerer Perioden','geglättete Sätze für die Vorkalkulation'],['Plankostenrechnung','Zukunft: geplante Mengen × Planpreise','Soll-Ist-Vergleich, Budgetvorgabe, Entscheidungen']]},
    {ul:['Vollkostenrechnung: alle Kosten (fix und variabel) werden auf die Produkte verrechnet','Teilkostenrechnung: nur die variablen (bzw. direkt zurechenbaren) Kosten gehen auf die Produkte, Fixkosten bleiben als Block']},
    {bsp:{t:'Beispiel: Die drei Fragen an einem Auftrag',b:['Auftrag: 50 Lagerböcke aus Stahlguss für einen Kunden.','Kostenarten: Gussrohlinge (Fertigungsmaterial), Lohn des Fräsers (Fertigungslohn), Strom, Kühlschmierstoff, Abschreibung des Bearbeitungszentrums, Meistergehalt.','Kostenstellen: Lager (Ausgabe der Rohlinge), Fräserei (Bearbeitung), Qualitätsprüfung, Versand.','Kostenträger: der Auftrag „50 Lagerböcke“. Material und Lohn landen direkt dort, alles andere über die Zuschlagssätze der Kostenstellen.']}},
    {merke:'Ist- und Normalkosten blicken zurück und können Unwirtschaftlichkeit nur fortschreiben. Nur Plankosten liefern einen echten Maßstab für wirtschaftliches Arbeiten.'}
  ]},
  {t:'Plankostenrechnung als Teil der Unternehmensplanung',h:'Plankostenrechnung als Teil der kostenbezogenen Unternehmensplanung',pg:4,b:[
    {p:'Die Plankostenrechnung plant die Kosten des Betriebs für eine künftige Periode (meist ein Jahr, aufgeteilt in Monate) nach Kostenarten, Kostenstellen und Kostenträgern. Sie liefert Vorgaben für jede Kostenstelle und die Basis für Angebote.'},
    {fx:['Plankosten = Planmenge · Planpreis','Planpreise sind für die Periode fest, damit Marktpreisschwankungen den Soll-Ist-Vergleich nicht verfälschen']},
    {tab:[['Vergleichsform','Was wird verglichen?','Aussage'],['Zeitvergleich','Kosten verschiedener Perioden (Vormonat, Vorjahresmonat)','Entwicklung, aber kein Maßstab'],['Betriebsvergleich','eigene Kosten mit anderen Betrieben/Werken','Stärken und Schwächen, Daten oft schwer vergleichbar'],['Soll-Ist-Vergleich','geplante bzw. Sollkosten mit Istkosten','echte Wirtschaftlichkeitskontrolle']]},
    {ol:['Kostenstellen bilden (Funktion, Verantwortung, räumliche Abgrenzung)','Bezugsgröße je Kostenstelle wählen (Fertigungs- oder Maschinenstunden, Stückzahl) – sie muss sich proportional zu den Kosten verhalten und die Beschäftigung ausdrücken; Planbezugsgröße meist aus dem Produktionsplan oder einem Engpass','Planmengen ermitteln (Erfahrung, Berechnung, Messung, Arbeitsstudien) und mit Planpreisen bzw. Lohnsätzen bewerten','Plankostenrechnung als Voll- oder Teilkostenrechnung durchführen (Einzel-/Gemeinkosten, fix/variabel)','Plankostenverrechnungssatz = Plankosten : Planbezugsgröße bilden']},
    {fx:['Plankostenverrechnungssatz PKVS = Plankosten der Kostenstelle : Planbezugsgröße','z. B. in €/Fertigungsstunde – zugleich Kalkulationssatz']},
    {ul:['Ergebnis: Kostenstellenplan (Budget) je Monat, aus der Jahresplanung anteilig der Arbeitstage','Wer Kosten verantworten soll, muss sie beeinflussen können und muss Überschreitungen begründen (Rechenschaft)','Zielsetzung beeinflusst die Planung: für Einsparziele optimale Abläufe unterstellen, für realistische Prognosen Erfahrungen einbeziehen; unerreichbare Vorgaben gehören nicht in den Kostenstellenplan','Voraussetzungen: abgestimmte Teilpläne (Absatz, Beschaffung, Fertigung, Personal, Investition, Finanzen), leistungsfähige Datenverarbeitung, gute Aufbau- und Ablauforganisation, wirtschaftliche Arbeitsvorbereitung']},
    {bsp:{t:'Beispiel: Monatsplan der Kostenstelle Schweißerei',b:['Planbezugsgröße: 1.800 Fertigungsstunden im Monat.','Schweißdraht: 900 kg · 4,20 €/kg = 3.780 €','Schutzgas: 120 Flaschen · 28,00 €/Fl. = 3.360 €','Hilfslöhne (Vorrichtungsbau, Transport): 300 h · 32,00 €/h = 9.600 €','Energie: 18.000 kWh · 0,25 €/kWh = 4.500 €','Plan-Gemeinkosten = 21.240 €; PKVS = 21.240 € : 1.800 h = 11,80 €/h.','Interpretation: Jede Fertigungsstunde in der Schweißerei wird mit 11,80 € Gemeinkosten kalkuliert. Der Meister erhält 21.240 € als Monatsbudget bei 1.800 h und erklärt am Monatsende die Abweichungen.']}},
    {merke:'Vergangene Istwerte nie ungeprüft als Plan übernehmen – sonst wird alte Verschwendung zur Vorgabe. Die Meisterin der Kostenstelle bei der Planung beteiligen: Das erhöht Akzeptanz und Kostenbewusstsein.'}
  ]},
  {t:'Plankostenrechnung in unterschiedlichen Produktionsverfahren',h:'Plankostenrechnung in unterschiedlichen Produktionsverfahren',pg:7,b:[
    {p:'Ob sich eine (flexible) Plankostenrechnung lohnt, hängt von Auftragslage und Fertigungstyp ab. Sie braucht ein über mindestens ein Jahr stabiles Programm und eine möglichst gleichbleibende Kostenstruktur.'},
    {tab:[['Fertigungstyp','Kennzeichen','Plankostenrechnung'],['Massenfertigung','ein Produkt in sehr großer Stückzahl (Normteile, Haushaltsgeräte)','gut geeignet'],['Serienfertigung','größere Stückzahl gleichartiger Produkte (Elektrogeräte, Pumpen)','gut geeignet'],['Sortenfertigung','ähnliche Produkte aus gleichem Material und Verfahren (Bleche, Drähte)','gut geeignet'],['Kleinserie / Einzelfertigung','auftragsorientiert, jedes Produkt anders','kaum geeignet – Vorkalkulation mit Durchschnittswerten'],['Partie-/Chargenfertigung','Rohstoffschwankungen von Charge zu Charge','eingeschränkt']]},
    {ul:['Probleme bei Einzel- und Kleinserienfertigung: Produkt bei Kalkulation oft noch nicht genau bekannt, Kundenwünsche ändern es; wenig Zeit für das Angebot zwingt zu vereinfachten Verfahren (Kilokosten-, Materialkostenmethode); Angebotsaufwand verursacht selbst Kosten; Gemeinkosten lassen sich keiner planbaren Menge zuordnen','Bei geringer Auslastung (Kurzarbeit) oder starken Preisschwankungen ist auch in Serienbetrieben kein verlässliches Programm planbar','Ist- und Normalkosten werden trotzdem überall für Vor- und Nachkalkulation gebraucht','Voraussetzungen der flexiblen Plankostenrechnung: abgestimmte Teilpläne, effizientes Rechnungswesen mit Iststatistik, Kostenstellen als selbstständige Verantwortungsbereiche, richtige Bezugsgrößen, passende EDV, wirtschaftliche Arbeitsvorbereitung']},
    {bsp:{t:'Beispiel: Ist-, Normal- und Plankosten eines Pumpengehäuses',b:['Istkosten je Stück der letzten sechs Monate: 41,20 €; 43,10 €; 42,50 €; 44,00 €; 42,80 €; 43,60 € (schwankende Stahlpreise, Tariferhöhung, wechselnde Stückzahlen).','Normalkosten = Durchschnitt = 257,20 € : 6 = 42,87 € je Stück – brauchbar für die Vorkalkulation, glättet Zufallsschwankungen.','Plankosten: Arbeitsvorbereitung und Meister planen mit neuer Spannvorrichtung (−1,10 €) und Ausschuss von 3 % statt 5 % (−0,30 €): 41,50 € je Stück.','Interpretation: 41,50 € ist Zielvorgabe für die Fertigung und Basis für den Angebotspreis; Abweichungen werden monatlich erklärt.']}},
    {falle:'Plankostenrechnung ist kein Allheilmittel: In der Einzelfertigung fehlt die planbare Bezugsmenge. Dort wird mit Vorkalkulation (Normalzuschläge) gearbeitet.'}
  ]},
  {t:'Starre Plankostenrechnung',h:'Starre und flexible Plankostenrechnung',pg:8,abb:[['Abb. 1.2 Formen der Plankostenrechnung',9]],b:[
    {p:'Die Plankostenrechnung kann als Vollkostenrechnung (starr oder flexibel) oder als Teilkostenrechnung (Grenzplankostenrechnung) aufgebaut sein. Die starre Form plant alle Kosten nur für eine einzige Planbeschäftigung, ohne fixe und variable Kosten zu trennen.'},
    {tab:[['Form','Kostenauflösung','Kalkulation','Abweichungsanalyse'],['starre PKR','keine','Vollkosten','nur Gesamtabweichung'],['flexible PKR auf Vollkostenbasis','fix/variabel je Kostenstelle','Vollkosten','Beschäftigungs- und Verbrauchsabweichung'],['Grenzplankostenrechnung','fix/variabel','nur variable Kosten','nur Verbrauchsabweichung']]},
    {fx:['Beschäftigungsgrad BG = Istbeschäftigung : Planbeschäftigung · 100','Verhältnis von Ist- zu Planauslastung']},
    {fx:['PKVS = Plankosten : Planbeschäftigung','']},
    {fx:['verrechnete Plankosten = PKVS · Istbeschäftigung = Plankosten · BG : 100','']},
    {fx:['Gesamtabweichung = verrechnete Plankosten − Istkosten','']},
    {svg:{w:520,h:280,body:'<line x1="60" y1="240" x2="495" y2="240" class="sk-l" marker-end="url(#ar)"/><line x1="60" y1="240" x2="60" y2="20" class="sk-l" marker-end="url(#ar)"/><text x="68" y="28" class="sk-t">Kosten (€)</text><text x="505" y="274" text-anchor="end" class="sk-t">Beschäftigung (h)</text><line x1="60" y1="240" x2="440" y2="44" class="sk-l"/><line x1="330" y1="240" x2="330" y2="60" class="sk-c"/><line x1="420" y1="240" x2="420" y2="50" class="sk-c"/><circle cx="420" cy="50" r="5" class="fillacc"/><circle cx="330" cy="59.5" r="5" class="fillacc"/><circle cx="330" cy="97.5" r="4" class="sk-body"/><line x1="342" y1="97.5" x2="342" y2="59.5" class="sk-l thick"/><text x="322" y="86" text-anchor="end" class="sk-t acc">GA</text><text x="320" y="54" text-anchor="end" class="sk-t">Istkosten 95.000 €</text><text x="505" y="38" text-anchor="end" class="sk-t">Basisplankosten</text><text x="165" y="214" class="sk-t">verrechnete Plankosten</text><text x="320" y="118" text-anchor="end" class="sk-t">75.000 €</text><text x="330" y="256" text-anchor="middle" class="sk-t">Ist 1.500</text><text x="420" y="256" text-anchor="middle" class="sk-t">Plan 2.000</text>',cap:'Starre Plankostenrechnung: Die Verrechnungsgerade läuft durch den Ursprung, die Gesamtabweichung lässt sich nicht nach Ursachen trennen'}},
    {bsp:{t:'Beispiel: Starre Rechnung in der Fräserei',b:['Plan: 2.000 Fertigungsstunden, Plankosten 100.000 €. Ist: 1.500 h, Istkosten 95.000 €.','BG = 1.500 h : 2.000 h · 100 = 75 %','PKVS = 100.000 € : 2.000 h = 50,00 €/h','verrechnete Plankosten = 50,00 €/h · 1.500 h = 75.000 €','Gesamtabweichung = 75.000 € − 95.000 € = −20.000 €','Interpretation: 20.000 € wurden nicht über die Kalkulation gedeckt. Ob die Ursache die schwache Auslastung (Fixkosten) oder Mehrverbrauch ist, zeigt die starre Rechnung nicht – der Meister kann daraus keine Maßnahme ableiten.']}},
    {merke:'Vorteile der starren PKR: einfach, keine Kostenauflösung. Nachteil: Sie passt die Plankosten nicht an Beschäftigungsschwankungen an, deshalb ist keine wirksame Kostenkontrolle möglich. In der Praxis wird fast immer flexibel gerechnet.'}
  ]},
  {t:'Flexible Plankostenrechnung auf Vollkostenbasis',h:'Starre und flexible Plankostenrechnung',pg:11,b:[
    {p:'Die flexible Plankostenrechnung trennt in jeder Kostenstelle fixe und variable Kosten. So lassen sich Sollkosten für jede Istbeschäftigung angeben und die Gesamtabweichung in Beschäftigungs- und Verbrauchsabweichung zerlegen. Ziel ist die Kontrolle des Mengenverbrauchs.'},
    {fx:['Variator = variable Plankosten : gesamte Plankosten','0 = nur fixe, 1 = nur variable Kosten; 0,7 heißt 70 % variabel, 30 % fix (in Teilen der Literatur mit 10 multipliziert)']},
    {fx:['variabler PKVS = variable Plankosten : Planbeschäftigung; fixer PKVS = fixe Plankosten : Planbeschäftigung','PKVS = fixer + variabler PKVS']},
    {fx:['Sollkosten = fixe Plankosten + variabler PKVS · Istbeschäftigung','= fixe Plankosten + variable Plankosten · BG : 100']},
    {fx:['Beschäftigungsabweichung BA = verrechnete Plankosten − Sollkosten','zu wenig (BG < 100 %) oder zu viel (BG > 100 %) verrechnete Fixkosten']},
    {fx:['Verbrauchsabweichung VA = Sollkosten − Istkosten','Istkosten zu Planpreisen bewertet; Mehr- oder Minderverbrauch']},
    {fx:['Gesamtabweichung GA = BA + VA = verrechnete Plankosten − Istkosten','']},
    {fx:['Preisabweichung = Istmenge · Planpreis − Istmenge · Istpreis','wird vorab herausgerechnet']},
    {svg:{w:520,h:290,body:'<line x1="60" y1="250" x2="495" y2="250" class="sk-l" marker-end="url(#ar)"/><line x1="60" y1="250" x2="60" y2="22" class="sk-l" marker-end="url(#ar)"/><text x="68" y="30" class="sk-t">Kosten (€)</text><text x="505" y="280" text-anchor="end" class="sk-t">Beschäftigung (h)</text><line x1="60" y1="190" x2="460" y2="190" class="sk-c"/><text x="455" y="205" text-anchor="end" class="sk-t">fixe Plankosten</text><line x1="60" y1="250" x2="460" y2="50" class="sk-l"/><line x1="60" y1="190" x2="460" y2="50" class="sk-f"/><line x1="360" y1="250" x2="360" y2="60" class="sk-c"/><line x1="460" y1="250" x2="460" y2="50" class="sk-c"/><circle cx="360" cy="60" r="5" class="fillacc"/><text x="352" y="56" text-anchor="end" class="sk-t">Istkosten</text><line x1="372" y1="100" x2="372" y2="85" class="sk-l thick"/><line x1="372" y1="85" x2="372" y2="60" class="sk-f"/><text x="380" y="98" class="sk-t">BA</text><text x="380" y="77" class="sk-t acc">VA</text><text x="360" y="266" text-anchor="middle" class="sk-t">Ist 1.500</text><text x="460" y="266" text-anchor="middle" class="sk-t">Plan 2.000</text><line x1="80" y1="48" x2="110" y2="48" class="sk-f"/><text x="118" y="52" class="sk-t">Sollkosten</text><line x1="80" y1="70" x2="110" y2="70" class="sk-l"/><text x="118" y="74" class="sk-t">verrechnete Plankosten</text>',cap:'Flexible Plankostenrechnung: Sollkosten- und Verrechnungsgerade, Abweichungen bei Unterbeschäftigung'}},
    {bsp:{t:'Beispiel: Abweichungsanalyse Fräserei bei Unterbeschäftigung',b:['Plan: 2.000 h, Plankosten 100.000 € (fix 30.000 €, variabel 70.000 € → Variator 0,7). Ist: 1.500 h, Istkosten 95.000 €.','BG = 75 %; PKVS = 50,00 €/h; verrechnete Plankosten = 50,00 €/h · 1.500 h = 75.000 €','Sollkosten = 30.000 € + 70.000 € · 0,75 = 82.500 € (variabler PKVS 35,00 €/h · 1.500 h = 52.500 € + 30.000 €)','BA = 75.000 € − 82.500 € = −7.500 € (nicht gedeckte Fixkosten)','VA = 82.500 € − 95.000 € = −12.500 € (Mehrverbrauch)','GA = −7.500 € + (−12.500 €) = −20.000 €','Interpretation: Die BA verantwortet die Meisterin nicht – sie folgt aus der Auftragslage. Die VA von 12.500 € (15 % der Sollkosten) muss sie erklären: z. B. Werkzeugbruch, Nacharbeit, schlechtes Rohmaterial.']}},
    {bsp:{t:'Beispiel: Überbeschäftigung',b:['Gleiche Kostenstelle, Ist: 2.200 h (BG 110 %), Istkosten 112.000 €.','verrechnete Plankosten = 50,00 €/h · 2.200 h = 110.000 €','Sollkosten = 30.000 € + 70.000 € · 1,10 = 107.000 €','BA = 110.000 € − 107.000 € = +3.000 € (Fixkostenüberdeckung)','VA = 107.000 € − 112.000 € = −5.000 €; GA = −2.000 €','Interpretation: Trotz guter Auslastung wurde mehr verbraucht als vorgegeben – Ursache klären (Überstunden, Fremdmaterial, Eilaufträge).']}},
    {bsp:{t:'Beispiel: Kostenreport je Kostenart (Montage, BG 75 %)',b:['Planbeschäftigung 2.000 h, Istbeschäftigung 1.500 h; Sollkosten je Kostenart = fix + variabel · 0,75.']}},
    {tab:[['Kostenart','Plan €','Var.','fix €','Soll €','Ist €','VA €'],['Fertigungslöhne','40.000','1,0','0','30.000','31.200','−1.200'],['Hilfslöhne','8.000','0,5','4.000','7.000','7.400','−400'],['Gehälter','9.000','0,0','9.000','9.000','9.000','0'],['Energie','6.000','0,8','1.200','4.800','5.300','−500'],['Werkzeuge','5.000','1,0','0','3.750','4.600','−850'],['Instandhaltung','8.000','0,5','4.000','7.000','8.900','−1.900'],['kalk. Abschreibung','16.000','0,0','16.000','16.000','16.000','0'],['kalk. Zinsen','8.000','0,0','8.000','8.000','8.000','0'],['Summe','100.000','','42.200','85.550','90.400','−4.850']]},
    {p:'Verrechnete Plankosten = 50,00 €/h · 1.500 h = 75.000 €; BA = 75.000 € − 85.550 € = −10.550 €; GA = −15.400 €. Größter Hebel für den Meister: Instandhaltung (−1.900 €) und Fertigungslöhne (−1.200 €).'},
    {ul:['Ursachen für Mehrverbrauch: Material anderer Beschaffenheit, Betriebsmittel nicht im geplanten Zustand, fehlende oder fehlerhafte Arbeitsunterlagen (Zeichnung, Stückliste, Arbeitsplan, Prüfplan), nachträgliche Konstruktionsänderungen, geänderte Abläufe (Verfahrensabweichung), geringe Leistungsbereitschaft oder -fähigkeit','Positive VA: Minderverbrauch oder zu großzügige Planvorgaben','Abweichungen ab ca. 10 % werden in der Praxis mit Kostenanalysen untersucht']},
    {falle:'BA = verrechnete − Soll, VA = Soll − Ist. Minus heißt Mehrkosten. Die Verbrauchsabweichung ist nur aussagefähig, wenn Istmengen mit Planpreisen bewertet sind – sonst steckt die Preisabweichung darin.'}
  ]},
  {t:'Grenzplankostenrechnung, Nutz- und Leerkosten',h:'Starre und flexible Plankostenrechnung',pg:15,b:[
    {p:'Die Grenzplankostenrechnung ist die flexible Plankostenrechnung auf Teilkostenbasis. Fixkosten ändern sich bei Beschäftigungsschwankungen nicht und werden deshalb aus dem Soll-Ist-Vergleich herausgehalten; geplant und verrechnet werden nur die variablen Kosten.'},
    {fx:['variabler PKVS = variable Plankosten : Planbeschäftigung','']},
    {fx:['Sollkosten = verrechnete Plankosten = variabler PKVS · Istbeschäftigung','deshalb ist die Beschäftigungsabweichung immer null']},
    {fx:['variable Istkosten = gesamte Istkosten − Fixkosten; VA = Sollkosten − variable Istkosten','']},
    {fx:['Nutzkosten = fixe Kosten · BG : 100; Leerkosten = fixe Kosten − Nutzkosten','fixe Kosten = Nutzkosten + Leerkosten']},
    {svg:{w:520,h:270,body:'<line x1="60" y1="230" x2="495" y2="230" class="sk-l" marker-end="url(#ar)"/><line x1="60" y1="230" x2="60" y2="30" class="sk-l" marker-end="url(#ar)"/><text x="68" y="38" class="sk-t">Fixkosten (€)</text><text x="505" y="262" text-anchor="end" class="sk-t">Beschäftigungsgrad</text><line x1="60" y1="80" x2="460" y2="80" class="sk-l thick"/><text x="70" y="72" class="sk-t">fixe Kosten 30.000 € (konstant)</text><line x1="60" y1="230" x2="460" y2="80" class="sk-f"/><line x1="360" y1="230" x2="360" y2="80" class="sk-c"/><line x1="352" y1="117" x2="352" y2="82" class="sk-l thick"/><text x="344" y="105" text-anchor="end" class="sk-t acc">Leerkosten 7.500 €</text><text x="368" y="190" class="sk-t">Nutzkosten 22.500 €</text><text x="360" y="246" text-anchor="middle" class="sk-t">75 %</text><text x="460" y="246" text-anchor="middle" class="sk-t">100 %</text><text x="200" y="196" text-anchor="middle" class="sk-t">Nutzkosten steigen</text><text x="200" y="212" text-anchor="middle" class="sk-t">mit der Auslastung</text>',cap:'Aufteilung der Fixkosten in Nutz- und Leerkosten bei 75 % Auslastung'}},
    {bsp:{t:'Beispiel: Fräserei als Grenzplankostenrechnung',b:['Daten wie zuvor: variable Plankosten 70.000 €, Planbeschäftigung 2.000 h, Fixkosten 30.000 €; Ist 1.500 h, Istkosten 95.000 €.','variabler PKVS = 70.000 € : 2.000 h = 35,00 €/h','Sollkosten = verrechnete Plankosten = 35,00 €/h · 1.500 h = 52.500 €','variable Istkosten = 95.000 € − 30.000 € = 65.000 €','VA = 52.500 € − 65.000 € = −12.500 € (identisch mit der Vollkostenrechnung)','Fixkostenanalyse: Nutzkosten = 30.000 € · 0,75 = 22.500 €; Leerkosten = 7.500 €.','Interpretation: Die Leerkosten (Kosten der ungenutzten Kapazität) entsprechen betragsmäßig der Beschäftigungsabweichung der Vollkostenrechnung. Sie lassen sich nur über mehr Aufträge oder Kapazitätsabbau senken, nicht durch sparsameres Arbeiten.']}},
    {merke:'Grenzplankostenrechnung: einfacher und verständlicher, weil die BA entfällt. Ideal für kurzfristige Entscheidungen. Fixkosten heißen auch Kosten der Betriebsbereitschaft; Nutzkosten nennt man auch Arbeitskosten.'},
    {falle:'In der Grenzplankostenrechnung gibt es keine Beschäftigungsabweichung. Wer eine BA ausrechnet, hat Voll- und Teilkostenbasis verwechselt.'}
  ]},
  {t:'Gliederung der Kostenarten',h:'Struktur der Plankostenrechnung',pg:19,b:[
    {p:'Mittlere und große Betriebe gliedern nach Funktionen (allgemeiner Bereich, Material, Fertigung, Verwaltung, Vertrieb) und darunter in Kostenstellen. Die Kostenstelle ist der Ort, an dem Kosten entstehen, beeinflusst werden und bei Abweichungen von der verantwortlichen Person zu vertreten sind. Für jede Stelle werden Einzel- und Gemeinkosten geplant.'},
    {ul:['Aufgaben der Kostenartenrechnung: alle künftigen Kosten der Periode erfassen, Kostenarten gliedern und zuordnen, Planbeträge je Kostenart bestimmen, Daten an Kostenstellen- und Kostenträgerrechnung liefern']},
    {tab:[['Gliederung nach','Kostenarten','Beispiele'],['Art der verbrauchten Güter','Material-, Personal-, Maschinen-, Werkzeugkosten','Rohstoff, Hilfslöhne, AfA, Bohrer'],['Herkunft','primäre Kosten (von außen bezogen) / sekundäre Kosten (in eigener Stelle erstellt)','Fremdstrom / Reparatur der eigenen Instandhaltung'],['Beschäftigung','fix / variabel / Mischkosten','Miete / Fertigungsmaterial / Instandhaltung, Energie'],['Verrechnung auf Kostenträger','Einzelkosten / Gemeinkosten','Fertigungsmaterial, -lohn / Hilfslöhne, Gehälter, Steuern'],['Erfassung','Grund-, Zusatz-, Anderskosten','Löhne / kalk. Unternehmerlohn / kalk. AfA'],['betriebliche Funktion','Material-, Fertigungs-, Verwaltungs-, Vertriebskosten','Kostenstellen der Bereiche']]},
    {svg:{w:520,h:210,body:'<line x1="25" y1="150" x2="165" y2="150" class="sk-l" marker-end="url(#ar)"/><line x1="25" y1="150" x2="25" y2="30" class="sk-l" marker-end="url(#ar)"/><line x1="25" y1="100" x2="155" y2="100" class="sk-f"/><line x1="195" y1="150" x2="335" y2="150" class="sk-l" marker-end="url(#ar)"/><line x1="195" y1="150" x2="195" y2="30" class="sk-l" marker-end="url(#ar)"/><line x1="195" y1="150" x2="325" y2="50" class="sk-f"/><line x1="365" y1="150" x2="505" y2="150" class="sk-l" marker-end="url(#ar)"/><line x1="365" y1="150" x2="365" y2="30" class="sk-l" marker-end="url(#ar)"/><line x1="365" y1="110" x2="495" y2="50" class="sk-f"/><line x1="365" y1="110" x2="495" y2="110" class="sk-c"/><text x="95" y="178" text-anchor="middle" class="sk-t acc">fixe Kosten</text><text x="95" y="198" text-anchor="middle" class="sk-t">Miete, Zeit-AfA</text><text x="265" y="178" text-anchor="middle" class="sk-t acc">variable Kosten</text><text x="265" y="198" text-anchor="middle" class="sk-t">Fertigungsmaterial</text><text x="435" y="178" text-anchor="middle" class="sk-t acc">Mischkosten</text><text x="435" y="198" text-anchor="middle" class="sk-t">Energie, Instandh.</text><text x="33" y="40" class="sk-t">K</text><text x="203" y="40" class="sk-t">K</text><text x="373" y="40" class="sk-t">K</text><text x="160" y="140" text-anchor="end" class="sk-t">x</text><text x="330" y="140" text-anchor="end" class="sk-t">x</text><text x="500" y="140" text-anchor="end" class="sk-t">x</text><text x="440" y="128" class="sk-t">fixer Teil</text>',cap:'Typische Gesamtkostenverläufe in Abhängigkeit von der Ausbringung x'}},
    {fx:['Kostenauflösung (Zwei-Punkt-Methode): kv = (K2 − K1) : (x2 − x1); Kf = K1 − kv · x1','trennt Mischkosten in fixen und variablen Teil']},
    {svg:{w:520,h:260,body:'<text x="40" y="38" class="sk-t acc">Aufwand (Finanzbuchhaltung)</text><rect x="40" y="48" width="160" height="50" class="sk-body"/><rect x="200" y="48" width="180" height="50" class="sk-body"/><text x="120" y="70" text-anchor="middle" class="sk-t">neutraler Aufwand</text><text x="120" y="88" text-anchor="middle" class="sk-t">(betriebsfremd, a. o.)</text><text x="290" y="78" text-anchor="middle" class="sk-t">Zweckaufwand</text><line x1="200" y1="98" x2="200" y2="150" class="sk-c"/><line x1="380" y1="98" x2="380" y2="150" class="sk-c"/><text x="290" y="130" text-anchor="middle" class="sk-t">gleicher Betrag</text><rect x="200" y="150" width="180" height="50" class="sk-body"/><rect x="380" y="150" width="120" height="50" class="sk-body"/><rect x="380" y="150" width="120" height="50" class="fillacc" opacity="0.25"/><text x="290" y="180" text-anchor="middle" class="sk-t">Grundkosten</text><text x="440" y="170" text-anchor="middle" class="sk-t">Zusatzkosten</text><text x="440" y="188" text-anchor="middle" class="sk-t">(kalkulatorisch)</text><text x="500" y="222" text-anchor="end" class="sk-t acc">Kosten (KLR)</text><text x="260" y="250" text-anchor="middle" class="sk-t">Anderskosten: gleicher Vorgang, aber anderer Wert (z. B. kalk. AfA)</text>',cap:'Abgrenzung von Aufwand und Kosten'}},
    {ul:['Grundkosten = Zweckaufwand, der in gleicher Höhe Kosten ist (Löhne, Material)','Anderskosten = in Buchhaltung und KLR unterschiedlich bewertet (kalk. AfA, kalk. Zinsen)','Zusatzkosten = ohne Aufwand in der Buchhaltung (kalk. Unternehmerlohn, kalk. Miete, kalk. Wagnisse)','Einzel- und Gemeinkosten sind immer bezogen auf ein Objekt: Gemeinkosten des Produkts können Einzelkosten einer Kostenstelle sein']},
    {bsp:{t:'Beispiel: Instandhaltungskosten auflösen',b:['Monat März: 1.200 Maschinenstunden, Instandhaltungskosten 9.800 €. Monat Mai: 1.800 Maschinenstunden, 12.200 €.','kv = (12.200 € − 9.800 €) : (1.800 h − 1.200 h) = 2.400 € : 600 h = 4,00 €/h','Kf = 9.800 € − 4,00 €/h · 1.200 h = 5.000 € je Monat','Interpretation: Für die flexible Planung gilt Instandhaltung = 5.000 € + 4,00 €/h · Maschinenstunden. Bei geplanten 1.500 h darf die Kostenstelle 11.000 € verbrauchen.']}},
    {merke:'Eine flexible Plankostenrechnung auf Vollkostenbasis ist nur mit Kostenauflösung möglich. Mischkosten werden über technische Analysen oder statistische Verfahren getrennt.'}
  ]},
  {t:'Kostenarten einer Fertigungskostenstelle',h:'Struktur der Plankostenrechnung',pg:21,b:[
    {p:'Für eine Fertigungskostenstelle werden typischerweise Personalkosten, Materialkosten, Betriebsmittelkosten, kalkulatorische Kosten, Fremdleistungen, Stelleneinzel- und -gemeinkosten sowie Umlagekosten geplant. In der Prüfung sind die Beträge meist vorgegeben – sie müssen nicht aus der Buchhaltung abgeleitet werden.'},
    {tab:[['Personalkosten','Merkmal','Einordnung'],['Fertigungslöhne (Akkord-/Zeitlohn inkl. Zuschläge)','direkt per Lohnschein dem Auftrag zugeordnet (Schweißer, Dreherin)','Einzelkosten'],['Hilfslöhne','Transport, Lager, Einrichter, Pförtner; Fertigungshilfslöhne vs. sonstige Hilfslöhne','Gemeinkosten'],['Gehälter','Zeitlohn der Angestellten, z. B. Meistergehalt','Gemeinkosten'],['gesetzliche Sozialkosten','AG-Anteile Kranken-, Pflege-, Unfall-, Arbeitslosen-, Rentenversicherung','auf Fertigungslohn Einzel-, sonst Gemeinkosten'],['freiwillige Sozialkosten','Kantinenzuschuss, Jubiläen','Gemeinkosten'],['sonstige Personalkosten','Stellenanzeigen, Vorstellungskosten, Abfindungen','Gemeinkosten']]},
    {tab:[['Materialkosten','Merkmal','Einordnung'],['Fertigungsmaterial','Hauptbestandteil des Produkts (Rohstoffe, Halbzeuge, Kaufteile)','Materialeinzelkosten – nicht in der Kostenstelle'],['Hilfsstoffe','Nebenbestandteil (Schrauben, Elektroden, Kleber)','unechte Gemeinkosten'],['Betriebsstoffe','nicht im Produkt, aber nötig (Strom, Schmierstoff, Gas, Schleifmittel)','Gemeinkosten']]},
    {ul:['Betriebsmittelkosten entstehen durch Verschleiß (Abschreibung), Instandhaltung (nach DIN 31051: Wartung, Inspektion, Instandsetzung, Verbesserung), Gebäude (Raumkosten), Energie für Antriebe und Licht, Werkzeuge und Vorrichtungen','Kleine Reparaturen durch eigenes Personal der Stelle laufen als geplante Hilfslöhne','Kalkulatorische Kosten: Abschreibungen (materiell und immateriell, z. B. Patente), Zinsen auf betriebsnotwendiges Kapital, Wagnisse, Unternehmerlohn, Miete','Fremdleistungen: Transporte, Telekommunikation, Fremdinstandhaltung, Lizenzen, Versicherungen, Prüfungen, Mieten, Steuerberatung']},
    {tab:[['Einzelwagnis','Beispiel'],['Anlagenwagnis','Ausfall durch Brand, Unfall, technischer Fortschritt'],['Fertigungswagnis','Ausschuss, Nacharbeit, Konstruktionsfehler'],['Beständewagnis','Schwund, Verderb, Veralten im Lager'],['Gewährleistungswagnis','Garantieleistungen, Ersatzteile, Preisnachlässe'],['Entwicklungswagnis','erfolglose Entwicklungsarbeit'],['Vertriebswagnis','Forderungsausfälle, Währungsverluste']]},
    {fx:['kalk. Zinsen pro Jahr = (Anschaffungskosten + Restwert) : 2 · Zinssatz','Durchschnittsverzinsung des gebundenen Kapitals']},
    {bsp:{t:'Beispiel: Kostenarten der Kostenstelle Montage zuordnen',b:['Lohn des Monteurs für Auftrag 4711 → Fertigungslohn, Einzelkosten','Lohn des Staplerfahrers → Hilfslohn, Gemeinkosten','Gehalt der Montagemeisterin → Gemeinkosten (Stelleneinzelkosten der Montage)','Sechskantschrauben M10 aus dem Kanban-Regal → Hilfsstoff, unechte Gemeinkosten','Druckluft, Schmierfett → Betriebsstoffe, Gemeinkosten','Abschreibung des Montagebands → kalkulatorische Kosten (Anderskosten)','Rechnung der Prüffirma für die Krananlage → Fremdleistung, Gemeinkosten']}},
    {merke:'Das allgemeine Unternehmerwagnis (Nachfrage, Konjunktur) wird nicht als Kosten kalkuliert – es wird durch den Gewinn abgegolten. Versicherte Risiken erzeugen keine Wagniskosten.'},
    {falle:'Kalkulatorische Miete entfällt, wenn für dieselben Räume schon kalkulatorische Abschreibungen, Zinsen und Instandhaltungskosten angesetzt sind.'}
  ]},
  {t:'Stelleneinzelkosten, Stellengemeinkosten und Umlagekosten',h:'Struktur der Plankostenrechnung',pg:24,abb:[['Kostenstellenplan einer Fertigungskostenstelle (Beispiel)',24]],b:[
    {p:'Gemeinkosten des Produkts werden in Bezug auf die Kostenstelle nochmals unterschieden: Was sich belegmäßig einer Stelle zuordnen lässt, sind Kostenstelleneinzelkosten; was mehrere Stellen gemeinsam verursachen, wird per Schlüssel verteilt (Kostenstellengemeinkosten).'},
    {tab:[['Begriff','Zuordnung','Beispiele'],['Kostenstelleneinzelkosten','direkt per Beleg oder Messung','Hilfs- und Betriebsstoffe (MES), Hilfslöhne, Gehälter, kalk. AfA und Zinsen (Anlagenkartei), Strom mit Zähler'],['Kostenstellengemeinkosten','per Verteilungsschlüssel','Personalzusatzkosten, Versicherungsprämien, Büromaterial, Grundgebühren, Gebäudemiete'],['Umlagekosten (sekundär)','Umlage der Hilfskostenstellen auf Hauptkostenstellen','Kosten von Fuhrpark, Kantine, Instandhaltung, AV']]},
    {ul:['Verteilungsschlüssel: Wert-, Zeit-, Mengen-, Vermögens-, Kapital-, Arbeitskräfteschlüssel','Ergebnis eines Kostenstellenplans je Kostenart: Einheit, Planverbrauch, Planpreis, Plankosten fix/variabel, Variator, Sollkosten, Istkosten, Verbrauchsabweichung absolut und in %']},
    {fx:['Sollkosten einer Kostenart = BG · variable Plankosten + fixe Plankosten','BG als Dezimalzahl']},
    {fx:['Verbrauchsabweichung in % = (Sollkosten − Istkosten) : Sollkosten · 100','']},
    {bsp:{t:'Beispiel: Sollkosten der Kostenart Energie im Biegezentrum',b:['Planbeschäftigung 4.000 h, Istbeschäftigung 3.600 h → BG 90 %.','Plankosten Energie 6.000 €, Variator 0,8 → variabel 4.800 €, fix 1.200 €.','Sollkosten = 0,9 · 4.800 € + 1.200 € = 4.320 € + 1.200 € = 5.520 €','Istkosten 5.880 € → VA = 5.520 € − 5.880 € = −360 € = −6,5 %.','Interpretation: Mehrverbrauch unter 10 % – beobachten; mögliche Ursache: Maschinen laufen in Pausen im Leerlauf. Maßnahme: Abschaltroutine in die Schichtübergabe aufnehmen.']}},
    {merke:'Wer von Einzel- oder Gemeinkosten spricht, muss das Bezugsobjekt nennen (Kostenträger oder Kostenstelle).'}
  ]},
  {t:'Kostenerfassung: Materialverbrauch und Bewertung',h:'Methoden der Kostenerfassung',pg:25,b:[
    {p:'Die Kostenartenrechnung erfasst alle primären Kosten belegmäßig und ordnet sie dem Kostenartenplan zu. Die Kostenarten eines Betriebs hängen ab von Größe und Art des Unternehmens, Zweck der Kostenrechnung, Kontenrahmen (GKR bzw. IKR) und Branchenempfehlungen. Ergebnisse dienen Kostenstrukturanalysen, Zeit- und Betriebsvergleichen, Kalkulation und Erfolgsrechnung.'},
    {svg:{w:520,h:250,body:'<text x="260" y="24" text-anchor="middle" class="sk-t acc">Lagerkonto Rundstahl (Stück)</text><line x1="60" y1="40" x2="460" y2="40" class="sk-l thick"/><line x1="260" y1="40" x2="260" y2="135" class="sk-l thick"/><text x="70" y="64" class="sk-t">Anfangsbestand 400</text><text x="70" y="88" class="sk-t">Zugänge 1.200</text><text x="270" y="64" class="sk-t">Verbrauch (MES) 1.350</text><text x="270" y="88" class="sk-t">Endbestand (Buch) 250</text><line x1="60" y1="102" x2="460" y2="102" class="sk-l"/><text x="70" y="122" class="sk-t">Summe 1.600</text><text x="270" y="122" class="sk-t">Summe 1.600</text><text x="20" y="170" class="sk-t">Skontration: Verbrauch aus Entnahmescheinen</text><text x="20" y="192" class="sk-t">Inventur: Verbrauch = AB + Zugänge − gezählter Endbestand</text><text x="20" y="214" class="sk-t">Retrograd: Verbrauch = Stückzahl · Sollverbrauch je Stück</text><text x="20" y="236" class="sk-t acc">Inventur zählt 236 → Fehlmenge 14 Stück (Schwund)</text>',cap:'Lagerkonto und die drei Methoden der Verbrauchsermittlung'}},
    {fx:['Skontration (Fortschreibung): Endbestand = Anfangsbestand + Zugänge − Abgänge','Abgänge belegt durch Materialentnahmescheine']},
    {fx:['Inventurmethode (Befundrechnung): Verbrauch = Anfangsbestand + Zugänge − Endbestand lt. Inventur','']},
    {fx:['Retrograde Methode: Verbrauch = hergestellte Stückzahl · Sollverbrauch je Stück','aus Stückliste oder Rezeptur inkl. Verschnitt']},
    {tab:[['Methode','Vorteile','Nachteile'],['Skontration','Zuordnung auf Auftrag und Kostenstelle, Verantwortung nachvollziehbar, Schwund durch Inventurvergleich erkennbar','hoher Erfassungsaufwand'],['Inventurmethode','kein Entnahmeschein, wenig Verwaltung','keine Zuordnung auf Stellen/Träger, häufige Inventuren, Schwund und Diebstahl unsichtbar'],['Retrograde Methode','schnell, aus Stückliste','ungenau, Gemeinkostenmaterial und Schwund nicht erfasst; nur für einfache Produkte']]},
    {ul:['Angaben auf dem Materialentnahmeschein: Auftrags-, Artikel- und Werkstoffnummer, Materialart, Menge, Abmessung/Gewicht, Lagerort, Kostenstelle/Arbeitsplatz, Belegnummer, Datum, Unterschriften von Ausgabe und Empfang','Gemeinkostenmaterial wird mit Angabe der Kostenstelle entnommen','Beste Aussagekraft: Verfahren parallel anwenden']},
    {tab:[['Bewertung','Inhalt','Einsatz'],['Anschaffungswert','Einstandspreis: Einkaufspreis − Rabatt − Skonto + Bezugskosten','Beschaffung in einem Vorgang'],['Durchschnittswert','gewogener Durchschnitt; permanent nach jedem Zugang','schwankende Einkaufspreise'],['Wiederbeschaffungswert','Preis bei Ersatzbeschaffung','lange gelagerte Güter, Großmengen'],['Tageswert','Preis am Entnahmetag','aktuelle Bewertung'],['Verrechnungspreis','fester Durchschnittswert für einen längeren Zeitraum','Plan-Ist-Vergleich, fertigungssynchrone Beschaffung']]},
    {fx:['Durchschnittswert = (Wert Anfangsbestand + Wert Zugänge) : (Menge Anfangsbestand + Menge Zugänge)','']},
    {bsp:{t:'Beispiel: Verbrauch und Bewertung von Flachstahl',b:['Skontration: Anfangsbestand 400 Stangen + Zugänge 1.200 − Entnahmen lt. MES 1.350 = Buchbestand 250 Stangen.','Inventur am Monatsende: 236 Stangen → Fehlmenge 14 Stangen (Schwund oder Entnahme ohne Beleg). Nach der Inventurmethode wäre der Verbrauch 400 + 1.200 − 236 = 1.364 Stangen – ohne Hinweis auf die Ursache.','Bewertung (anderes Lager, Blech in kg): Anfangsbestand 500 kg zu 2,40 €/kg = 1.200 €; Zugang 1.000 kg zu 2,70 € = 2.700 €; Zugang 1.500 kg zu 2,55 € = 3.825 €.','Durchschnittswert = (1.200 € + 2.700 € + 3.825 €) : 3.000 kg = 7.725 € : 3.000 kg = 2,575 €/kg ≈ 2,58 €/kg.','Interpretation: Der Meister klärt die 14 fehlenden Stangen (Ausgabe ohne MES?) und führt die Unterschriftspflicht konsequent ein.']}},
    {falle:'Die Inventurmethode zeigt nur den Gesamtverbrauch. Schwund, Verderb und Diebstahl werden erst sichtbar, wenn Buchbestand (Skontration) und Inventur verglichen werden.'}
  ]},
  {t:'Kostenerfassung: Personalkosten und Lohnformen',h:'Methoden der Kostenerfassung',pg:27,b:[
    {p:'Personalkosten (Arbeitskosten) umfassen Löhne, Gehälter, Sozialkosten und sonstige Personalkosten. Die Daten (Bruttoentgelte, AG-Anteile) kommen aus der Lohn- und Gehaltsbuchhaltung; Grundlage sind Lohnscheine, Stundenaufschreibungen und Gehaltslisten der Kostenstellen.'},
    {ul:['Lohnschein enthält u. a.: Auftrag, Artikel-/Zeichnungsnummer, Stückzahl, Losgröße, Arbeitsgang, Lohngruppe, Rüst- und Stückzeit, Vorgabezeit (Rüstzeit + Stückzahl · Stückzeit), verbrauchte Stunden, Kostenstelle, Personalnummer, Unterschriften','Nach Zurechnung: Fertigungslöhne (Einzelkosten), Hilfslöhne (Gemeinkosten), Zulagen (Erschwernis, Bereitschaft) und Zuschläge (Schicht, Nacht, Feiertag) folgen dem Grundlohn','Gehälter: Gemeinkosten, nur ausnahmsweise Einzelkosten (Projektingenieur für einen Auftrag)','Sozialkosten: gesetzliche und tarifliche (primär) sowie freiwillige (sekundär) Leistungen, je Kostenstelle als Gemeinkosten erfasst','Zeitliche Abgrenzung: Urlaubs- und Feiertagslöhne monatlich zu 1/12 verrechnen','Kalkulatorischer Unternehmerlohn: Zusatzkosten in Einzel- und Personengesellschaften, Höhe wie vergleichbares Gehalt einer Führungskraft']},
    {tab:[['Lohnform','Formel','sinnvoll bei'],['Zeitlohn','Stundensatz · geleistete Stunden','hohen Qualitätsanforderungen, nicht messbarer Leistung (Reparatur, Transport, Überwachung), Unfallgefahr'],['Geldakkord','Stückgeld · Stückzahl','wiederholbaren, messbaren Arbeiten; Nachteil: neue Werte bei jeder Tarifänderung'],['Zeitakkord','Vorgabezeit je Stück · Stückzahl · Minutenfaktor','wie Geldakkord; Vorgabezeit bleibt bei Tarifänderung gleich'],['Prämienlohn','Grundlohn + Prämie','teilweise beeinflussbarer Leistung; Mengen-, Qualitäts-, Ersparnis-, Nutzungsprämie']]},
    {fx:['Akkordrichtsatz = tariflicher Grundlohn + Akkordzuschlag','Stundenverdienst bei Normalleistung']},
    {fx:['Minutenfaktor = Akkordrichtsatz : 60','€ je Vorgabeminute']},
    {fx:['Zeitakkord-Stundenlohn = Vorgabezeit je Stück · Stück je Stunde · Minutenfaktor','']},
    {svg:{w:520,h:290,body:'<line x1="60" y1="260" x2="495" y2="260" class="sk-l" marker-end="url(#ar)"/><line x1="60" y1="260" x2="60" y2="28" class="sk-l" marker-end="url(#ar)"/><text x="68" y="36" class="sk-t">Stundenverdienst (€/h)</text><text x="505" y="282" text-anchor="end" class="sk-t">Leistung →</text><line x1="260" y1="260" x2="260" y2="40" class="sk-c"/><text x="260" y="278" text-anchor="middle" class="sk-t">Normalleistung</text><line x1="60" y1="172" x2="460" y2="172" class="sk-l thick"/><line x1="60" y1="238" x2="460" y2="62" class="sk-f"/><line x1="60" y1="227" x2="460" y2="117" class="sk-l"/><text x="440" y="55" text-anchor="end" class="sk-t acc">Akkordlohn</text><text x="455" y="150" text-anchor="end" class="sk-t">Prämienlohn</text><text x="455" y="190" text-anchor="end" class="sk-t">Zeitlohn</text>',cap:'Verdienst je Stunde: Zeitlohn konstant, Akkord proportional zur Leistung, Prämie mit flacherem Anstieg (unter Normalleistung sichert ein garantierter Mindestlohn den Akkordlohn ab)'}},
    {bsp:{t:'Beispiel: Zeit- und Akkordlohn in der Dreherei',b:['Zeitlohn: 18,50 €/h · 38 h/Woche = 703,00 € Wochenlohn.','Akkord: Grundlohn 16,00 €/h + 20 % Akkordzuschlag = Akkordrichtsatz 19,20 €/h → Minutenfaktor = 19,20 € : 60 = 0,32 €/min.','Vorgabezeit 12 min je Welle; Normalleistung also 5 Stück/h. Der Dreher schafft 6 Stück/h.','Stundenverdienst = 12 min · 6 · 0,32 €/min = 23,04 €/h (Leistungsgrad 6 : 5 = 120 %).','Geldakkord gleichwertig: Stückgeld = 12 min · 0,32 €/min = 3,84 €/Stück → 6 · 3,84 € = 23,04 €/h.','Interpretation: Mehrleistung wird proportional bezahlt; die Lohnstückkosten bleiben bei 3,84 € je Welle – für die Kalkulation konstant.']}},
    {falle:'Bei Minderleistung im Akkord sichert ein tariflich oder betrieblich garantierter Mindestverdienst ab. Akkord- und Prämiensätze unterliegen der Mitbestimmung des Betriebsrats (§ 87 Abs. 1 Nr. 11 BetrVG).'}
  ]},
  {t:'Kostenerfassung: Betriebsmittelkosten und kalkulatorische Abschreibung',h:'Methoden der Kostenerfassung',pg:29,b:[
    {p:'Betriebsmittelkosten entstehen durch Gebrauch von Grundstücken, Gebäuden, Maschinen und immateriellen Gütern (Patente, Lizenzen) sowie durch Instandhaltung, Werkzeuge und Energie. Die kalkulatorische Abschreibung erfasst den betriebsbedingten Werteverzehr – unabhängig von der steuerlichen AfA.'},
    {tab:[['Merkmal','bilanzielle Abschreibung','kalkulatorische Abschreibung'],['Umfang','gesamtes Anlagevermögen','nur betriebsnotwendige Anlagen'],['Basis','Anschaffungs-/Herstellkosten','Wiederbeschaffungswert (meist Tageswert)'],['Nutzungsdauer','AfA-Tabellen','tatsächlich erwartete Nutzung (Schichtbetrieb!)'],['Methode','linear, zeitweise degressiv','linear oder leistungsbezogen'],['Ziel','Steuer- und Handelsbilanz','Substanzerhaltung, verursachungsgerechte Kalkulation']]},
    {ul:['Ursachen des Werteverzehrs: Gebrauchsverschleiß (nutzungsabhängig → variabel) und Zeitverschleiß (Korrosion, technisches und wirtschaftliches Veralten → fix)','Ist die zeitliche Nutzungsdauer länger als die technische, sind die Abschreibungen proportional zur Leistung (variabel), sonst fix','Bestimmungsgrößen: Basiswert, Restwert (Schrott-/Liquidationserlös), Nutzungsdauer, Methode','Degressive Verfahren: geometrisch-degressiv (fester % vom Restbuchwert, Restwert nie null) und arithmetisch-degressiv','Steuerlich (Stand 2026): degressive AfA bis 30 %, höchstens das Dreifache der linearen, für bewegliche Anlagegüter mit Anschaffung 07/2025 bis 12/2027 („Investitionsbooster“); frühere Fenster 2020–2022 (25 %) und 04–12/2024 (20 %)']},
    {fx:['Wiederbeschaffungswert WBW = Anschaffungskosten · Preisindex Wiederbeschaffungsjahr : Preisindex Anschaffungsjahr','Indizes vom Statistischen Bundesamt oder Fachverbänden']},
    {fx:['lineare kalk. AfA = (WBW − Restwert) : Nutzungsdauer','Monatsbetrag = 1/12']},
    {fx:['leistungsbezogene AfA = (Basiswert − Restwert) : Gesamtleistung · Periodenleistung','am stärksten verursachungsgerecht']},
    {svg:{w:520,h:262,body:'<line x1="60" y1="220" x2="512" y2="220" class="sk-l"/><line x1="60" y1="220" x2="60" y2="30" class="sk-l" marker-end="url(#ar)"/><text x="68" y="22" class="sk-t">Restbuchwert (€)</text><rect x="75" y="50" width="34" height="170" class="fillacc"/><rect x="125" y="69.4" width="34" height="150.6" class="sk-body"/><rect x="175" y="88.9" width="34" height="131.1" class="sk-body"/><rect x="225" y="108.2" width="34" height="111.8" class="sk-body"/><rect x="275" y="127.6" width="34" height="92.4" class="sk-body"/><rect x="325" y="147" width="34" height="73" class="sk-body"/><rect x="375" y="166.4" width="34" height="53.6" class="sk-body"/><rect x="425" y="185.8" width="34" height="34.2" class="sk-body"/><rect x="475" y="205.2" width="34" height="14.8" class="sk-body"/><text x="92" y="44" text-anchor="middle" class="sk-t">92.000</text><text x="142" y="63" text-anchor="middle" class="sk-t">81.500</text><text x="192" y="83" text-anchor="middle" class="sk-t">71.000</text><text x="242" y="102" text-anchor="middle" class="sk-t">60.500</text><text x="292" y="121" text-anchor="middle" class="sk-t">50.000</text><text x="342" y="141" text-anchor="middle" class="sk-t">39.500</text><text x="392" y="160" text-anchor="middle" class="sk-t">29.000</text><text x="442" y="179" text-anchor="middle" class="sk-t">18.500</text><text x="492" y="199" text-anchor="middle" class="sk-t">8.000</text><text x="92" y="236" text-anchor="middle" class="sk-t">0</text><text x="142" y="236" text-anchor="middle" class="sk-t">1</text><text x="192" y="236" text-anchor="middle" class="sk-t">2</text><text x="242" y="236" text-anchor="middle" class="sk-t">3</text><text x="292" y="236" text-anchor="middle" class="sk-t">4</text><text x="342" y="236" text-anchor="middle" class="sk-t">5</text><text x="392" y="236" text-anchor="middle" class="sk-t">6</text><text x="442" y="236" text-anchor="middle" class="sk-t">7</text><text x="492" y="236" text-anchor="middle" class="sk-t">8</text><text x="290" y="256" text-anchor="middle" class="sk-t">Jahr – jährlich 10.500 € kalkulatorische Abschreibung</text>',cap:'Lineare kalkulatorische Abschreibung einer CNC-Drehmaschine vom Wiederbeschaffungswert bis zum Restwert'}},
    {bsp:{t:'Beispiel: Kalkulatorische Abschreibung einer CNC-Drehmaschine',b:['Anschaffung 80.000 €, Preisindex im Anschaffungsjahr 100 %, für das Ersatzjahr erwartet 115 %; Nutzungsdauer im Zweischichtbetrieb 8 Jahre; erwarteter Verkaufserlös am Ende 8.000 €.','WBW = 80.000 € · 115 : 100 = 92.000 €','lineare AfA = (92.000 € − 8.000 €) : 8 Jahre = 10.500 €/Jahr = 875 €/Monat','Leistungsbezogen (anderes Gerät): Gabelstapler 36.000 €, kein Restwert, Gesamtleistung 12.000 Betriebsstunden, im 1. Jahr 2.800 h → 36.000 € : 12.000 h · 2.800 h = 8.400 €.','Interpretation: Über die Preise werden in 8 Jahren 84.000 € AfA verdient; zusammen mit dem Restwert reicht das für die teurere Ersatzmaschine (Substanzerhaltung).']}},
    {falle:'Kalkulatorische AfA vom Wiederbeschaffungswert, kalkulatorische Zinsen dagegen vom halben Anschaffungswert (plus halber Restwert). Und: Die steuerliche degressive AfA spielt für die Kostenrechnung keine Rolle.'}
  ]},
  {t:'Kostenerfassung: Instandhaltung, Werkzeuge, Energie, Raum, Zinsen, Steuern, Wagnisse',h:'Methoden der Kostenerfassung',pg:33,b:[
    {p:'Neben der Abschreibung gehören weitere Kostenarten zu den Betriebsmitteln. Für jede gibt es typische Planungsformeln, die in Maschinenstundensätzen wieder auftauchen.'},
    {fx:['jährliche Instandhaltungskosten = Anschaffungswert bzw. WBW · Instandhaltungsfaktor','Faktor aus Branchenkatalogen; aufteilbar in Material, Fremdleistung, eigene Instandhaltung']},
    {fx:['Energieverbrauch (kWh) = Anschlussleistung (kW) · Einsatzzeit (h) · Auslastungsfaktor','Energiekosten = Verbrauch · Arbeitspreis + anteilige Grundgebühr']},
    {fx:['Raumkosten = Flächenbedarf (m²) · kalkulatorischer Mietsatz (€/m²)','Maschinenfläche plus Bedien- und Bereitstellungsflächen']},
    {fx:['kalk. Zinsen = (Anschaffungskosten + Restwert) : 2 · Zinssatz','Zinssatz langfristiger Kapitalanlagen']},
    {fx:['Wagnissatz = Summe Wagnisverluste : Summe Bezugsgröße (3–5 Jahre) · 100; Wagniskosten = Wagnissatz · Bezugsgröße','']},
    {tab:[['Wagnis','Bezugsgröße'],['Anlagenwagnis','Anschaffungs- bzw. Herstellwert'],['Fertigungswagnis','Herstellkosten (Material- und Fertigungskosten des Ausschusses)'],['Beständewagnis','Lagerbestand'],['Gewährleistungswagnis','Umsatz, Herstellkosten'],['Entwicklungswagnis','Entwicklungskosten'],['Vertriebswagnis','Umsatz bzw. Forderungsbestand']]},
    {ul:['Inspektion und Wartung sind gut planbar (Wartungspläne); Reparaturen hängen von Alter, Wartungszustand und Auslastung ab','Werkzeuge: geringwertige als Materialkosten, hochwertige Werkzeuge und Vorrichtungen wie Maschinen mit AfA und Instandhaltung','Energieplanung: Schätzung aus Vorperioden, Messung an Anlagen oder Berechnung aus Verbrauchern, Anschlusswerten, Auslastung und Einsatzzeiten','Raumkosten: keine kalkulatorischen Raumkosten, wenn schon AfA, Zinsen, Versicherung, Grundsteuer und Erhaltung für die Räume angesetzt sind; gezahlte Miete = Dienstleistungskosten','Dienstleistungskosten (Fremdleistungen) sind meist Gemeinkosten und werden per Rechnung erfasst','Kostensteuern (Grund-, Kfz-, Gewerbesteuer): Gemeinkosten; Verbrauchsteuern: Sondereinzelkosten des Vertriebs; Gewerbesteuer vor Veranlagung geschätzt','Gute Daten entstehen nur im Zusammenspiel von Lohn-, Anlagen- und Materialbuchhaltung mit Kostenarten-, -stellen- und -trägerrechnung']},
    {bsp:{t:'Beispiel: Kosten rund um eine Fräsmaschine',b:['Instandhaltung: WBW 92.000 € · 5 % = 4.600 €/Jahr; davon Material 30 % = 1.380 €, Fremdleistung 45 % = 2.070 €, eigene Instandhaltung 25 % = 1.150 €.','Energie (Monat): Fräsmaschine 22 kW · 160 h · 0,7 = 2.464 kWh; Beleuchtung/Absaugung 4 kW · 200 h = 800 kWh; gesamt 3.264 kWh · 0,24 €/kWh = 783,36 € + Grundgebühranteil 40,00 € = 823,36 €.','Raum: 45 m² · 9,50 €/m² = 427,50 € je Monat.','Fertigungswagnis: Ausschussverluste der letzten 4 Jahre 38.000 € bei Herstellkosten von 1.900.000 € → Wagnissatz 2 %; bei geplanten Herstellkosten von 520.000 € → 10.400 € Wagniskosten.','Interpretation: Jede dieser Zahlen kann der Meister beeinflussen – Leerlauf abschalten, Wartungsplan einhalten, Ausschuss senken.']}},
    {merke:'Nicht versicherte Einzelrisiken werden als kalkulatorische Wagnisse verrechnet und den verursachenden Kostenstellen zugeordnet; versicherte Risiken stecken schon in der Versicherungsprämie.'}
  ]},
  {t:'Zuordnung der Kosten auf Kostenstellen',h:'Methoden der Kostenerfassung',pg:36,b:[
    {p:'Zahl, Art und Tiefe der Kostenstellen folgen aus Größe und Aufbauorganisation des Betriebs. Je feiner gegliedert, desto genauer die Zurechnung auf Produkte und desto wirksamer die Kostenkontrolle am Ort der Entstehung – bis hin zum einzelnen Arbeitsplatz.'},
    {tab:[['Bereich','typische Kostenstellen'],['allgemeiner Bereich','Energieerzeugung, Werkfeuerwehr, Betriebsrat, Kantine, Gebäude'],['Material','Einkauf, Wareneingang, Lager, Materialausgabe (in kleinen Betrieben eine Stelle)'],['Fertigung','Hauptstellen (Dreherei, Fräserei), Unterstellen (Bearbeitungszentren), Fertigungshilfsstellen (Konstruktion, AV, Vorrichtungsbau, Instandhaltung, Transport)'],['Verwaltung','Leitung, Personal, KLR, Finanzbuchhaltung, Organisation, Revision'],['Vertrieb','Verkauf, Versand, Kundendienst, Werbung']]},
    {tab:[['Kostenstellenart','Merkmal'],['Hauptkostenstelle','direkt an Beschaffung, Fertigung, Verwaltung oder Vertrieb der Produkte beteiligt; Kosten gehen über Zuschläge auf die Kostenträger'],['Hilfskostenstelle','erbringt innerbetriebliche Leistungen; Kosten werden auf Hauptstellen umgelegt'],['Unterkostenstelle','Teil einer Hauptstelle, z. B. Maschinengruppe, für genauere Kontrolle und Kalkulation'],['Nebenkostenstelle','Nebenprodukte oder Nebenleistungen (Späneaufbereitung, Werkswohnungen)']]},
    {bsp:{t:'Beispiel: Kostenstellen eines Metallbetriebs mit 120 Beschäftigten',b:['Allgemein: 100 Gebäude/Energie, 110 Fuhrpark, 120 Kantine','Material: 200 Einkauf und Lager','Fertigung: 310 Arbeitsvorbereitung (Hilfsstelle), 320 Instandhaltung (Hilfsstelle), 330 Dreherei mit Unterstellen 331 CNC-Drehen und 332 konventionell, 340 Schweißerei, 350 Montage','Verwaltung: 400; Vertrieb: 500','Interpretation: Die Meisterin der Dreherei verantwortet 330 bis 332; die Umlage von 310 und 320 kann sie nur über den Bedarf an AV- und Instandhaltungsleistungen beeinflussen.']}},
    {merke:'Kostenstelle = Ort der Entstehung, der Beeinflussung und der Verantwortung. Ohne klaren Verantwortlichen keine wirksame Kostenkontrolle.'}
  ]},
  {t:'Betriebsabrechnungsbogen: Aufbau und Primärkostenverteilung',h:'Verrechnung der Kostenarten auf Kostenstellen im Betriebsabrechnungsbogen',pg:37,abb:[['Abb. 1.3 Schema BAB',37]],b:[
    {p:'Der BAB ist das klassische Werkzeug der Kostenstellenrechnung – heute meist als Bericht aus der Software, die Logik ist dieselbe. Er übernimmt die Gemeinkosten aus der Kostenartenrechnung, verteilt sie vollständig auf die Kostenstellen, rechnet die Hilfsstellen auf die Hauptstellen um und bildet Zuschlagssätze. Er ist das Bindeglied zwischen Kostenarten- und Kostenträgerrechnung.'},
    {svg:{w:520,h:250,body:'<rect x="20" y="15" width="220" height="36" class="sk-body"/><text x="130" y="38" text-anchor="middle" class="sk-t acc">Kostenartenrechnung</text><line x1="130" y1="51" x2="130" y2="73" class="sk-f" marker-end="url(#ar)"/><text x="138" y="67" class="sk-t">Gemeinkosten</text><rect x="20" y="75" width="220" height="36" class="sk-body"/><text x="130" y="98" text-anchor="middle" class="sk-t">1 Primärkosten verteilen</text><line x1="130" y1="111" x2="130" y2="133" class="sk-f" marker-end="url(#ar)"/><rect x="20" y="135" width="220" height="36" class="sk-body"/><text x="130" y="158" text-anchor="middle" class="sk-t">2 Hilfsstellen umlegen</text><line x1="130" y1="171" x2="130" y2="193" class="sk-f" marker-end="url(#ar)"/><rect x="20" y="195" width="220" height="36" class="sk-body"/><text x="130" y="218" text-anchor="middle" class="sk-t">3 Zuschlagssätze bilden</text><line x1="240" y1="213" x2="298" y2="213" class="sk-f" marker-end="url(#ar)"/><rect x="300" y="195" width="200" height="36" class="sk-body"/><text x="400" y="218" text-anchor="middle" class="sk-t acc">Kostenträgerrechnung</text><line x1="240" y1="33" x2="400" y2="33" class="sk-l"/><line x1="400" y1="33" x2="400" y2="193" class="sk-l" marker-end="url(#ar)"/><text x="392" y="110" text-anchor="end" class="sk-t">Einzelkosten direkt</text><rect x="300" y="135" width="90" height="36" class="sk-body"/><text x="345" y="158" text-anchor="middle" class="sk-t">4 Kontrolle</text><line x1="240" y1="200" x2="298" y2="165" class="sk-c"/>',cap:'Ablauf der Kostenstellenrechnung im BAB; Einzelkosten gehen direkt auf die Kostenträger, Schritt 4 vergleicht Ist- und Normalgemeinkosten'}},
    {ol:['Primärkostenrechnung: Gemeinkosten direkt (Belege) oder per Schlüssel auf alle Kostenstellen verteilen','Sekundärkostenrechnung: innerbetriebliche Leistungsverrechnung von Hilfs- auf Hauptkostenstellen','Zuschlags- bzw. Verrechnungssätze bilden (Ist)','Kostenkontrolle: Ist- mit Normalgemeinkosten vergleichen → Kostenüber- und -unterdeckung']},
    {tab:[['Direkte Zurechnung (Stelleneinzelkosten)','Beleg'],['Hilfs- und Betriebsstoffe','Materialentnahmeschein'],['Hilfslöhne, Gehälter','Lohn- und Gehaltslisten'],['kalk. Abschreibung und Zinsen','Anlagenkartei'],['Fremdreparaturen','Rechnung']]},
    {ul:['Stellengemeinkosten werden per Schlüssel verteilt: Mengenschlüssel (Köpfe, Stunden, m², kg, kW-Anschlusswert, km) oder Wertschlüssel (Lohnsumme, Umsatz, Bestand, Anlagewert)','Der Schlüssel muss eine Ursache-Wirkungs-Beziehung haben oder zumindest plausibel sein','Unechte Stellengemeinkosten: genau erfassbar, aber zu teuer (z. B. ein Stromzähler je Stelle) – Aufwand gegen Nutzen abwägen','Kosten wie Gebäude-AfA, Reinigung, Heizung und Hausmeister können auf einer eigenen Gebäudekostenstelle gesammelt und nach m² weiterverrechnet werden']},
    {bsp:{t:'Beispiel: Primärkostenverteilung in einem Monats-BAB (Werte in €)',b:['Kostenstellen: Fuhrpark (FP) und Instandhaltung (IH) als Hilfsstellen; Material, Fertigung I (Drehen), Fertigung II (Montage), Verwaltung, Vertrieb als Hauptstellen.','Hilfslöhne, Gehälter, Hilfs- und Betriebsstoffe: direkt laut Belegen.','Miete 36.000 € nach Fläche: 6.000 m² → 6,00 €/m² (z. B. Fertigung I: 1.800 m² · 6 € = 10.800 €).','kalk. Abschreibung 48.000 € nach Anlagewerten von 2,4 Mio. € → 2 % (z. B. Fertigung I: 1,1 Mio. € · 2 % = 22.000 €).']}},
    {tab:[['Kostenart','Summe','FP','IH','Mat','F I','F II','Vw','Vt'],['Hilfslöhne','60.000','8.200','14.000','6.000','16.000','10.000','1.800','4.000'],['Gehälter','90.000','0','6.000','9.000','12.000','8.000','35.000','20.000'],['Hilfs-/Betriebsstoffe','24.000','5.000','3.000','1.000','8.000','6.000','500','500'],['Miete (m²)','36.000','1.800','2.400','5.400','10.800','9.000','3.600','3.000'],['kalk. AfA','48.000','3.000','2.000','3.000','22.000','14.000','2.400','1.600'],['Primärkosten','258.000','18.000','27.400','24.400','68.800','47.000','43.300','29.100']]},
    {merke:'Nach der Primärkostenverteilung sind alle Gemeinkosten auf Kostenstellen verteilt, aber noch nicht alle auf Hauptstellen. Die Summe der Gemeinkosten bleibt in jedem Schritt gleich (hier 258.000 €).'}
  ]},
  {t:'Innerbetriebliche Leistungsverrechnung',h:'Verrechnung der Kostenarten auf Kostenstellen im Betriebsabrechnungsbogen',pg:38,abb:[['Abb. 1.4 Innerbetriebliche Leistungsverrechnung',39],['Abb. 1.5 Umlageverfahren der innerbetrieblichen Leistungsverrechnung',39]],b:[
    {p:'Innerbetriebliche Leistungen werden im eigenen Betrieb erstellt und verbraucht – vor allem von allgemeinen Kostenstellen (Strom, Werkschutz, Kantine, Rechenzentrum) und Fertigungshilfsstellen (AV, Instandhaltung, Labor). Die leistende Stelle wird entlastet (Gutschrift), die empfangende belastet (Lastschrift), bewertet mit einem Verrechnungspreis.'},
    {tab:[['Art','Beispiele','Behandlung'],['aktivierungsfähig/-pflichtig','selbst gebaute Maschinen, Vorrichtungen, Werkzeuge, Gebäude','wie Absatzleistung als Kostenträger zu Herstellkosten aktivieren; später über kalk. AfA und Zinsen verrechnet'],['nicht aktivierungsfähig','Strom, Fertigungspläne, Kantinenessen, interne Schulung','in derselben Periode verbraucht; Primärkosten der leistenden Stelle werden Sekundärkosten der empfangenden']]},
    {tab:[['Verfahren','Prinzip','Bewertung'],['Anbauverfahren','Hilfsstellen geben nur an Hauptstellen ab; Reihenfolge egal','einfach, ignoriert Leistungen zwischen Hilfsstellen'],['Stufenleiter-/Treppenverfahren','Hilfsstellen geben an Hauptstellen und nachgelagerte Hilfsstellen ab, nie zurück','genauer; Reihenfolge so wählen, dass vorgelagerte Stellen kaum etwas empfangen'],['Gleichungs-, Festpreisverfahren','gegenseitige Leistungen werden voll berücksichtigt','genau, aber aufwendig']]},
    {fx:['Verrechnungspreis (Anbau) = Primärkosten der Hilfsstelle : Leistungsabgabe an Hauptstellen','']},
    {fx:['Verrechnungspreis (Stufenleiter) = (Primärkosten + bereits erhaltene Sekundärkosten) : Leistungsabgabe an nachgelagerte Stellen','']},
    {svg:{w:520,h:250,body:'<rect x="20" y="20" width="140" height="40" class="sk-body"/><text x="90" y="45" text-anchor="middle" class="sk-t acc">Hilfs-KSt A</text><rect x="190" y="95" width="140" height="40" class="sk-body"/><text x="260" y="120" text-anchor="middle" class="sk-t acc">Hilfs-KSt B</text><line x1="160" y1="48" x2="198" y2="93" class="sk-f" marker-end="url(#ar)"/><line x1="90" y1="60" x2="90" y2="170" class="sk-f"/><line x1="260" y1="135" x2="260" y2="170" class="sk-f"/><line x1="65" y1="170" x2="455" y2="170" class="sk-f"/><line x1="65" y1="170" x2="65" y2="188" class="sk-f" marker-end="url(#ar)"/><line x1="195" y1="170" x2="195" y2="188" class="sk-f" marker-end="url(#ar)"/><line x1="325" y1="170" x2="325" y2="188" class="sk-f" marker-end="url(#ar)"/><line x1="455" y1="170" x2="455" y2="188" class="sk-f" marker-end="url(#ar)"/><rect x="10" y="192" width="110" height="40" class="sk-body"/><rect x="140" y="192" width="110" height="40" class="sk-body"/><rect x="270" y="192" width="110" height="40" class="sk-body"/><rect x="400" y="192" width="110" height="40" class="sk-body"/><text x="65" y="217" text-anchor="middle" class="sk-t">Material</text><text x="195" y="217" text-anchor="middle" class="sk-t">Fertigung</text><text x="325" y="217" text-anchor="middle" class="sk-t">Verwaltung</text><text x="455" y="217" text-anchor="middle" class="sk-t">Vertrieb</text><text x="345" y="40" class="sk-t">Reihenfolge festlegen:</text><text x="345" y="58" class="sk-t">zuerst die Stelle, die</text><text x="345" y="76" class="sk-t">am wenigsten empfängt</text>',cap:'Stufenleiterverfahren: A belastet B und die Hauptstellen, B gibt nichts an A zurück'}},
    {bsp:{t:'Beispiel: Anbau- und Stufenleiterverfahren im Vergleich',b:['Hilfsstelle Stromerzeugung: Primärkosten 10.000 €, Abgabe 50.000 kWh – davon 10.000 kWh an die Hilfsstelle Werkstatt, 40.000 kWh an Hauptstellen. Werkstatt: Primärkosten 8.000 €, 200 h an Hauptstellen.','Anbau: Strom 10.000 € : 40.000 kWh = 0,25 €/kWh; Werkstatt 8.000 € : 200 h = 40,00 €/h.','Stufenleiter (Strom zuerst): 10.000 € : 50.000 kWh = 0,20 €/kWh; Werkstatt erhält 10.000 kWh · 0,20 € = 2.000 € → (8.000 € + 2.000 €) : 200 h = 50,00 €/h.','Interpretation: Beide Verfahren verteilen insgesamt 18.000 € auf die Hauptstellen. Das Anbauverfahren rechnet die Werkstattstunde aber um 10 € zu billig – wer viele Werkstattleistungen nutzt, wird zu gering belastet.']}},
    {bsp:{t:'Beispiel: Fortsetzung des Monats-BAB (Stufenleiterverfahren)',b:['Fuhrpark zuerst: 18.000 € : 20.000 km = 0,90 €/km; Abgabe an IH 2.000 km, Material 6.000, F I 1.000, F II 1.000, Vw 2.000, Vt 8.000 km.','Instandhaltung danach: (27.400 € + 1.800 €) : 800 h = 36,50 €/h; Abgabe an Material 50 h, F I 450 h, F II 300 h.']}},
    {tab:[['Schritt','FP','IH','Mat','F I','F II','Vw','Vt'],['Primärkosten','18.000','27.400','24.400','68.800','47.000','43.300','29.100'],['Umlage FP 0,90 €/km','−18.000','1.800','5.400','900','900','1.800','7.200'],['Zwischensumme','0','29.200','29.800','69.700','47.900','45.100','36.300'],['Umlage IH 36,50 €/h','','−29.200','1.825','16.425','10.950','0','0'],['Endkosten','0','0','31.625','86.125','58.850','45.100','36.300']]},
    {falle:'Beim Stufenleiterverfahren immer die bereits empfangenen Sekundärkosten in den Verrechnungspreis einrechnen und die eigene Leistung an schon abgerechnete Stellen weglassen. Kontrolle: Summe der Endkosten = Summe der Primärkosten.'}
  ]},
  {t:'Zuschlagssätze, Normalkosten und Kostenüber-/-unterdeckung',h:'Verrechnung der Kostenarten auf Kostenstellen im Betriebsabrechnungsbogen',pg:40,b:[
    {p:'Aus den Endkosten der Hauptstellen werden Kalkulationssätze gebildet: Verrechnungssätze auf Mengenbasis (€/h, €/kg) oder Zuschlagssätze auf Wertbasis (%). Logik: Wer viel Material und Lohn verursacht, trägt auch viele Material- und Fertigungsgemeinkosten; Verwaltung und Vertrieb belasten Produkte nach ihren Herstellkosten.'},
    {fx:['MGKZ = Materialgemeinkosten : Fertigungsmaterial · 100','']},
    {fx:['FGKZ = Fertigungsgemeinkosten : Fertigungslöhne · 100','je Fertigungsstelle ein eigener Satz']},
    {fx:['VwGKZ = Verwaltungsgemeinkosten : Herstellkosten des Umsatzes · 100; VtGKZ = Vertriebsgemeinkosten : HKU · 100','']},
    {fx:['HKE = FM + MGK + FL + FGK; HKU = HKE + Bestandsminderung − Bestandsmehrung','Bestände sind zu Herstellkosten bewertet']},
    {fx:['Normalgemeinkosten = Ist-Zuschlagsgrundlage · Normalzuschlagssatz','Normal-MGK auf Ist-FM, Normal-FGK auf Ist-FL, Normal-VwGK/VtGK auf Normal-HKU']},
    {fx:['Kostenüber-/-unterdeckung = Normalgemeinkosten − Istgemeinkosten','> 0 Überdeckung, < 0 Unterdeckung']},
    {ul:['Normalkosten = Durchschnittskosten der Vergangenheit bzw. Kosten, die normalerweise hätten anfallen dürfen','Zweck 1: Vergleichsmaßstab für die Istkosten einer Stelle. Zweck 2: Zuschlagssätze für die Vorkalkulation, weil Istsätze vorher nicht vorliegen und schwanken','Ursachen von Abweichungen: Preisabweichungen (teureres Material), Verbrauchsabweichungen (Verschnitt), Beschäftigungsabweichungen (Konjunkturdelle)','Material-, Verwaltungs- und Vertriebsstellen werden für den Zuschlag meist zu Bereichen zusammengefasst; in der Fertigung oft je Stelle ein eigener Satz']},
    {bsp:{t:'Beispiel: Ist-Zuschlagssätze aus dem Monats-BAB',b:['Einzelkosten: Fertigungsmaterial 300.000 €, Fertigungslöhne F I 40.000 €, F II 30.000 €; Bestandsmehrung an fertigen Erzeugnissen 10.000 €.','MGKZ = 31.625 € : 300.000 € · 100 = 10,54 %','FGKZ I = 86.125 € : 40.000 € · 100 = 215,31 %; FGKZ II = 58.850 € : 30.000 € · 100 = 196,17 %','HKE = 300.000 + 31.625 + 40.000 + 86.125 + 30.000 + 58.850 = 546.600 €; HKU = 546.600 € − 10.000 € = 536.600 €','VwGKZ = 45.100 € : 536.600 € · 100 = 8,40 %; VtGKZ = 36.300 € : 536.600 € · 100 = 6,76 %','Selbstkosten des Umsatzes (Ist) = 536.600 € + 45.100 € + 36.300 € = 618.000 €']}},
    {bsp:{t:'Beispiel: Normalkosten und Über-/Unterdeckung',b:['Normalzuschläge aus den Vorjahren: Material 10 %, F I 210 %, F II 200 %, Verwaltung 8 %, Vertrieb 7 %.']}},
    {tab:[['Stelle','Basis €','Normal-GK €','Ist-GK €','Differenz €'],['Material (10 %)','300.000','30.000','31.625','−1.625'],['Fertigung I (210 %)','40.000','84.000','86.125','−2.125'],['Fertigung II (200 %)','30.000','60.000','58.850','+1.150'],['Verwaltung (8 %)','534.000','42.720','45.100','−2.380'],['Vertrieb (7 %)','534.000','37.380','36.300','+1.080'],['Summe','','254.100','258.000','−3.900']]},
    {p:'Normal-HKE = 300.000 + 30.000 + 40.000 + 84.000 + 30.000 + 60.000 = 544.000 €; Normal-HKU = 534.000 €; Normal-Selbstkosten = 534.000 + 42.720 + 37.380 = 614.100 €. Die Kalkulation mit Normalsätzen hat 3.900 € zu wenig Kosten verrechnet (618.000 € − 614.100 €).'},
    {p:'Interpretation: Unterdeckungen in Material, Fertigung I und Verwaltung prüfen – etwa höhere Hilfslöhne, ungeplante Reparaturen, Gehaltserhöhung. Überdeckungen (Fertigung II, Vertrieb) können auf gute Auslastung oder auf zu hohe Normalsätze hindeuten. Die Gesamtunterdeckung mindert das Betriebsergebnis.'},
    {merke:'Normalkosten vergleichen Ist mit dem Durchschnitt der Vergangenheit – also möglicherweise Unwirtschaftlichkeit mit Unwirtschaftlichkeit. Objektive Maßstäbe liefern erst Plan- bzw. Sollkosten.'},
    {falle:'Verwaltungs- und Vertriebszuschlag beziehen sich auf die Herstellkosten des Umsatzes (Bestandsmehrung abziehen, Bestandsminderung addieren). Normal-VwGK und -VtGK werden auf die Normal-HKU gerechnet, nicht auf die Ist-HKU.'}
  ]},
  {t:'Wirtschaftlichkeitsrechnung und statische Investitionsrechnung',h:'Methoden der Wirtschaftlichkeitsberechnung auf der Basis von Kosten- und Erlösdaten',pg:48,b:[
    {p:'Die Investitionsrechnung beurteilt, ob eine Investition notwendig und zweckmäßig ist. Statische Verfahren rechnen mit Durchschnittswerten einer Periode und beantworten drei Fragen: Ist sie wirtschaftlich (Kosten)? Ist sie rentabel (Verzinsung)? Wie riskant ist sie (Amortisation)?'},
    {tab:[['Investitionsart','Anlass'],['Erstinvestition','neue Fertigung, die es im Betrieb noch nicht gibt'],['Ersatzinvestition','Anlage ist verschlissen oder nicht mehr einsetzbar'],['Rationalisierungsinvestition','leistungsfähigere Anlage senkt die Kosten'],['Erweiterungsinvestition','zusätzliche Kapazität']]},
    {fx:['Kostenvergleich: K = Kf + kv · x je Alternative; Kf = AfA + kalk. Zinsen + sonstige Fixkosten','die Alternative mit den geringeren Kosten je Periode oder je Stück wählen']},
    {fx:['kritische Menge = (Kf B − Kf A) : (kv A − kv B)','ab hier ist die Anlage mit den höheren Fixkosten günstiger']},
    {fx:['Rentabilität in % = Gewinn bzw. Kostenersparnis pro Jahr : durchschnittlich gebundenes Kapital · 100','Ø Kapital = (Anschaffungskosten + Restwert) : 2']},
    {fx:['Amortisationsdauer in Jahren = (Anschaffungskosten − Restwert) : (Gewinn bzw. Kostenersparnis + Abschreibung)','Rückfluss pro Jahr; je kürzer, desto geringer das Risiko']},
    {svg:{w:520,h:280,body:'<line x1="60" y1="240" x2="495" y2="240" class="sk-l" marker-end="url(#ar)"/><line x1="60" y1="240" x2="60" y2="20" class="sk-l" marker-end="url(#ar)"/><text x="68" y="28" class="sk-t">Kosten (€)</text><text x="505" y="274" text-anchor="end" class="sk-t">Stückzahl je Jahr</text><line x1="60" y1="186.8" x2="480" y2="58.8" class="sk-l thick"/><line x1="60" y1="158" x2="480" y2="78" class="sk-f"/><line x1="312" y1="240" x2="312" y2="110" class="sk-c"/><circle cx="312" cy="110" r="5" class="fillacc"/><text x="480" y="50" text-anchor="end" class="sk-t">Maschine A</text><text x="480" y="114" text-anchor="end" class="sk-t acc">Maschine B</text><text x="55" y="191" text-anchor="end" class="sk-t">26.600</text><text x="55" y="162" text-anchor="end" class="sk-t">41.000</text><text x="312" y="256" text-anchor="middle" class="sk-t">kritische Menge 9.600 St.</text><text x="186" y="228" text-anchor="middle" class="sk-t">A günstiger</text><text x="400" y="228" text-anchor="middle" class="sk-t">B günstiger</text>',cap:'Kostenvergleichsrechnung zweier Maschinen mit kritischer Menge'}},
    {bsp:{t:'Beispiel: Kostenvergleich zweier Drehautomaten',b:['Maschine A: Anschaffung 120.000 €, 8 Jahre, kein Restwert, sonstige Fixkosten 8.000 €/Jahr, variable Kosten 4,00 €/Stück. Maschine B: 200.000 €, 8 Jahre, sonstige Fixkosten 10.000 €/Jahr, 2,50 €/Stück. Kalkulationszins 6 %; Bedarf 12.000 Stück/Jahr.','Fixkosten A = 120.000 € : 8 + 120.000 € : 2 · 0,06 + 8.000 € = 15.000 + 3.600 + 8.000 = 26.600 €','Fixkosten B = 200.000 € : 8 + 200.000 € : 2 · 0,06 + 10.000 € = 25.000 + 6.000 + 10.000 = 41.000 €','Kosten bei 12.000 Stück: A = 26.600 € + 4,00 € · 12.000 = 74.600 €; B = 41.000 € + 2,50 € · 12.000 = 71.000 €','kritische Menge = (41.000 € − 26.600 €) : (4,00 € − 2,50 €) = 14.400 € : 1,50 € = 9.600 Stück','Interpretation: Bei 12.000 Stück spart B 3.600 € im Jahr. Fällt der Bedarf dauerhaft unter 9.600 Stück, wäre A die bessere Wahl – Absatzprognose kritisch prüfen.']}},
    {bsp:{t:'Beispiel: Rentabilität und Amortisation einer Spannvorrichtung',b:['Eine automatische Spannvorrichtung kostet 120.000 €, Nutzungsdauer 6 Jahre, kein Restwert. Sie spart jährlich 30.000 € Lohn- und Rüstkosten.','Ø gebundenes Kapital = 120.000 € : 2 = 60.000 €; Rentabilität = 30.000 € : 60.000 € · 100 = 50 %','Abschreibung = 120.000 € : 6 = 20.000 €/Jahr; Amortisation = 120.000 € : (30.000 € + 20.000 €) = 2,4 Jahre','Interpretation: Fordert die Geschäftsleitung mindestens 25 % Rentabilität und höchstens 3 Jahre Amortisation, ist die Investition zu empfehlen.']}},
    {merke:'Nicht die niedrigsten Anschaffungskosten entscheiden, sondern die Gesamtkosten bei der geplanten Menge, die Verzinsung und das Risiko. Rentabilität bezieht sich immer auf ein Jahr und auf das durchschnittlich gebundene Kapital.'},
    {falle:'In der Amortisationsrechnung gehört die Abschreibung zum Rückfluss dazu (sie ist Kostenbestandteil ohne Auszahlung). Wer nur die Ersparnis nimmt, rechnet die Amortisation zu lang.'}
  ]},
  {t:'Prozesskostenrechnung',h:'Kostenverrechnung und Kalkulation mit Prozesskosten',pg:50,b:[
    {p:'Bei hohen Gemeinkostenzuschlägen kalkuliert die Zuschlagsrechnung falsch: Großserien bekommen zu viele Gemeinkosten, Kleinmengen und Exoten zu wenige. Die Prozesskostenrechnung verteilt die Gemeinkosten indirekter Bereiche (Einkauf, Lager, Versand, AV, Abrechnung) nach der tatsächlichen Inanspruchnahme von Prozessen.'},
    {tab:[['Begriff','Bedeutung','Beispiel'],['Aktivität / Teilprozess / Hauptprozess','Tätigkeiten werden zu Teilprozessen, diese zu Hauptprozessen gebündelt','Angebot einholen → Bestellung → Beschaffung'],['lmi-Prozess','leistungsmengeninduziert: Kosten steigen mit der Prozessmenge','Bestellungen, Störmeldungen bearbeiten'],['lmn-Prozess','leistungsmengenneutral: unabhängig von der Menge','Abteilung leiten, Mitarbeitende schulen'],['Kostentreiber','Maßgröße für die Inanspruchnahme','Anzahl Bestellungen, Aufträge, Varianten'],['Prozesskostensatz','Kosten je einmaliger Durchführung','€ je Bestellung']]},
    {svg:{w:520,h:230,body:'<rect x="10" y="20" width="110" height="74" class="sk-body"/><rect x="140" y="20" width="110" height="74" class="sk-body"/><rect x="270" y="20" width="110" height="74" class="sk-body"/><rect x="400" y="20" width="110" height="74" class="sk-body"/><text x="65" y="50" text-anchor="middle" class="sk-t">Tätigkeits-</text><text x="65" y="68" text-anchor="middle" class="sk-t">analyse</text><text x="195" y="50" text-anchor="middle" class="sk-t">Teilprozesse</text><text x="195" y="68" text-anchor="middle" class="sk-t">lmi / lmn</text><text x="325" y="50" text-anchor="middle" class="sk-t">Kostentreiber</text><text x="325" y="68" text-anchor="middle" class="sk-t">+ Prozessmenge</text><text x="455" y="44" text-anchor="middle" class="sk-t acc">Prozess-</text><text x="455" y="62" text-anchor="middle" class="sk-t acc">kostensatz</text><text x="455" y="80" text-anchor="middle" class="sk-t">+ lmn-Umlage</text><line x1="120" y1="57" x2="138" y2="57" class="sk-f" marker-end="url(#ar)"/><line x1="250" y1="57" x2="268" y2="57" class="sk-f" marker-end="url(#ar)"/><line x1="380" y1="57" x2="398" y2="57" class="sk-f" marker-end="url(#ar)"/><text x="260" y="135" text-anchor="middle" class="sk-t">Prozesskostensatz = Prozesskosten : Prozessmenge</text><text x="260" y="160" text-anchor="middle" class="sk-t">lmn-Umlagesatz = lmn-Kosten : lmi-Kosten · 100</text><text x="260" y="200" text-anchor="middle" class="sk-t acc">40.000 € : 400 Bestellungen = 100 € je Bestellung</text>',cap:'Vorgehen der Prozesskostenrechnung bis zum Kostensatz je Vorgang'}},
    {ol:['Untersuchungsbereich festlegen, Prozessorganisation grob gliedern','Tätigkeitsanalyse: Aktivitäten erfassen und zu Teilprozessen bündeln','Teilprozesse als lmi oder lmn einstufen und Kosten zuordnen','Kostentreiber festlegen und Prozessmengen ermitteln','Prozesskostensatz = Prozesskosten : Prozessmenge; lmn-Kosten als prozentuale Umlage aufschlagen','Produkt- bzw. Auftragskosten = Summe (Prozessmenge · Gesamtprozesskostensatz)','Kostentreibende Teilprozesse erkennen und Abläufe verbessern']},
    {fx:['lmn-Umlagesatz = Summe lmn-Kosten : Summe lmi-Kosten · 100','']},
    {fx:['Gesamtprozesskostensatz = lmi-Prozesskostensatz · (1 + Umlagesatz)','']},
    {bsp:{t:'Beispiel: Prozesskostensätze im Einkauf',b:['Monatliche Gemeinkosten des Einkaufs: 85.500 €.']}},
    {tab:[['Teilprozess','Art','Kosten €','Kostentreiber','Menge','Satz €','inkl. Umlage €'],['Angebote einholen','lmi','18.000','Anfragen','300','60,00','67,50'],['Bestellungen auslösen','lmi','40.000','Bestellungen','400','100,00','112,50'],['Rechnungen prüfen','lmi','12.000','Rechnungen','1.500','8,00','9,00'],['Lieferanten betreuen','lmi','6.000','Lieferanten','60','100,00','112,50'],['Abteilung leiten','lmn','9.500','–','–','–','–']]},
    {p:'Umlagesatz = 9.500 € : 76.000 € · 100 = 12,5 %. Ein Sonderteil mit 2 Anfragen, 3 Bestellungen und 3 Rechnungen verursacht 2 · 67,50 € + 3 · 112,50 € + 3 · 9,00 € = 499,50 € Einkaufskosten. Mit einem Materialgemeinkostenzuschlag von 12 % auf 600 € Material würden nur 72 € angesetzt – das Sonderteil wäre viel zu billig kalkuliert.'},
    {bsp:{t:'Beispiel: Vertriebskosten je Auftrag statt Zuschlag',b:['Vertriebskosten 180.000 € im Jahr, ausschließlich lmi, Kostentreiber Anzahl Aufträge: 600 → 300 € je Auftrag. Herstellkosten der verkauften Produkte 1,2 Mio. € → bisheriger Zuschlag 15 %.','Auftrag mit 1 Stück (HK 400 €): Zuschlag 60 €, Prozesskosten 300 €.','Auftrag mit 20 Stück (HK 8.000 €): Zuschlag 1.200 €, Prozesskosten 300 €.','Auftrag mit 100 Stück (HK 40.000 €): Zuschlag 6.000 €, Prozesskosten 300 €.','Interpretation: Kleinaufträge waren zu günstig, Großaufträge zu teuer angeboten. Folge: Mindestauftragswert oder Kleinmengenzuschlag einführen, Großkunden gezielter Rabatt.']}},
    {ul:['Nutzen: Gemeinkostenbereiche werden transparent und steuerbar, unwirtschaftliche Abläufe sichtbar, Einsparpotenziale und bessere Kalkulationsgrundlagen, Unterstützung strategischer Entscheidungen','Effekte: Allokationseffekt (verursachungsgerechte Verteilung), Degressionseffekt (Prozesskosten je Stück sinken mit der Auftragsgröße), Komplexitätseffekt (Varianten und Sonderteile werden teurer)']},
    {falle:'lmn-Kosten haben keinen eigenen Kostentreiber – sie werden prozentual auf die lmi-Sätze aufgeschlagen.'}
  ]},
  {t:'Budgetkontrolle und Ergebnisfeststellung',h:'Budgetkontrolle; Ergebnisfeststellung',pg:57,b:[
    {p:'Ein Budget ist ein Haushaltsplan mit erwarteten Einnahmen bzw. Leistungen und erlaubten Ausgaben bzw. Kosten für einen Verantwortungsbereich und Zeitraum. Nach der Budgetierung folgt die laufende, meist monatliche Kontrolle – sachbezogen (Funktionsbereich) oder personenbezogen (Stelleninhaber).'},
    {tab:[['Gliederungsmerkmal','Budgetarten'],['Zeithorizont','strategisches / operatives Budget'],['Umfang','Einzel- / Gesamtbudget'],['Inhalt','Erfolgsbudget / Finanzbudget'],['Flexibilität','starres / flexibles Budget'],['Produktionsfaktor','Material-, Personal-, Investitionsbudget']]},
    {svg:{w:520,h:250,body:'<rect x="180" y="17" width="160" height="36" class="sk-body"/><text x="260" y="40" text-anchor="middle" class="sk-t">1 Maßstäbe setzen</text><rect x="340" y="87" width="160" height="36" class="sk-body"/><text x="420" y="110" text-anchor="middle" class="sk-t">2 Ist erfassen</text><rect x="280" y="197" width="160" height="36" class="sk-body"/><text x="360" y="220" text-anchor="middle" class="sk-t">3 Soll-Ist-Vergleich</text><rect x="80" y="197" width="160" height="36" class="sk-body"/><text x="160" y="220" text-anchor="middle" class="sk-t">4 Abweichungsanalyse</text><rect x="20" y="87" width="160" height="36" class="sk-body"/><text x="100" y="110" text-anchor="middle" class="sk-t">5 Maßnahmen einleiten</text><line x1="330" y1="53" x2="385" y2="85" class="sk-f" marker-end="url(#ar)"/><line x1="410" y1="123" x2="380" y2="195" class="sk-f" marker-end="url(#ar)"/><line x1="280" y1="215" x2="243" y2="215" class="sk-f" marker-end="url(#ar)"/><line x1="125" y1="197" x2="105" y2="125" class="sk-f" marker-end="url(#ar)"/><line x1="135" y1="87" x2="185" y2="53" class="sk-f" marker-end="url(#ar)"/><text x="260" y="130" text-anchor="middle" class="sk-t acc">Budget-</text><text x="260" y="148" text-anchor="middle" class="sk-t acc">kontrolle</text>',cap:'Regelmäßiger Kontrollkreis der Budgetüberwachung'}},
    {ul:['Fremdkontrolle durch Controlling oder höhere Ebenen greift erst ein, wenn Toleranzgrenzen überschritten sind (Management by Exception) – das entlastet','Der Kontrollprozess muss regelmäßig und in fester Reihenfolge ablaufen, damit er ins Informationssystem passt','Abweichungsanalyse: zuerst Gesamtkosten und Erlöse, dann die mengenabhängigen (variablen) Kosten unter Berücksichtigung der tatsächlichen Absatzmenge']},
    {fx:['flexibles Budget (Sollkosten) = Fixkosten + variable Stückkosten · Istmenge','erst an die Istmenge anpassen, dann vergleichen']},
    {bsp:{t:'Beispiel: Ergebnisabweichung einer Produktlinie Hydraulikkupplungen',b:['Plan: 8.000 Stück · 45 € = 360.000 € Umsatz; variable Kosten 20 €/St. = 160.000 €; Fixkosten 150.000 €; Ergebnis 50.000 €.','Ist: 7.200 Stück · 45 € = 324.000 €; variable Kosten 21 €/St. = 151.200 €; Fixkosten 152.000 €; Ergebnis 20.800 €. Gesamtabweichung −29.200 €.','Mengeneffekt: (7.200 − 8.000) · (45 € − 20 €) = −20.000 € (fehlender Deckungsbeitrag)','Effekt variable Kosten: 7.200 · (20 € − 21 €) = −7.200 € (Mehrverbrauch oder Preissteigerung beim Material)','Fixkosteneffekt: 150.000 € − 152.000 € = −2.000 €','Summe: −20.000 € − 7.200 € − 2.000 € = −29.200 €','Interpretation: Zwei Drittel der Abweichung kommen aus dem Absatz (Vertrieb), 7.200 € aus der Fertigung bzw. Beschaffung – hier muss der Meister Ursachen klären (Materialverbrauch, Ausschuss, Einkaufspreis).']}},
    {bsp:{t:'Beispiel: Budget der Kostenstelle Laserschneiden',b:['Budget 50.000 € für 4.000 Teile (fix 18.000 €, variabel 8,00 €/Teil). Ist: 4.500 Teile, Kosten 58.000 €.','Starrer Vergleich: 58.000 € − 50.000 € = 8.000 € „Überschreitung“.','Flexibles Budget = 18.000 € + 8,00 € · 4.500 = 54.000 € → echte Mehrkosten nur 4.000 € (7,4 %).']}},
    {merke:'Regelmäßige Budgetkontrolle erkennt Abweichungen rechtzeitig, findet Ursachen und leitet Korrekturen ein. Ohne Anpassung an die Istmenge ist der Vergleich unfair.'}
  ]},
  {t:'Forecast und Maßnahmen',h:'Maßnahmen',pg:58,b:[
    {p:'Der Forecast ist eine Prognose der künftigen Geschäftsentwicklung auf Basis des aktuellen Wissens – ein vorausschauendes Steuerungsinstrument. Die Hochrechnung dagegen schätzt das Ganze nur aus einem vorliegenden Teilergebnis.'},
    {svg:{w:520,h:215,body:'<line x1="110" y1="60" x2="494" y2="60" class="sk-l"/><rect x="110" y="55" width="128" height="10" class="fillacc"/><line x1="302" y1="45" x2="302" y2="75" class="sk-l"/><text x="206" y="40" text-anchor="middle" class="sk-t">Jahr 1</text><text x="398" y="40" text-anchor="middle" class="sk-t">Jahr 2</text><text x="174" y="86" text-anchor="middle" class="sk-t">Ist Jan–Aug</text><line x1="238" y1="50" x2="238" y2="180" class="sk-c"/><text x="238" y="200" text-anchor="middle" class="sk-t acc">heute</text><text x="10" y="124" class="sk-t">Year-End</text><line x1="240" y1="120" x2="300" y2="120" class="sk-f" marker-end="url(#ar)"/><text x="312" y="124" class="sk-t">bis Jahresende, schrumpft</text><text x="10" y="164" class="sk-t">rollierend</text><line x1="240" y1="160" x2="476" y2="160" class="sk-f" marker-end="url(#ar)"/><text x="358" y="182" text-anchor="middle" class="sk-t">immer 5–6 Quartale</text>',cap:'Prognosehorizont von Year-End-Forecast und rollierendem Forecast'}},
    {tab:[['Instrument','Horizont','Zweck'],['Hochrechnung','aus Teilergebnis auf das Ganze','schnelle Schätzung'],['Year-End-Forecast','bis Geschäftsjahresende, wird im Jahresverlauf kürzer','Erreichen des Jahresbudgets prüfen; Brücke zwischen Gegenwart und Jahresbudget'],['rollierender Forecast','konstant, meist 5 oder 6 Quartale','über das Jahr hinaus planen, laufende Strategiediskussion']]},
    {ul:['Abweichungsanalysen und Forecasts regelmäßig und häufig erstellen – Übung verbessert die Prognosegenauigkeit','Budgetierung, Forecast und Erfolgsrechnung bilden das Management-Reporting','Gegensteuerungsmaßnahmen: Beschaffungsmärkte analysieren und wechseln, Lieferantenmanagement, Absatzmarkt bearbeiten, Marketing einsetzen, Durchlaufzeiten prüfen, Ausschussquote senken, Abläufe verändern']},
    {bsp:{t:'Beispiel: Forecast der Kostenstelle Montage',b:['Jahresbudget 600.000 €. Istkosten Januar bis August 420.000 €.','Hochrechnung: 420.000 € : 8 · 12 = 630.000 € → 30.000 € über Budget.','Year-End-Forecast mit Wissen über die restlichen Monate: Restbudget Sept.–Dez. 200.000 €, bekannte Tariferhöhung +8.000 €, geringeres Auftragsvolumen −10.000 € → 420.000 € + 198.000 € = 618.000 €.','Maßnahme: Ausschussquote einer Baugruppe (50.000 Teile im Jahr, Herstellkosten 12 €) von 4,0 % auf 2,5 % senken: 50.000 · 1,5 % · 12 € = 9.000 € Ersparnis; Überstunden durch Schichtplanung abbauen.','Interpretation: Die Hochrechnung überzeichnet, weil sie Saisoneffekte ignoriert. Der Forecast zeigt realistische 18.000 € Überschreitung, die mit konkreten Maßnahmen bis zum Jahresende halbiert werden kann.']}},
    {merke:'Kritische Analyse des Erreichten und systematische Einschätzung der Zukunft sind die Kernelemente der operativen Unternehmensführung.'}
  ]},
  {t:'Optimierung der Arbeitsplatzgestaltung',h:'Optimierung der Arbeitsplatzgestaltung',pg:59,b:[
    {p:'Arbeitsplatzgestaltung schafft Bedingungen, unter denen Mensch, Technik, Information und Organisation im Arbeitssystem gut zusammenwirken. Ziel: die Arbeitsaufgabe menschengerecht und wirtschaftlich erfüllen. Roboter und künstliche Intelligenz übernehmen zunehmend auch komplexere Tätigkeiten.'},
    {ul:['Elemente des Arbeitssystems: Arbeitsaufgabe, Arbeitsablauf, Mensch, Betriebs-/Arbeitsmittel, Eingabe, Ausgabe, Umwelteinflüsse','Operations Research: mathematische Entscheidungsunterstützung, wichtigstes Verfahren lineare Optimierung; Merkmale: Streben nach dem Optimum, Modellanalyse, Quantifizierung, Entscheidungsvorbereitung','Arbeitswissenschaftliche Grundlagen: Ergonomie, Anthropometrie (Körpermaße), Arbeitsschutzvorschriften, Arbeitsstättenverordnung, Gestaltung des Arbeitsablaufs','Methodisch: REFA-Planungssystematik (6 Stufen) und KVP','Ergebnis: geringere Beanspruchung, mehr Arbeitssicherheit, höhere Leistung bei guter Qualität und niedrigeren Kosten']},
    {tab:[['Weiterbildung am Arbeitsplatz','Inhalt'],['Unterweisung, laufende Beratung','durch Führungskraft oder erfahrene Kollegen'],['Stellvertretung','Übernahme von Vertretungsaufgaben'],['Job-Enlargement','Aufgabenerweiterung auf gleichem Niveau'],['Jobrotation','planmäßiger Arbeitsplatzwechsel'],['Delegation','Aufgaben mit Verantwortung übertragen'],['Fachliteratur, Workshops, Versetzung','Wissen erweitern, Perspektive wechseln']]},
    {bsp:{t:'Beispiel: Montageplatz nach Greifräumen umgestalten',b:['Ausgangslage: Am Montageplatz für Ventilblöcke liegen Kleinteile außerhalb des Greifraums; die Mitarbeiterin muss sich je Teil drehen und strecken.','Maßnahme: Greifbehälter im Sichtbereich, höhenverstellbarer Tisch, Drehmomentschrauber am Balancer. Kosten 3.000 €.','Zeitersparnis 0,15 min je Teil · 40.000 Teile/Jahr = 6.000 min = 100 h.','Bei 52 €/h (Lohn + Fertigungsgemeinkosten) spart das 5.200 € im Jahr; Amortisation 3.000 € : 5.200 €/Jahr ≈ 0,6 Jahre.','Interpretation: Neben dem Geld sinken Rückenbelastung und Fehlgriffe – ein Argument für Betriebsrat und Fachkraft für Arbeitssicherheit.']}},
    {merke:'Bildung kostet Geld und ist wie eine Sachinvestition zu planen. Kostengünstig und wirksam ist Training on the Job.'}
  ]},
  {t:'Alternative Materialien',h:'Alternative Materialien',pg:60,b:[
    {p:'Material umfasst alle Sachgüter für die Leistungserstellung (Werk-, Hilfs- und Betriebsstoffe). Günstigere Materialien senken Kosten, wenn sie die technischen Anforderungen erfüllen.'},
    {tab:[['bisher','Alternative','Einsatzbeispiel'],['Vollmaterial aus Verschleißstahl','Baustahl mit aufgeschweißter Verschleißschicht','Walzen, Gleitbahnen, Baggerschaufeln'],['Bronze','Kunststoff (z. B. PA, PTFE-Verbund)','Gleitlager, Spindelmuttern'],['Stahlrohr','glasfaserverstärkter Kunststoff','Behälter, Rohrleitungen'],['Stahl','Leichtmetall oder Kunststoff','Zahnräder in Kleingeräten'],['Gummi','Thermoplast/Elastomer','Schläuche, Dichtungen']]},
    {ul:['Sortimentsbreite und -tiefe straffen: weniger Varianten, geringere Bereitstellungskosten, größere Bestellmengen mit Rabatten und günstigeren Frachten','Hilfs- und Betriebsstoffe sind oft nicht exakt spezifiziert: das günstigste Material wählen, das die Anforderungen sicher erfüllt','Wertanalyse: Funktion je Kosten verbessern']},
    {bsp:{t:'Beispiel: Kunststoff-Gleitbuchse statt Bronze',b:['Bedarf 8.000 Buchsen im Jahr. Bronze 4,80 €/St., Kunststoffbuchse 1,90 €/St.; Erprobung und Zeichnungsänderung einmalig 4.500 €.','Ersparnis = (4,80 € − 1,90 €) · 8.000 = 23.200 €/Jahr; nach Abzug der Einmalkosten im 1. Jahr 18.700 €.','Interpretation: Vor der Umstellung Dauerlauftest (Temperatur, Last) und Freigabe durch die Konstruktion – Reklamationen würden die Ersparnis schnell auffressen.']}},
    {merke:'Alternatives Material immer gegen Funktion, Qualität und Lebensdauer prüfen – nicht nur gegen den Einkaufspreis.'}
  ]},
  {t:'Beeinflussung der Materialbestände',h:'Beeinflussung der Materialbestände',pg:60,b:[
    {p:'Der Materialbestand ist der Lagerbestand nach Art und Menge zu einem Stichtag. Bestände sollen so geplant werden, dass wenig Kapital gebunden und die Lieferbereitschaft trotzdem hoch ist.'},
    {tab:[['Klasse','Anteil Positionen (Richtwert)','Wertanteil (Richtwert)','Strategie'],['A','ca. 20 %','ca. 70–80 %','genaue Bedarfsplanung, Angebotsvergleich, knappe Bestände, JIT, Wertanalyse'],['B','ca. 30–40 %','ca. 15 %','mittlerer Aufwand'],['C','ca. 40–50 %','ca. 5–15 %','Bestellkosten senken: Sammelbestellung, Katalog/E-Procurement, vereinfachte Lagerbuchführung, Sichtkontrolle']]},
    {ul:['XYZ-Analyse nach Bedarfsverlauf: X konstant (fertigungssynchron beschaffen), Y schwankend (Vorratshaltung mit Sicherheitsbestand), Z unregelmäßig (Einzelbeschaffung)','C-Teile vereinfachen: Sammelbestellungen, monatliche Sammelrechnung, Zu- und Abgang gleichzeitig buchen, Verbrauch per Inventur, großzügige Sicherheitsbestände, Kanban','Halbfabrikate (meist B/A): Lagersorten optimieren – weniger Abmessungen und Werkstoffe, größere Mengen','Fertigfabrikate: Markt-, Preis- und Kostenanalysen, kleine Abrufmengen, genaue Bestandsführung und Sicherheitsbestände, bevorzugt Wertanalyse']},
    {fx:['optimale Bestellmenge (Andler) = √(200 · Jahresbedarf · Bestellkosten je Bestellung : (Einstandspreis · Lagerhaltungskostensatz in %))','minimiert die Summe aus Bestell- und Lagerkosten']},
    {svg:{w:520,h:295,body:'<line x1="70" y1="250" x2="480" y2="250" class="sk-l"/><line x1="70" y1="250" x2="70" y2="45" class="sk-l"/><polyline points="70,250 110,171.6 150,128.2 190,91 230,77.2 270,66.6 310,61 350,56 390,52.4 430,50.6 470,50" class="sk-f"/><line x1="190" y1="250" x2="190" y2="91" class="sk-c"/><line x1="310" y1="250" x2="310" y2="61" class="sk-c"/><line x1="70" y1="91" x2="190" y2="91" class="sk-c"/><line x1="70" y1="61" x2="310" y2="61" class="sk-c"/><text x="64" y="95" text-anchor="end" class="sk-t">79,5 %</text><text x="64" y="65" text-anchor="end" class="sk-t">94,5 %</text><text x="130" y="236" text-anchor="middle" class="sk-t acc">A</text><text x="250" y="236" text-anchor="middle" class="sk-t acc">B</text><text x="390" y="236" text-anchor="middle" class="sk-t acc">C</text><text x="190" y="268" text-anchor="middle" class="sk-t">30 %</text><text x="310" y="268" text-anchor="middle" class="sk-t">60 %</text><text x="470" y="268" text-anchor="middle" class="sk-t">100 %</text><text x="78" y="36" class="sk-t">Wertanteil kumuliert</text><text x="480" y="288" text-anchor="end" class="sk-t">Anteil der Artikelpositionen</text>',cap:'ABC-Analyse (Lorenzkurve) für das Beispiel mit zehn Artikeln'}},
    {bsp:{t:'Beispiel: ABC-Analyse im Zukaufteilelager',b:['Jahresverbrauchswerte = Menge · Preis, absteigend sortiert, kumuliert.']}},
    {tab:[['Artikel','Menge','Preis €','Wert €','Anteil','kumuliert','Klasse'],['Gussgehäuse','1.200','95,00','114.000','39,2 %','39,2 %','A'],['Hydraulikzylinder','150','420,00','63.000','21,7 %','60,9 %','A'],['Edelstahlblech (m²)','3.000','18,00','54.000','18,6 %','79,5 %','A'],['Wellenstahl (m)','5.000','4,00','20.000','6,9 %','86,4 %','B'],['Kugellager','2.400','6,50','15.600','5,4 %','91,7 %','B'],['Schweißdraht (kg)','2.500','3,20','8.000','2,8 %','94,5 %','B'],['Lack (l)','800','9,00','7.200','2,5 %','97,0 %','C'],['Dichtungen','9.000','0,60','5.400','1,9 %','98,8 %','C'],['Normschrauben M8','60.000','0,04','2.400','0,8 %','99,7 %','C'],['Kabelbinder','20.000','0,05','1.000','0,3 %','100,0 %','C']]},
    {p:'Gesamtwert 290.600 €. Drei A-Artikel (30 % der Positionen) machen 79,5 % des Werts aus. Für Gussgehäuse lohnen Rahmenvertrag und Abruf; Schrauben und Kabelbinder gehören in ein Kanban- oder Lieferantenregal.'},
    {bsp:{t:'Beispiel: Optimale Bestellmenge für Kugellager',b:['Jahresbedarf 12.000 Stück, Bestellkosten 60 € je Bestellung, Einstandspreis 8,00 €, Lagerhaltungskostensatz 15 %.','x opt = √(200 · 12.000 · 60 : (8 · 15)) = √1.200.000 ≈ 1.095 Stück → etwa 11 Bestellungen im Jahr.','Interpretation: Kleinere Lose erhöhen die Bestellkosten, größere binden unnötig Kapital. Mengenrabatte oder Verpackungseinheiten (z. B. 1.000 Stück) können zu einer leicht abweichenden Praxismenge führen.']}},
    {merke:'A-Teile: wenig Positionen, viel Wert → Kapitalbindung senken. C-Teile: viele Positionen, wenig Wert → Abwicklungskosten senken. Mit E-Procurement lassen sich bei C-Teilen sehr hohe Prozesskostenanteile einsparen.'}
  ]},
  {t:'Veränderung der Fertigungstiefe (Make or Buy)',h:'Veränderung der Fertigungstiefe',pg:62,b:[
    {p:'Fertigungstiefe beschreibt, wie viel der Wertschöpfung im eigenen Betrieb stattfindet. Entscheidungen darüber sind Make-or-buy-Entscheidungen. Sie verlangen einen Kostenvergleich und die Bewertung qualitativer Kriterien.'},
    {fx:['kurzfristig (freie Kapazität): kv Eigenfertigung < Fremdbezugspreis → Eigenfertigung','Fixkosten fallen ohnehin an und sind nicht entscheidungsrelevant']},
    {fx:['langfristig: kritische Menge = Fixkosten der Eigenfertigung : (Fremdbezugspreis − kv)','Menge darüber → Eigenfertigung; darunter → Fremdbezug']},
    {svg:{w:520,h:270,body:'<line x1="60" y1="240" x2="495" y2="240" class="sk-l" marker-end="url(#ar)"/><line x1="60" y1="240" x2="60" y2="20" class="sk-l" marker-end="url(#ar)"/><text x="68" y="28" class="sk-t">Kosten (€/Jahr)</text><text x="505" y="266" text-anchor="end" class="sk-t">Stück/Jahr</text><line x1="60" y1="240" x2="480" y2="44" class="sk-f"/><line x1="60" y1="192" x2="480" y2="80" class="sk-l thick"/><line x1="300" y1="240" x2="300" y2="128" class="sk-c"/><circle cx="300" cy="128" r="5" class="fillacc"/><text x="480" y="36" text-anchor="end" class="sk-t acc">Fremdbezug</text><text x="480" y="128" text-anchor="end" class="sk-t">Eigenfertigung</text><text x="55" y="196" text-anchor="end" class="sk-t">12.000</text><text x="300" y="256" text-anchor="middle" class="sk-t">2.000 Stück</text><text x="180" y="112" text-anchor="middle" class="sk-t">Fremdbezug günstiger</text><text x="400" y="226" text-anchor="middle" class="sk-t">Eigenfertigung günstiger</text>',cap:'Langfristige Make-or-buy-Entscheidung: Schnittpunkt der Kostengeraden'}},
    {tab:[['qualitative Kriterien','für Eigenfertigung','für Fremdbezug'],['Know-how','Kernkompetenz schützen','Spezialwissen des Lieferanten nutzen'],['Qualität/Termine','direkte Kontrolle','Lieferant mit besserer Prozessfähigkeit'],['Kapazität','eigene Anlagen auslasten','Spitzen abfangen, Investitionen sparen'],['Abhängigkeit','unabhängig vom Lieferanten','Risiko: Ausfall, Preiserhöhung']]},
    {ul:['Weitere Wege zur Kostensenkung neben Fremdvergabe: Bestände reduzieren, Beschäftigungsgrad erhöhen (Fixkosten je Stück sinken), Produktivität durch bessere Abläufe steigern, flexible Fertigungstechnik (Mehrmaschinenbedienung, Fertigungsinseln)','Qualitative Faktoren lassen sich mit der Nutzwertanalyse vergleichbar machen']},
    {bsp:{t:'Beispiel: Lagerdeckel selbst fertigen oder kaufen?',b:['Kaufpreis frei Haus 14,00 €/Stück. Eigenfertigung: variable Kosten 8,00 €/Stück, zusätzliche Fixkosten (Vorrichtung, Programmierung, anteilige Maschine) 12.000 €/Jahr.','kritische Menge = 12.000 € : (14,00 € − 8,00 €) = 2.000 Stück/Jahr','Bei 3.000 Stück: Eigen 12.000 € + 24.000 € = 36.000 €; Kauf 42.000 € → Eigenfertigung spart 6.000 €.','Kurzfristig, wenn die Maschine ohnehin frei steht und keine Zusatzfixkosten entstehen: 8,00 € < 14,00 € → selbst fertigen.','Interpretation: Bei 1.500 Stück wäre Kaufen günstiger (21.000 € gegenüber 24.000 €). Lieferzuverlässigkeit und Qualität zusätzlich bewerten.']}},
    {falle:'Bei freier Kapazität nur variable Kosten mit dem Fremdpreis vergleichen. Wer Vollkosten (inklusive ohnehin anfallender Fixkosten) ansetzt, entscheidet sich zu oft für den Fremdbezug.'}
  ]},
  {t:'Beeinflussung der Logistikkosten',h:'Beeinflussung der Logistikkosten',pg:62,b:[
    {p:'Logistikkosten umfassen Bestellkosten, Kosten für internen und externen Transport sowie Lagerkosten. Sie lassen sich über Bestände, Lieferkonzepte, Materialfluss und Fremdvergabe beeinflussen.'},
    {ul:['Lagerlogistik: Bestände reduzieren, Just-in-time-Lieferung (fertigungssynchron; Teile der Wertschöpfung werden an Lieferanten verlagert = Outsourcing)','Bei JIT alle Kosten vergleichen und Qualität, Zuverlässigkeit, Termintreue, Lieferbereitschaft quantifizieren (z. B. Nutzwertanalyse)','Bestellkosten: effiziente Verwaltungsabläufe, Rahmenverträge mit rollierender Planung','Interne Logistik: guter Materialfluss verkürzt Transport-, Liege- und Wartezeiten','Externer Transport: eigene Kapazitäten nur bei voller Auslastung, sonst Leerkosten – meist Spedition oder Logistikdienstleister']},
    {fx:['Lagerkosten pro Jahr ≈ durchschnittlicher Lagerbestand (€) · Lagerhaltungskostensatz','Satz enthält Zinsen, Raum, Personal, Schwund, Veralten']},
    {bsp:{t:'Beispiel: JIT für Aluminium-Strangpressprofile',b:['Durchschnittsbestand bisher 180.000 €, mit Abrufsystem und Lieferung zweimal pro Woche 60.000 €. Lagerhaltungskostensatz 20 %.','Ersparnis = (180.000 € − 60.000 €) · 0,20 = 24.000 €/Jahr; zusätzlich werden 120.000 € Kapital frei.','Gegenrechnung: Aufpreis des Lieferanten 0,5 % auf 900.000 € Einkaufsvolumen = 4.500 €. Netto bleiben 19.500 €.','Interpretation: Lohnt sich, wenn Liefertreue vertraglich gesichert ist (Pönale) und ein Sicherheitsbestand für zwei Tage vorgehalten wird.']}},
    {merke:'Eigene Transportkapazität ohne volle Auslastung erzeugt Leerkosten – Fremdvergabe wandelt Fixkosten in variable Kosten.'}
  ]},
  {t:'Vereinfachung von Verwaltungsabläufen',h:'Vereinfachung von Verwaltungsabläufen',pg:62,b:[
    {p:'Verwaltungsabläufe verbinden Sachmittel und Personal mit Methoden und Umwelt des Unternehmens. Sie sollen die Unternehmensziele mit möglichst wenig Aufwand unterstützen.'},
    {tab:[['Art','Beispiele'],['technisch','CNC-Programme erstellen, Werkstoffprüfungen, Prüfpläne'],['organisatorisch','Angebote, Rechnungen, Reklamationen bearbeiten'],['prozessorientiert','Neueinstellungen, zentraler Einkauf']]},
    {ul:['Hilfsmittel: Stellenablaufpläne, Dokumentenlaufkarten, Arbeitsablaufkarten, Programmablaufpläne, Arbeitsflussdiagramme','Rationalisierung z. B. durch E-Procurement-Kataloge für C-Teile, digitale Freigaben, Standardangebote, Vorlagen','Mehr Flexibilität im Einkauf senkt Kosten spürbar']},
    {bsp:{t:'Beispiel: Katalogbestellung für C-Teile',b:['Bisher 1.500 Bestellungen von Verbrauchsmaterial pro Jahr über den Einkauf, Prozesskosten je Bestellung 65 €.','Neu: Meister und Gruppenleiter bestellen direkt aus einem freigegebenen Lieferantenkatalog mit Budgetgrenze; Prozesskosten 15 € je Bestellung.','Ersparnis = 1.500 · (65 € − 15 €) = 75.000 €/Jahr; der Einkauf gewinnt Zeit für die Verhandlung der A-Teile.']}},
    {merke:'Bevor ein Ablauf digitalisiert wird, wird er vereinfacht – sonst wird Verschwendung nur schneller.'}
  ]},
  {t:'Ergebnisse aus zeitwirtschaftlichen Überlegungen',h:'Ergebnisse aus zeitwirtschaftlichen Überlegungen',pg:63,b:[
    {p:'Zeitwirtschaft nutzt die Zeit als Messgröße für Planung, Steuerung und Kontrolle aller Arbeitsprozesse. Wer Zeiten beeinflussen will, muss Prozesse verändern – und dafür die Potenziale aller Mitarbeitenden einbinden.'},
    {ul:['Aufgabenintegration: Gruppenarbeit und teilautonome Fertigungsgruppen erhöhen Selbstständigkeit, Eigenverantwortung und Motivation','Zu beachten: prozessorientierte Aufgabenstrukturen, größere Handlungsspielräume, neues Rollenverständnis von Mitarbeitenden und Führungskräften','Gruppenentlohnung: Tarifgrundlohn + tarifliche Leistungszulage + zielorientierte Gruppenzulage','Die Gruppenzulage wirkt auf Löhne und Gehälter, Leitungskosten, Betriebs- und Hilfsstoffe, Ausschuss und Nacharbeit sowie Instandhaltung']},
    {bsp:{t:'Beispiel: Zielorientierte Gruppenzulage in der Rohrbiegerei',b:['Gruppe aus 8 Mitarbeitenden, je 150 h im Monat. Ziel: Ausschussquote unter 2 % (bisher 3 %). Zulage bei Zielerreichung 0,80 €/h.','Kosten der Zulage: 8 · 150 h · 0,80 € = 960 €/Monat.','Nutzen: 30.000 Rohre/Monat · 1 Prozentpunkt weniger Ausschuss · 9,00 € Herstellkosten = 2.700 €/Monat.','Interpretation: Der Betrieb spart netto 1.740 € im Monat, die Gruppe verdient mehr. Die Regelung ist mitbestimmungspflichtig (§ 87 Abs. 1 Nr. 10, 11 BetrVG) und braucht eine Betriebsvereinbarung.']}},
    {merke:'Selbstverantwortliche Gruppenarbeit funktioniert, wenn die Gruppe ihre Kraft einbringen darf, Freude daran hat und finanziell profitiert.'}
  ]},
  {t:'Kostenbeeinflussung aufgrund von Ergebnissen der Kostenrechnung',h:'Kostenbeeinflussung aufgrund von Ergebnissen der Kostenrechnung',pg:63,b:[
    {p:'Kostenträgerstück- und -zeitrechnung kontrollieren Kosten je Stück, Auftrag oder Periode. Die laufende Überwachung erfolgt in der mitlaufenden Kalkulation.'},
    {ul:['Istkosten und Umsatzerlöse zur Beurteilung heranziehen','Sollkosten mit den Istkosten der Nachkalkulation vergleichen','Vorkalkulation der Nachkalkulation gegenüberstellen','Kosten der verkauften Produkte ins Verhältnis zu den Erlösen setzen']},
    {tab:[['Bereich','typische Ursachen von Mehrkosten'],['Vertrieb und Projektierung','Terminnot, unvollständige technische Angaben, Nachträge nach Vertragsabschluss, abweichende Kundenvorschriften, Teillieferungen, Vertragsstrafen'],['Konstruktion','unzureichende Zeichnungen, falsche Leistungsdaten, nachträgliche Werkstoffänderung, fehlerhafte Stücklisten, falsche Gewichte'],['Materialwirtschaft','Terminnot, Ausweichmaterial, Teil- und Überlieferungen, Mindestmengen, Umdisposition, Eigenfertigung statt Fremdbezug, nicht erfasste Rückgaben'],['Fertigung','Losgrößenänderung, Sammelaufträge, Auftragssplitting, Mengenänderung, verlängerte Werkbank, zusätzliche Vorrichtungen'],['Rechnungswesen','Fehlkontierungen, fehlende Belege, falsche Rückstellungen, Fehlbewertung von Restmaterial, Änderung von Verrechnungspreisen']]},
    {ul:['PPS-Systeme (Produktionsplanung und -steuerung) planen alle Fertigungsprozesse rechnergestützt, fassen gleichartige Aufträge werksübergreifend zusammen, berücksichtigen Mindestlosgrößen und nutzen Lagerbestände – das verbessert die Auslastung und senkt Kosten']},
    {bsp:{t:'Beispiel: Vor- und Nachkalkulation eines Schaltschrankgestells',b:['Vergleich der Herstellkosten (Werte in €), Zuschläge wie in der Vorkalkulation.']}},
    {tab:[['Position','Vorkalkulation','Nachkalkulation','Abweichung','in %'],['Fertigungsmaterial','1.200','1.290','+90','+7,5'],['Materialgemeinkosten 10 %','120','129','+9','+7,5'],['Fertigungslohn','800','920','+120','+15,0'],['Fertigungsgemeinkosten 180 %','1.440','1.656','+216','+15,0'],['Herstellkosten','3.560','3.995','+435','+12,2']]},
    {p:'Interpretation: Der Lohn liegt 15 % über Plan. Nachfrage beim Meister: Die Zeichnung kam unvollständig, zwei Bleche mussten nachgeschnitten werden (Konstruktion); 6 % Mehrmaterial durch Verschnitt. Maßnahme: Zeichnungsprüfung vor Fertigungsfreigabe, Schachtelplan für die Lasermaschine.'},
    {merke:'Die Nachkalkulation zeigt, wo Kalkulationsannahmen falsch waren – entweder die Vorgabe korrigieren oder die Ursache in der Fertigung abstellen.'}
  ]},
  {t:'Arbeitsorganisation als kostenbeeinflussender Faktor',h:'Arbeitsorganisation als kostenbeeinflussender Faktor',pg:67,b:[
    {p:'Im weiten Sinn gehören Arbeitszeitmodelle, Art- und Mengenteilung und Gruppenarbeit zur Arbeitsorganisation. Im engen Sinn wird sie in drei Ebenen gegliedert, die alle Kosten über Durchlauf-, Rüst- und Wartezeiten beeinflussen.'},
    {tab:[['Ebene','Inhalt','Kostenhebel'],['Arbeitsgangorganisation','Teilaufgaben zu betrieblich passenden Arbeitsgängen bündeln; Qualifikation und Automatisierungsgrad berücksichtigen','weniger Übergaben, passende Qualifikation'],['Arbeitsplatzorganisation','Stellen, Mitarbeitende, Arbeitsplätze und Maschinen zuordnen; Hilfsmittel, Teile, Werkzeuge, Software beschreiben','kurze Wege, vollständige Ausstattung'],['Arbeitsablauforganisation','Teilarbeiten parallel oder nacheinander ausführen','kürzere Durchlauf- und Rüstzeiten']]},
    {fx:['Reihenverlauf: Durchlaufzeit = m · Summe te','ganzes Los wird erst nach Fertigstellung weitergegeben']},
    {fx:['Parallelverlauf: Durchlaufzeit = Summe te + (m − 1) · te max','jedes Stück wird sofort weitergegeben; der längste Arbeitsgang bestimmt den Takt']},
    {svg:{w:520,h:250,body:'<text x="110" y="22" class="sk-t acc">Reihenverlauf – ganzes Los weitergeben</text><text x="100" y="43" text-anchor="end" class="sk-t">AG 1</text><text x="100" y="63" text-anchor="end" class="sk-t">AG 2</text><text x="100" y="83" text-anchor="end" class="sk-t">AG 3</text><rect x="110" y="30" width="112" height="16" class="sk-body"/><rect x="222" y="50" width="168" height="16" class="sk-body"/><rect x="390" y="70" width="84" height="16" class="fillacc"/><text x="474" y="104" text-anchor="end" class="sk-t">Durchlaufzeit 52 min</text><text x="110" y="128" class="sk-t acc">Parallelverlauf – jedes Stück sofort weitergeben</text><text x="100" y="153" text-anchor="end" class="sk-t">AG 1</text><text x="100" y="173" text-anchor="end" class="sk-t">AG 2</text><text x="100" y="193" text-anchor="end" class="sk-t">AG 3</text><rect x="110" y="140" width="28" height="16" class="sk-body"/><rect x="138" y="140" width="28" height="16" class="sk-body"/><rect x="166" y="140" width="28" height="16" class="sk-body"/><rect x="194" y="140" width="28" height="16" class="sk-body"/><rect x="138" y="160" width="42" height="16" class="sk-body"/><rect x="180" y="160" width="42" height="16" class="sk-body"/><rect x="222" y="160" width="42" height="16" class="sk-body"/><rect x="264" y="160" width="42" height="16" class="sk-body"/><rect x="180" y="180" width="21" height="16" class="fillacc"/><rect x="222" y="180" width="21" height="16" class="fillacc"/><rect x="264" y="180" width="21" height="16" class="fillacc"/><rect x="306" y="180" width="21" height="16" class="fillacc"/><text x="340" y="193" class="sk-t">Durchlaufzeit 31 min</text><line x1="110" y1="215" x2="480" y2="215" class="sk-l"/><line x1="110" y1="211" x2="110" y2="219" class="sk-l"/><line x1="180" y1="211" x2="180" y2="219" class="sk-l"/><line x1="250" y1="211" x2="250" y2="219" class="sk-l"/><line x1="320" y1="211" x2="320" y2="219" class="sk-l"/><line x1="390" y1="211" x2="390" y2="219" class="sk-l"/><line x1="460" y1="211" x2="460" y2="219" class="sk-l"/><text x="110" y="234" text-anchor="middle" class="sk-t">0</text><text x="180" y="234" text-anchor="middle" class="sk-t">10</text><text x="250" y="234" text-anchor="middle" class="sk-t">20</text><text x="320" y="234" text-anchor="middle" class="sk-t">30</text><text x="390" y="234" text-anchor="middle" class="sk-t">40</text><text x="460" y="234" text-anchor="middle" class="sk-t">50 min</text>',cap:'Los mit 4 Stück, Stückzeiten 4, 6 und 3 min: Reihen- gegen Parallelverlauf'}},
    {bsp:{t:'Beispiel: Durchlaufzeit eines Loses Hydraulikflansche',b:['Los m = 50 Stück; Arbeitsgänge: Drehen te = 4 min, Bohren te = 6 min, Entgraten te = 3 min (Summe 13 min).','Reihenverlauf: 50 · 13 min = 650 min ≈ 10,8 h.','Parallelverlauf: 13 min + 49 · 6 min = 307 min ≈ 5,1 h.','Interpretation: Durch Weitergabe in kleinen Transportlosen halbiert sich die Durchlaufzeit; Umlaufbestand und Kapitalbindung sinken. Nachteil: mehr Transportvorgänge und Wartezeiten am Engpass (Bohren) – dort ansetzen, z. B. zweite Bohrstation.']}},
    {merke:'Ziel der Arbeitsablauforganisation: Durchlaufzeiten mit den zugehörigen Rüstzeiten minimieren. Der Engpass-Arbeitsgang bestimmt die Leistung der ganzen Kette.'}
  ]},
  {t:'Einbeziehung der Mitarbeiter in die Kostenbewertung',h:'Einbeziehung der Mitarbeiter in die Kostenbewertung',pg:67,b:[
    {p:'Viele Beschäftigte wollen besser informiert und stärker beteiligt werden. Aktuelles Wissen weckt Verständnis für Veränderungen, baut Ängste ab und fördert Vorschläge. Eine gute Führungskraft muss nicht alles besser wissen, sondern das Wissen der Gruppe zusammenführen und koordinieren.'},
    {ul:['Mitarbeitende an der Bewertung von Plan-Ist-Abweichungen beteiligen','Ziele gemeinsam entwickeln: anspruchsvoll, aber realistisch','Beiträge anerkennen – materiell (Prämie) und immateriell (Lob, Aushang, Verantwortung)','Offene Kommunikation: regelmäßige Mitarbeiter- und Gruppengespräche über Arbeitsergebnisse, auch über berufliche Anliegen','Instrumente: Qualitätszirkel, Qualitätsgruppen, Werkstattkreise, betriebliches Vorschlagswesen/Ideenmanagement, Lösungs- und Kreativitätstechniken','Gruppen mit eigenen Entscheidungsbefugnissen (Arbeitsplanung, Qualitätskontrolle, Instandhaltung) sparen Steuerungs- und Kontrollaufwand, verkürzen Durchlaufzeiten, steigern Auslastung und Zufriedenheit']},
    {bsp:{t:'Beispiel: Kostenwand in der Zerspanung',b:['Die Meisterin hängt monatlich eine Tafel aus: Werkzeugkosten je 1.000 Teile, Ausschussquote, Energieverbrauch je Maschinenstunde – jeweils Ziel und Ist.','Im Gruppengespräch schlägt ein Mitarbeiter vor, Wendeschneidplatten mit vier statt zwei nutzbaren Schneiden einzusetzen und Standzeiten zu dokumentieren.','Ergebnis: Werkzeugkosten sinken um 12.000 € im Jahr. Nach der Betriebsvereinbarung zum Ideenmanagement gibt es 15 % der Jahresersparnis als Prämie: 1.800 €.','Interpretation: Sichtbare Kennzahlen und eine faire Prämie machen Kostenbewusstsein greifbar.']}},
    {merke:'Qualifizierte und motivierte Mitarbeitende sind das wichtigste Potenzial. Motivation ist am höchsten, wenn der eigene Vorschlag erkennbar zu einem anerkannten Ergebnis führt.'},
    {falle:'Das betriebliche Vorschlagswesen ist mitbestimmungspflichtig (§ 87 Abs. 1 Nr. 12 BetrVG) – Prämienregeln gehören in eine Betriebsvereinbarung.'}
  ]},
  {t:'Kostenartenrechnung und Kontenrahmen',h:'Kostenartenrechnung',pg:69,b:[
    {p:'Grundlage der Kostenartenrechnung ist ein einheitlicher Kontenrahmen. Der Industriekontenrahmen (IKR), 1971 vom BDI empfohlen, vereinheitlicht die Buchführung und erleichtert die EDV. Daraus leitet jeder Betrieb seinen Kontenplan ab.'},
    {tab:[['Ebene','Beispiel'],['Kontenklasse','2 Umlaufvermögen'],['Kontengruppe','28 flüssige Mittel'],['Kontenart','280 Guthaben bei Kreditinstituten'],['Kontenunterart','2801 bestimmte Bank']]},
    {ul:['IKR: Klassen 0–8 für die Finanzbuchhaltung (Rechnungskreis I), Klasse 9 für die Kosten- und Leistungsrechnung (Rechnungskreis II) – Zweikreissystem','Betriebliche Aufwendungen der Klasse 6 werden nach Sachbereichen gegliedert, z. B. Rohstoffe/Fertigungsmaterial, Hilfsstoffe, Betriebsstoffe, Löhne, Gehälter, soziale Abgaben, Abschreibungen, Mieten','In der KLR (Klasse 9) z. B. Fertigungsmaterial, Sondereinzelkosten der Fertigung, Gemeinkostenmaterial, Betriebsstoffe, Verbrauchswerkzeuge']},
    {tab:[['Verhalten bei Beschäftigungsänderung','Merkmal'],['reine fixe Kosten','zeitabhängig, unabhängig von der Beschäftigung'],['reine variable Kosten','abhängig von Leistung bzw. Beschäftigung'],['Mischkosten','fixe und variable Bestandteile']]},
    {bsp:{t:'Beispiel: Belege richtig kontieren',b:['Eingangsrechnung über 2 t Rundstahl für Wellen → Fertigungsmaterial (IKR 600), Einzelkosten','Rechnung über Schweißdraht und Trennscheiben → Hilfsstoffe (602), Gemeinkosten der Schweißerei','Stromrechnung → Betriebsstoffe/Energie (605), Gemeinkosten, nach Zählern auf Kostenstellen','Lohnliste der Dreher → Löhne (620); per Lohnschein auf Aufträge = Fertigungslohn','Interpretation: Falsch kontierte Belege verzerren Kostenstellenberichte – Meister prüfen Kostenstelle und Auftragsnummer auf jedem Beleg.']}},
    {merke:'Ein Kontenrahmen ist überbetrieblich (Organisationsrahmen), der Kontenplan ist sein betriebsindividueller Ausbau.'}
  ]},
  {t:'Kostenstellenrechnung: Bildung von Kostenstellen',h:'Kostenstellenrechnung',pg:69,abb:[['Abb. 5.1 Kostenstellen nach Funktionsmerkmalen geordnet',70]],b:[
    {p:'Weil Gemeinkosten in den Teilbereichen unterschiedlich anfallen, bildet man Kostenstellen. Erst so lassen sich die Gemeinkosten verursachungsgerecht auf die Kostenträger verteilen. Die Aufbauorganisation – eine hierarchische Gliederung von Leitungs- und Funktionsebenen – liefert den Rahmen.'},
    {tab:[['Merkmal','Beispiel'],['Funktion (Art der Verrichtung)','Beschaffung, Fertigung, Vertrieb'],['räumliche Gegebenheiten','Dreherei in Halle 2'],['Organisation/Verantwortung','Bereich einer Meisterin oder Abteilungsleitung'],['abrechnungstechnische Kriterien','Haupt- und Hilfsstellen; Maschinen mit ähnlicher Kostenstruktur zusammenfassen']]},
    {svg:{w:520,h:225,body:'<rect x="210" y="10" width="100" height="30" class="sk-body"/><text x="260" y="30" text-anchor="middle" class="sk-t acc">Betrieb</text><line x1="260" y1="40" x2="260" y2="55" class="sk-l"/><line x1="56" y1="55" x2="464" y2="55" class="sk-l"/><line x1="56" y1="55" x2="56" y2="65" class="sk-l"/><line x1="158" y1="55" x2="158" y2="65" class="sk-l"/><line x1="362" y1="55" x2="362" y2="65" class="sk-l"/><line x1="464" y1="55" x2="464" y2="65" class="sk-l"/><line x1="260" y1="55" x2="260" y2="65" class="sk-l"/><rect x="10" y="65" width="92" height="44" class="sk-body"/><rect x="112" y="65" width="92" height="44" class="sk-body"/><rect x="214" y="65" width="92" height="44" class="sk-body"/><rect x="316" y="65" width="92" height="44" class="sk-body"/><rect x="418" y="65" width="92" height="44" class="sk-body"/><text x="56" y="83" text-anchor="middle" class="sk-t">100</text><text x="56" y="101" text-anchor="middle" class="sk-t">Allgemein</text><text x="158" y="83" text-anchor="middle" class="sk-t">200</text><text x="158" y="101" text-anchor="middle" class="sk-t">Material</text><text x="260" y="83" text-anchor="middle" class="sk-t acc">300</text><text x="260" y="101" text-anchor="middle" class="sk-t acc">Fertigung</text><text x="362" y="83" text-anchor="middle" class="sk-t">400</text><text x="362" y="101" text-anchor="middle" class="sk-t">Verwaltung</text><text x="464" y="83" text-anchor="middle" class="sk-t">500</text><text x="464" y="101" text-anchor="middle" class="sk-t">Vertrieb</text><line x1="260" y1="109" x2="260" y2="125" class="sk-l"/><line x1="95" y1="125" x2="440" y2="125" class="sk-l"/><line x1="95" y1="125" x2="95" y2="140" class="sk-l"/><line x1="210" y1="125" x2="210" y2="140" class="sk-l"/><line x1="325" y1="125" x2="325" y2="140" class="sk-l"/><line x1="440" y1="125" x2="440" y2="140" class="sk-l"/><rect x="45" y="140" width="100" height="44" class="sk-body"/><rect x="160" y="140" width="100" height="44" class="sk-body"/><rect x="275" y="140" width="100" height="44" class="sk-body"/><rect x="390" y="140" width="100" height="44" class="sk-body"/><text x="95" y="158" text-anchor="middle" class="sk-t">310 AV</text><text x="95" y="176" text-anchor="middle" class="sk-t">Hilfsstelle</text><text x="210" y="158" text-anchor="middle" class="sk-t">320 Instandh.</text><text x="210" y="176" text-anchor="middle" class="sk-t">Hilfsstelle</text><text x="325" y="158" text-anchor="middle" class="sk-t">330 Dreherei</text><text x="325" y="176" text-anchor="middle" class="sk-t">Hauptstelle</text><text x="440" y="158" text-anchor="middle" class="sk-t">340 Montage</text><text x="440" y="176" text-anchor="middle" class="sk-t">Hauptstelle</text><text x="325" y="208" text-anchor="middle" class="sk-t">Unterstellen 331 CNC, 332 konventionell</text>',cap:'Eigener Kostenstellenplan nach dem Funktionsprinzip mit Haupt-, Hilfs- und Unterstellen'}},
    {ul:['Bereiche mittlerer und größerer Betriebe: allgemeiner Bereich, Materialbereich, Fertigungsbereich, Verwaltungsbereich, Vertriebsbereich; kleine Betriebe oft nur Produktion, Verwaltung, Vertrieb','In der Praxis werden mehrere Merkmale kombiniert – meist die Funktion mit Verantwortung und Raum; eine allgemeingültige Gliederung gibt es nicht','Methoden der Kostenstellenrechnung: buchhalterisch (über Kostenstellenkonten, aufwendig, unübersichtlich) oder statistisch-tabellarisch im BAB – beim IKR (Zweikreissystem) der Normalfall']},
    {bsp:{t:'Beispiel: Kostenstellen für eine neue Laserhalle',b:['Ausgangslage: Zwei Laserschneidanlagen und eine Abkantpresse kommen in eine neue Halle.','Entscheidung: Eine Hauptkostenstelle 350 „Blechbearbeitung“ (Verantwortung: ein Meister, ein Raum) mit den Unterstellen 351 Laser (zwei gleichartige Anlagen) und 352 Abkanten – für getrennte Maschinenstundensätze.','Interpretation: Gleiche Maschinen zusammenfassen, unterschiedliche Kostenstrukturen trennen – so bleibt die Kalkulation genau und der Aufwand gering.']}},
    {merke:'Kostenstellen nach dem Prinzip „ein Verantwortlicher, klare räumliche und funktionale Abgrenzung, eindeutige Bezugsgröße“ bilden.'}
  ]},
  {t:'Betriebsabrechnungsbogen in der Betriebsabrechnung',h:'Betriebsabrechnungsbogen (BAB)',pg:71,b:[
    {p:'Der BAB ist die Grundlage der stellenweisen Wirtschaftlichkeitskontrolle. Er enthält die Istkosten der Periode; bei Normal- oder Plankostenrechnung werden sie den Normal- bzw. Sollkosten gegenübergestellt. Aus den Gemeinkosten je Hauptstelle und einer passenden Bezugsgröße entstehen die Kalkulationssätze für die differenzierende Zuschlagskalkulation.'},
    {fx:['Zuschlagssatz in % = Gemeinkosten : Bezugsgröße · 100','Bezugsgröße = Einzelkosten (Material, Lohn) bzw. Herstellkosten des Umsatzes']},
    {fx:['Normal-HKE = Ist-FM + Normal-MGK + Ist-FL + Normal-FGK; Normal-HKU = Normal-HKE + Minderbestand − Mehrbestand','']},
    {fx:['Deckungsdifferenz = Normalgemeinkosten − Istgemeinkosten','Normal > Ist: Überdeckung; Normal < Ist: Unterdeckung']},
    {ul:['Kalkulationssätze gibt es als Ist-, Normal- und Plankostensätze','Normalzuschläge: über mehrere Perioden gemittelt, bei durchschnittlicher Beschäftigung','Ursachen von Deckungsdifferenzen: Preis-, Verfahrens- und Beschäftigungsabweichungen','Werden Toleranzgrenzen über- oder unterschritten, folgen Abweichungsanalysen und Maßnahmen bzw. angepasste Vorgaben','Grenze: Normalkosten vergleichen mit Durchschnitt der Vergangenheit – bessere Aussagen liefern technisch-wirtschaftlich ermittelte Plan- und Sollwerte','Dauerhaft erhöhte Kosten, die sich nicht über den Preis weitergeben lassen, schmälern direkt den Gewinn']},
    {bsp:{t:'Beispiel: Istzuschläge, Normalkosten und Deckungsdifferenzen mit Bestandsveränderungen',b:['Einzelkosten: Fertigungsmaterial 125.000 €, Fertigungslöhne 150.000 €. Ist-Gemeinkosten: Material 14.400 €, Fertigung 250.000 €, Verwaltung 75.000 €, Vertrieb 47.000 €.','Bestände: unfertige Erzeugnisse 40.000 € → 25.000 € (Minderung 15.000 €); fertige Erzeugnisse 60.000 € → 80.000 € (Mehrung 20.000 €); saldiert Mehrbestand 5.000 €.','Normalzuschläge: Material 12 %, Fertigung 160 %, Verwaltung 15 %, Vertrieb 10 %.']}},
    {tab:[['Position','Ist €','Ist-Satz','Normal €','Differenz €'],['Fertigungsmaterial','125.000','','125.000',''],['Materialgemeinkosten','14.400','11,52 %','15.000','+600'],['Fertigungslöhne','150.000','','150.000',''],['Fertigungsgemeinkosten','250.000','166,67 %','240.000','−10.000'],['Herstellkosten der Erzeugung','539.400','','530.000',''],['− Mehrbestand (saldiert)','5.000','','5.000',''],['Herstellkosten des Umsatzes','534.400','','525.000',''],['Verwaltungsgemeinkosten','75.000','14,03 %','78.750','+3.750'],['Vertriebsgemeinkosten','47.000','8,79 %','52.500','+5.500'],['Selbstkosten des Umsatzes','656.400','','656.250','−150']]},
    {p:'Interpretation: Insgesamt nur 150 € Unterdeckung – aber die Fertigung liegt 10.000 € über Normal (z. B. ungeplante Reparatur, Überstunden), während Verwaltung und Vertrieb unter Normal blieben. Die Gesamtsumme verdeckt die Problemstelle; deshalb immer stellenweise auswerten.'},
    {falle:'Bestandsmehrung (fertige und unfertige zusammen saldieren) von den HKE abziehen, Minderung addieren. Ein Vorzeichenfehler verfälscht Verwaltungs- und Vertriebszuschlag.'}
  ]},
  {t:'Kostenträgerrechnung: Zeit- und Stückrechnung',h:'Kostenträgerrechnung',pg:74,b:[
    {p:'Die Kostenträgerrechnung ordnet die Einzelkosten (aus der Kostenartenrechnung) und die Gemeinkosten (aus der Kostenstellenrechnung) den Leistungen zu. Kostenträger sind Absatzleistungen (Kunden- und Lageraufträge) und innerbetriebliche Leistungen (aktivierbar, z. B. selbst gebaute Vorrichtung).'},
    {tab:[['Aufgabe','Instrument'],['Herstell- und Selbstkosten je Einheit ermitteln','Kostenträgerstückrechnung (Kalkulation)'],['alle Kosten einer Periode je Produkt(gruppe) erfassen','Kostenträgerzeitrechnung (Kostenträgerblatt, BAB II)'],['kurzfristigen, monatlichen Erfolg zeigen','kurzfristige Erfolgsrechnung: Umsatzkosten- oder Gesamtkostenverfahren'],['Informationen für Preis-, Programm- und Beschaffungsentscheidungen, Bestandsbewertung','alle']]},
    {fx:['Umsatzergebnis = Nettoverkaufserlöse − Selbstkosten des Umsatzes','Nettoerlöse = Umsatzerlöse − Erlösschmälerungen']},
    {fx:['Betriebsergebnis = Umsatzergebnis (zu Normalkosten) + Überdeckung − Unterdeckung','= Nettoerlöse − Ist-Selbstkosten']},
    {tab:[['Verfahren','Gegenüberstellung'],['Umsatzkostenverfahren','Selbstkosten der verkauften Produkte ↔ Umsatzerlöse je Produkt'],['Gesamtkostenverfahren','gesamte Kosten nach Kostenarten ± Bestandsveränderungen ↔ Umsatzerlöse']]},
    {tab:[['Kalkulationsart','Zeitpunkt','Grundlagen','Zweck'],['Vorkalkulation','vor Auftragsbeginn','Stücklisten, Vorgabezeiten, Normal- bzw. Plansätze, Wiederbeschaffungspreise','Angebotspreis, Annahme bei vorgegebenem Preis, neue Produkte, Verfahrenswahl'],['Zwischenkalkulation (mitlaufende Kalkulation)','während langer Fertigung','bisherige Istkosten des Auftrags','Kostenentwicklung überwachen (Anlagen-, Schiff-, Brückenbau); unfertige Erzeugnisse bewerten'],['Nachkalkulation','nach Fertigstellung','MES, Lohnscheine, Istzuschläge','Über-/Unterdeckung gegenüber Vorkalkulation, künftige Angebote verbessern, Erfolgsbeitrag je Produkt']]},
    {bsp:{t:'Beispiel: Kostenträgerzeitblatt für zwei Produktgruppen (Normalkosten)',b:['Normalzuschläge: Material 12 %, Fertigung 160 %, Verwaltung 15 %, Vertrieb 10 %; keine Bestandsveränderungen.','Pumpen (A): FM 80.000 €, MGK 9.600 €, FL 60.000 €, FGK 96.000 € → HK 245.600 €; VwGK 36.840 €, VtGK 24.560 € → Selbstkosten 307.000 €; Erlöse 330.000 € → Umsatzergebnis +23.000 €.','Ventile (B): FM 45.000 €, MGK 5.400 €, FL 90.000 €, FGK 144.000 € → HK 284.400 €; VwGK 42.660 €, VtGK 28.440 € → Selbstkosten 355.500 €; Erlöse 350.000 € → Umsatzergebnis −5.500 €.','Umsatzergebnis gesamt = 17.500 €. Ist-Gemeinkosten laut BAB: Material 14.400 €, Fertigung 250.000 €, Verwaltung 75.000 €, Vertrieb 47.000 € → Ist-Selbstkosten 661.400 €; Normal-Selbstkosten 662.500 € → Überdeckung 1.100 €.','Betriebsergebnis = 17.500 € + 1.100 € = 18.600 € (Kontrolle: 680.000 € − 661.400 €).','Interpretation: Die Ventile decken ihre Vollkosten nicht. Bevor man sie streicht, prüft die Deckungsbeitragsrechnung, ob sie zur Fixkostendeckung beitragen.']}},
    {merke:'Herstellkosten bewerten Bestände; Selbstkosten sind alle Kosten bis zum Verkauf. Das Betriebsergebnis ergibt sich aus Erlösen minus Selbstkosten des Umsatzes.'}
  ]},
  {t:'Kalkulationsverfahren im Überblick',h:'Kalkulationsverfahren und ihre Anwendungsbereiche',pg:79,b:[
    {p:'Welches Kalkulationsverfahren passt, hängt vom Fertigungstyp ab. Je verschiedenartiger die Produkte und je höher der Gemeinkostenanteil, desto differenzierter muss gerechnet werden.'},
    {svg:{w:520,h:315,body:'<rect x="10" y="10" width="250" height="34" class="sk-body"/><text x="135" y="32" text-anchor="middle" class="sk-t">Nur ein Produkt?</text><rect x="330" y="10" width="180" height="34" class="fillacc"/><text x="420" y="32" text-anchor="middle" class="sk-t">Divisionskalkulation</text><rect x="10" y="75" width="250" height="34" class="sk-body"/><text x="135" y="97" text-anchor="middle" class="sk-t">Sorten, festes Kostenverhältnis?</text><rect x="330" y="75" width="180" height="34" class="sk-body"/><text x="420" y="97" text-anchor="middle" class="sk-t">Äquivalenzziffern</text><rect x="10" y="140" width="250" height="34" class="sk-body"/><text x="135" y="162" text-anchor="middle" class="sk-t">Kuppelprodukte?</text><rect x="330" y="140" width="180" height="34" class="sk-body"/><text x="420" y="162" text-anchor="middle" class="sk-t">Kuppelkalkulation</text><rect x="10" y="205" width="250" height="34" class="sk-body"/><text x="135" y="227" text-anchor="middle" class="sk-t">Hohe Maschinenkosten?</text><rect x="330" y="205" width="180" height="34" class="sk-body"/><text x="420" y="227" text-anchor="middle" class="sk-t">Maschinenstundensatz</text><rect x="10" y="270" width="250" height="34" class="sk-body"/><text x="135" y="292" text-anchor="middle" class="sk-t acc">Zuschlagskalkulation</text><line x1="260" y1="27" x2="328" y2="27" class="sk-f" marker-end="url(#ar)"/><line x1="260" y1="92" x2="328" y2="92" class="sk-f" marker-end="url(#ar)"/><line x1="260" y1="157" x2="328" y2="157" class="sk-f" marker-end="url(#ar)"/><line x1="260" y1="222" x2="328" y2="222" class="sk-f" marker-end="url(#ar)"/><text x="294" y="20" text-anchor="middle" class="sk-t">ja</text><text x="294" y="85" text-anchor="middle" class="sk-t">ja</text><text x="294" y="150" text-anchor="middle" class="sk-t">ja</text><text x="294" y="215" text-anchor="middle" class="sk-t">ja</text><line x1="135" y1="44" x2="135" y2="73" class="sk-l" marker-end="url(#ar)"/><line x1="135" y1="109" x2="135" y2="138" class="sk-l" marker-end="url(#ar)"/><line x1="135" y1="174" x2="135" y2="203" class="sk-l" marker-end="url(#ar)"/><line x1="135" y1="239" x2="135" y2="268" class="sk-l" marker-end="url(#ar)"/><text x="143" y="64" class="sk-t">nein</text><text x="143" y="129" class="sk-t">nein</text><text x="143" y="194" class="sk-t">nein</text><text x="143" y="259" class="sk-t">nein</text>',cap:'Entscheidungsweg zum passenden Kalkulationsverfahren'}},
    {tab:[['Verfahren','Fertigungstyp','Beispiele'],['einstufige/mehrstufige Divisionskalkulation','Einproduktfertigung, Massenfertigung','Strom, Wasser, Druckluft, Normteil'],['ein-/mehrstufige Äquivalenzziffernkalkulation','Sortenfertigung mit gleichem Grundstoff bzw. Verfahren','Bleche, Ketten, Drähte, Schrauben verschiedener Größe'],['summarische/differenzierende Zuschlagskalkulation','Einzel- und Serienfertigung mehrerer Produkte','Maschinenbau, Lohnfertigung'],['Verrechnungssatzkalkulation','kapitalintensive Fertigung','Maschinenstundensatz für CNC-Zentren'],['Kuppelkalkulation','zwangsläufig gemeinsam entstehende Produkte','Roheisen, Gichtgas, Schlacke; Koks, Teer, Benzol']]},
    {bsp:{t:'Beispiel: Welches Verfahren für welchen Betrieb?',b:['Eigene Drucklufterzeugung eines Werks → Divisionskalkulation (€ je m³).','Schraubenfabrik mit Größen M6 bis M16 aus gleichem Draht → Äquivalenzziffern (z. B. nach Gewicht).','Lohnfertiger mit wechselnden Kundenteilen → differenzierende Zuschlagskalkulation.','Betrieb mit fünf 5-Achs-Zentren und kaum Personal an der Maschine → Maschinenstundensatzrechnung.']}},
    {merke:'Division und Äquivalenzziffern trennen nicht nach Einzel- und Gemeinkosten; Zuschlagsverfahren tun es – und brauchen deshalb eine Kostenstellenrechnung.'}
  ]},
  {t:'Divisionskalkulation',h:'Divisionskalkulation',pg:79,b:[
    {p:'Die Divisionskalkulation ist das einfachste Verfahren: Gesamtkosten durch Leistungsmenge. Sie setzt ein einziges Produkt voraus. Je nach Lagerbestandsveränderung wird ein-, zwei- oder mehrstufig gerechnet.'},
    {fx:['einstufig: Selbstkosten je Einheit = Gesamtkosten der Periode : Leistungsmenge','nur ein Produkt, keine Bestandsveränderung bei unfertigen und fertigen Erzeugnissen']},
    {fx:['zweistufig: k = Herstellkosten : produzierte Menge + Verwaltungs- und Vertriebskosten : abgesetzte Menge','bei Bestandsveränderung an fertigen Erzeugnissen']},
    {fx:['mehrstufig: k = Summe (Herstellkosten Stufe i : bearbeitete Menge Stufe i) + (VwK + VtK) : abgesetzte Menge','bei Zwischenlagern zwischen den Produktionsstufen']},
    {fx:['bewerteter Lagerzugang = Mehrmenge · Herstellkosten je Einheit bis zu dieser Stufe','']},
    {svg:{w:520,h:185,body:'<rect x="10" y="30" width="90" height="60" class="sk-body"/><text x="55" y="48" text-anchor="middle" class="sk-t acc">Stufe 1</text><text x="55" y="66" text-anchor="middle" class="sk-t">4.000 St.</text><text x="55" y="84" text-anchor="middle" class="sk-t">9 €/St.</text><line x1="100" y1="60" x2="113" y2="60" class="sk-f" marker-end="url(#ar)"/><rect x="115" y="45" width="60" height="30" class="fillacc"/><text x="145" y="64" text-anchor="middle" class="sk-t">+200</text><line x1="175" y1="60" x2="188" y2="60" class="sk-f" marker-end="url(#ar)"/><rect x="190" y="30" width="90" height="60" class="sk-body"/><text x="235" y="48" text-anchor="middle" class="sk-t acc">Stufe 2</text><text x="235" y="66" text-anchor="middle" class="sk-t">3.800 St.</text><text x="235" y="84" text-anchor="middle" class="sk-t">6 €/St.</text><line x1="280" y1="60" x2="293" y2="60" class="sk-f" marker-end="url(#ar)"/><rect x="295" y="45" width="60" height="30" class="fillacc"/><text x="325" y="64" text-anchor="middle" class="sk-t">+100</text><line x1="355" y1="60" x2="368" y2="60" class="sk-f" marker-end="url(#ar)"/><rect x="370" y="30" width="90" height="60" class="sk-body"/><text x="415" y="48" text-anchor="middle" class="sk-t acc">Stufe 3</text><text x="415" y="66" text-anchor="middle" class="sk-t">3.700 St.</text><text x="415" y="84" text-anchor="middle" class="sk-t">8 €/St.</text><line x1="415" y1="90" x2="415" y2="125" class="sk-f" marker-end="url(#ar)"/><text x="145" y="22" text-anchor="middle" class="sk-t">Zwischenlager</text><text x="325" y="22" text-anchor="middle" class="sk-t">Zwischenlager</text><text x="505" y="146" text-anchor="end" class="sk-t">Absatz 3.400 St., Fertiglager +300 St.</text><text x="505" y="170" text-anchor="end" class="sk-t acc">Selbstkosten 9 + 6 + 8 + 6 = 29 €/St.</text>',cap:'Mehrstufige Divisionskalkulation mit Zwischenlagern (Zahlen aus dem Beispiel)'}},
    {bsp:{t:'Beispiel: Einstufig – Druckluft',b:['Druckluftstation: Gesamtkosten 180.000 €/Jahr, erzeugt 1.200.000 m³.','Kosten je m³ = 180.000 € : 1.200.000 m³ = 0,15 €/m³ – Verrechnungspreis an die Kostenstellen.']}},
    {bsp:{t:'Beispiel: Zweistufig – Distanzhülsen mit Lageraufbau',b:['Produziert 25.000 Stück, Herstellkosten 50.000 €; verkauft 20.000 Stück; Verwaltungs- und Vertriebskosten 9.000 €.','k = 50.000 € : 25.000 + 9.000 € : 20.000 = 2,00 € + 0,45 € = 2,45 €/Stück','Lagerzugang 5.000 Stück · 2,00 € = 10.000 € (zu Herstellkosten).','Interpretation: Einstufig gerechnet (59.000 € : 25.000 = 2,36 €) würden Vertriebskosten auf Lagerware verteilt – die Stückkosten wären zu niedrig.']}},
    {bsp:{t:'Beispiel: Mehrstufig – Bolzen in drei Stufen',b:['Stufe 1 (Ablängen): 4.000 Stück, 36.000 € → 9,00 €/St. Stufe 2 (Drehen): 3.800 Stück, 22.800 € → 6,00 €/St. Stufe 3 (Härten): 3.700 Stück, 29.600 € → 8,00 €/St.','Verwaltung und Vertrieb: 20.400 € für 3.400 verkaufte Stück → 6,00 €/St.','Herstellkosten je fertigem Stück = 9 + 6 + 8 = 23,00 €; Selbstkosten = 29,00 €/St.','Bestandsmehrungen: nach Stufe 1: 200 · 9,00 € = 1.800 €; nach Stufe 2: 100 · 15,00 € = 1.500 €; Fertiglager: 300 · 23,00 € = 6.900 €.']}},
    {falle:'Lagerbestände immer mit den Herstellkosten bis einschließlich der letzten durchlaufenen Stufe bewerten – nie mit Selbstkosten (keine Verwaltungs- und Vertriebskosten im Bestand).'}
  ]},
  {t:'Äquivalenzziffernkalkulation',h:'Divisionskalkulation',pg:82,b:[
    {p:'Bei Sortenfertigung (ähnliche Produkte, gleiche Grundstoffe bzw. Verfahren, festes Kostenverhältnis) werden die Sorten über Äquivalenzziffern auf eine Einheitssorte umgerechnet. Dann wird wie bei der Division gerechnet.'},
    {ol:['Äquivalenzziffern festlegen (Einheitssorte = 1), z. B. nach Fertigungszeit, Gewicht, Durchmesser, Blechdicke oder Erfahrungswerten','Recheneinheiten = Menge · Äquivalenzziffer','Kosten je Recheneinheit = Gesamtkosten : Summe Recheneinheiten','Stückkosten je Sorte = Kosten je Recheneinheit · Äquivalenzziffer; Sortenkosten = Stückkosten · Menge']},
    {ul:['Einstufig: alle Produkte der Periode abgesetzt, keine Bestandsveränderung','Mehrstufig: getrennte Äquivalenzziffern je Kostenbereich (Material, Fertigung, Verwaltung/Vertrieb), wenn die Sorten Bereiche unterschiedlich beanspruchen oder Bestände sich ändern','Schwierigkeit: Ziffern müssen die tatsächlichen Kostenverhältnisse (Verursachung) abbilden']},
    {bsp:{t:'Beispiel: Rundstahlstäbe in drei Durchmessern',b:['Gesamtkosten der Periode 60.000 €, alles abgesetzt. Äquivalenzziffern nach Bearbeitungszeit: A = 1,0; B = 1,5; C = 2,0.']}},
    {tab:[['Sorte','Menge St.','ÄZ','Recheneinheiten','Kosten je St. €','Sortenkosten €'],['A','1.000','1,0','1.000','12,00','12.000'],['B','2.000','1,5','3.000','18,00','36.000'],['C','500','2,0','1.000','24,00','12.000'],['Summe','3.500','','5.000','','60.000']]},
    {p:'Kosten je Recheneinheit = 60.000 € : 5.000 RE = 12,00 €. Interpretation: Sorte C kostet doppelt so viel wie A. Liegt der Marktpreis für C unter 24 €, ist C nicht kostendeckend.'},
    {bsp:{t:'Beispiel: Mehrstufig nach Bereichen',b:['Materialkosten 30.000 € mit ÄZ nach Gewicht A 1 : B 1,2 : C 2 → Recheneinheiten 1.000 + 2.400 + 1.000 = 4.400 → 6,82 € je RE.','Fertigungskosten 30.000 € mit ÄZ nach Zeit A 1 : B 1,5 : C 2 → 5.000 RE → 6,00 € je RE.','Stückkosten C = 2 · 6,82 € + 2 · 6,00 € = 25,64 €; A = 6,82 € + 6,00 € = 12,82 €.','Interpretation: Mit getrennten Ziffern verschieben sich die Kosten je Sorte – genauer, wenn Material- und Zeitverhältnis auseinanderfallen.']}},
    {merke:'Äquivalenzziffern sind Verhältniszahlen zur Einheitssorte. Recheneinheiten = Menge · ÄZ – nie die Stückzahlen direkt addieren.'}
  ]},
  {t:'Zuschlagskalkulation',h:'Zuschlagskalkulation',pg:84,b:[
    {p:'In Mehrproduktbetrieben mit Einzel- oder Serienfertigung haben die Produkte unterschiedliche Kostenstrukturen. Einzelkosten werden direkt zugerechnet, Gemeinkosten per Zuschlag – unter der Annahme, dass sie proportional zu Material- bzw. Lohnkosten anfallen.'},
    {tab:[['Form','Vorgehen','Eignung'],['summarische Zuschlagskalkulation','ein einziger Zuschlag auf alle Einzelkosten, auf den Lohn (lohnintensiv) oder auf das Material (materialintensiv)','kleine Betriebe ohne Kostenstellenrechnung; ungenau'],['differenzierende Zuschlagskalkulation','getrennte Zuschläge je Bereich bzw. Kostenstelle aus dem BAB','Standardverfahren der Industrie']]},
    {svg:{w:520,h:372,body:'<rect x="20" y="10" width="200" height="40" class="sk-body"/><text x="120" y="27" text-anchor="middle" class="sk-t acc">Materialkosten</text><text x="120" y="44" text-anchor="middle" class="sk-t">MEK + MGK</text><rect x="260" y="10" width="240" height="40" class="sk-body"/><text x="380" y="27" text-anchor="middle" class="sk-t acc">Fertigungskosten</text><text x="380" y="44" text-anchor="middle" class="sk-t">FL + FGK + SEKF</text><line x1="120" y1="50" x2="120" y2="78" class="sk-f" marker-end="url(#ar)"/><line x1="380" y1="50" x2="224" y2="90" class="sk-f" marker-end="url(#ar)"/><rect x="20" y="80" width="200" height="32" class="sk-body"/><text x="120" y="101" text-anchor="middle" class="sk-t">Herstellkosten</text><line x1="120" y1="112" x2="120" y2="148" class="sk-l" marker-end="url(#ar)"/><text x="235" y="135" class="sk-t">+ VwGK, VtGK, SEK des Vertriebs</text><rect x="20" y="150" width="200" height="32" class="fillacc"/><text x="120" y="171" text-anchor="middle" class="sk-t">Selbstkosten</text><line x1="120" y1="182" x2="120" y2="208" class="sk-l" marker-end="url(#ar)"/><text x="235" y="200" class="sk-t">+ Gewinnzuschlag (auf SK)</text><rect x="20" y="210" width="200" height="32" class="sk-body"/><text x="120" y="231" text-anchor="middle" class="sk-t">Barverkaufspreis</text><line x1="120" y1="242" x2="120" y2="268" class="sk-l" marker-end="url(#ar)"/><text x="235" y="260" class="sk-t">+ Kundenskonto (im Hundert)</text><rect x="20" y="270" width="200" height="32" class="sk-body"/><text x="120" y="291" text-anchor="middle" class="sk-t">Zielverkaufspreis</text><line x1="120" y1="302" x2="120" y2="328" class="sk-l" marker-end="url(#ar)"/><text x="235" y="320" class="sk-t">+ Kundenrabatt (im Hundert)</text><rect x="20" y="330" width="200" height="32" class="sk-body"/><text x="120" y="351" text-anchor="middle" class="sk-t acc">Listenverkaufspreis</text>',cap:'Schema der differenzierenden Zuschlagskalkulation bis zum Listenverkaufspreis (netto)'}},
    {fx:['Barverkaufspreis = Selbstkosten + Gewinn; Zielverkaufspreis = Barverkaufspreis : (1 − Skontosatz)','Skonto vom Zielpreis = im Hundert']},
    {fx:['Listenverkaufspreis = Zielverkaufspreis : (1 − Rabattsatz)','Rabatt vom Listenpreis = im Hundert']},
    {bsp:{t:'Beispiel: Vorwärtskalkulation eines Getriebegehäuses',b:['Daten: MEK 200 €, MGK 10 %, Fertigungslohn 100 €, FGK 150 %, Sondereinzelkosten der Fertigung (Prüfvorrichtung anteilig) 30 €, VwGK 12 %, VtGK 8 %, SEK des Vertriebs (Spezialverpackung) 10 €, Gewinn 10 %, Skonto 2 %, Rabatt 10 %.']}},
    {tab:[['Position','Rechnung','€'],['Materialeinzelkosten','','200,00'],['+ Materialgemeinkosten','10 % von 200','20,00'],['= Materialkosten','','220,00'],['Fertigungslohn','','100,00'],['+ Fertigungsgemeinkosten','150 % von 100','150,00'],['+ SEK der Fertigung','','30,00'],['= Fertigungskosten','','280,00'],['= Herstellkosten','220 + 280','500,00'],['+ Verwaltungsgemeinkosten','12 % von 500','60,00'],['+ Vertriebsgemeinkosten','8 % von 500','40,00'],['+ SEK des Vertriebs','','10,00'],['= Selbstkosten','','610,00'],['+ Gewinn','10 % von 610','61,00'],['= Barverkaufspreis','','671,00'],['+ Kundenskonto','671 : 0,98 − 671','13,69'],['= Zielverkaufspreis','','684,69'],['+ Kundenrabatt','684,69 : 0,90 − 684,69','76,08'],['= Listenverkaufspreis netto','','760,77']]},
    {bsp:{t:'Beispiel: Differenzkalkulation bei vorgegebenem Marktpreis',b:['Der Kunde bietet 900 € Listenpreis bei 10 % Rabatt und 2 % Skonto. Selbstkosten wie oben 610 €.','Zielverkaufspreis = 900 € · 0,90 = 810,00 €; Barverkaufspreis = 810 € · 0,98 = 793,80 €','Gewinn = 793,80 € − 610,00 € = 183,80 € = 30,13 % der Selbstkosten','Interpretation: Der Auftrag ist auskömmlich. Ab einem Listenpreis unter 691,61 € (= 610 € : 0,98 : 0,90) würde der Auftrag die Vollkosten nicht mehr decken.']}},
    {bsp:{t:'Beispiel: Summarische Zuschlagskalkulation',b:['Kleiner Schlossereibetrieb: Gemeinkosten 300.000 €, Fertigungslöhne 120.000 € → Zuschlag 250 % auf den Lohn.','Auftrag Geländer: Material 450 €, Lohn 380 € → Selbstkosten = 450 € + 380 € + 950 € = 1.780 €.','Interpretation: Schnell, aber ungenau – ein materialintensiver Auftrag bekäme kaum Materialgemeinkosten.']}},
    {falle:'Skonto und Rabatt sind Abzüge vom jeweils höheren Preis: durch (1 − Satz) teilen, nicht mit (1 + Satz) multiplizieren. Rückwärts (Differenzkalkulation) wird dagegen mit (1 − Satz) multipliziert.'}
  ]},
  {t:'Verrechnungssatzkalkulation mit Maschinenstundensätzen',h:'Verrechnungssatzkalkulation',pg:86,abb:[['Tab. 6.1 Trennung der Gemeinkosten in MFGK und RFGK',88]],b:[
    {p:'Mit wachsender Automatisierung sinken die Löhne, die maschinenabhängigen Gemeinkosten steigen. Fertigungsgemeinkostenzuschläge von mehreren hundert Prozent auf den Lohn verteilen die Kosten dann verzerrt. Besser ist es, die Maschinenkosten über die Belegungszeit zu verrechnen.'},
    {fx:['FGK = maschinenabhängige FGK (MFGK) + Restfertigungsgemeinkosten (RFGK)','']},
    {fx:['Maschinenstundensatz MSS = MFGK pro Jahr : geplante Maschinenlaufzeit pro Jahr','Laufzeit = Arbeitstage · Schichten · Stunden je Schicht − Stillstandszeiten']},
    {fx:['RFGK-Zuschlagssatz = Restfertigungsgemeinkosten : Fertigungslöhne · 100','Rest: Hilfslöhne, Gehälter, Sozialkosten, Büromaterial usw.']},
    {fx:['Fertigungskosten = Fertigungslohn + RFGK + Maschinenzeit (h) · MSS','']},
    {tab:[['Kostenart im MSS','Berechnung','fix/variabel'],['kalk. Abschreibung','(WBW − Restwert) : Nutzungsdauer','fix (zeitabhängig)'],['kalk. Zinsen','(Anschaffungskosten + Restwert) : 2 · Zinssatz','fix'],['Instandhaltung','WBW bzw. AK · Instandhaltungsfaktor','meist fix bzw. gemischt'],['Raumkosten','Fläche · Mietsatz','fix'],['Versicherung','Prämie','fix'],['Energie','Anschlusswert · Lastfaktor · Strompreis · Laufzeit','variabel'],['Kühlschmierstoff','Verbrauch je h · Preis · Laufzeit','variabel'],['Werkzeuge','Satz je Maschinenstunde · Laufzeit','variabel']]},
    {bsp:{t:'Beispiel: Maschinenstundensatz eines Bearbeitungszentrums',b:['Daten: Anschaffung 250.000 €, Wiederbeschaffungswert 280.000 €, Nutzungsdauer 10 Jahre, Restwert 20.000 €, Zins 7 %; Anschlusswert 30 kW, Lastfaktor 0,6, Strom 0,22 €/kWh; Kühlschmierstoff 2 l/h zu 1,50 €/l; Instandhaltung 4 % vom WBW; Fläche 25 m² zu 12 €/m² und Monat; Werkzeuge 3,00 €/h; Versicherung 1.800 €/Jahr.','Laufzeit: 220 Tage · 2 Schichten · 8 h = 3.520 h − 15 % Stillstand = 2.992 h/Jahr.']}},
    {tab:[['Kostenart','Rechnung','€/Jahr'],['kalk. Abschreibung','(280.000 − 20.000) : 10','26.000,00'],['kalk. Zinsen','(250.000 + 20.000) : 2 · 0,07','9.450,00'],['Instandhaltung','280.000 · 0,04','11.200,00'],['Raumkosten','25 · 12 · 12','3.600,00'],['Versicherung','','1.800,00'],['Summe fix','','52.050,00'],['Energie','30 · 0,6 · 0,22 · 2.992','11.848,32'],['Kühlschmierstoff','2 · 1,50 · 2.992','8.976,00'],['Werkzeuge','3,00 · 2.992','8.976,00'],['Summe variabel','','29.800,32'],['Maschinenkosten gesamt','','81.850,32']]},
    {p:'MSS = 81.850,32 € : 2.992 h = 27,36 €/h (fix 17,40 €/h + variabel 9,96 €/h). Ein Teil mit 0,4 h Fertigungslohn zu 24 €/h, RFGK 120 % und 18 min Maschinenzeit kostet: 9,60 € + 11,52 € + 0,3 h · 27,36 € (8,21 €) = 29,33 € Fertigungskosten.'},
    {bsp:{t:'Beispiel: Auslastung sinkt auf 80 %',b:['Laufzeit nur noch 2.992 h · 0,8 = 2.393,6 h. MSS neu = 52.050 € : 2.393,6 h + 9,96 €/h = 21,75 € + 9,96 € = 31,71 €/h.','Wird weiter mit 27,36 €/h kalkuliert, werden nur 80 % der Fixkosten verrechnet; 20 % · 52.050 € = 10.410 € bleiben ungedeckt – das Betriebsergebnis sinkt entsprechend.','Interpretation: Der MSS hängt stark von der geplanten Auslastung ab. Bei Unterauslastung lieber Aufträge mit positivem Deckungsbeitrag hereinholen als den Satz zu erhöhen (Preise würden noch weniger wettbewerbsfähig).']}},
    {bsp:{t:'Beispiel: Zuschlag gegen Maschinenstundensatz',b:['Kostenstelle: FGK 540.000 €, Fertigungslöhne 120.000 € → FGKZ 450 %. Davon maschinenabhängig 396.000 € → RFGK 144.000 € → RFGKZ 120 %. MSS 27,36 €/h.','Teil X (lohnintensiv): FL 6,00 €, Maschinenzeit 3 min. Alt: 6,00 € + 450 % = 33,00 €. Neu: 6,00 € + 7,20 € + 0,05 h · 27,36 € = 14,57 €.','Teil Y (maschinenintensiv): FL 1,50 €, Maschinenzeit 20 min. Alt: 1,50 € + 6,75 € = 8,25 €. Neu: 1,50 € + 1,80 € + 9,12 € = 12,42 €.','Interpretation: Mit Lohnzuschlag wurde X zu teuer und Y zu billig angeboten – genau die Fehler, die man an verlorenen bzw. verlustbringenden Aufträgen bemerkt.']}},
    {merke:'Maschinenstundensatz = verursachungsgerechte Verteilung der Maschinenkosten nach Belegungszeit. Fixe Bestandteile machen den Satz auslastungsabhängig.'}
  ]},
  {t:'Deckungsbeitragsrechnung: Grundlagen und Programmentscheidungen',h:'Deckungsbeitragsrechnung',pg:89,abb:[['Abb. 6.1 Struktur Vollkosten- vs. einstufige Deckungsbeitragsrechnung',90]],b:[
    {p:'Vollkostenverfahren schlüsseln Gemeinkosten mehrfach (Stellen, Umlage, Zuschlag) und behandeln Fixkosten so, als stiegen sie mit den Einzelkosten. Für kurzfristige, marktorientierte Entscheidungen ist das ungeeignet. Teilkostenverfahren – Deckungsbeitragsrechnung auf Istbasis und Grenzplankostenrechnung auf Planbasis – rechnen den Produkten nur variable Kosten zu.'},
    {ul:['Voraussetzungen der einstufigen Deckungsbeitragsrechnung (Direct Costing, USA 1950er): Kostenauflösung in fix und variabel, stabile Marktpreise, konstante Grenzkosten','Fixkosten entstehen aus Strukturen und Kapazitäten (Maschine, Halle, Darlehenszinsen, Verwaltung) und lassen sich kurzfristig nicht abbauen','Anwendungen: Betriebsergebnisrechnung, Gewinnschwelle, Programm- und Verfahrenswahl, Make-or-buy, Preisuntergrenzen, Zusatzaufträge']},
    {fx:['DB = Umsatzerlöse U − variable Kosten Kv; db = p − kv; DB = x · db','Deckungsbeitrag deckt Fixkosten und bildet Gewinn']},
    {fx:['Betriebsergebnis = Summe der Deckungsbeiträge − Fixkosten','']},
    {fx:['relativer Deckungsbeitrag = db : Engpassbeanspruchung je Stück','Rangfolge bei Engpass']},
    {svg:{w:520,h:232,body:'<text x="130" y="22" text-anchor="middle" class="sk-t acc">Vollkostenrechnung</text><rect x="40" y="35" width="180" height="30" class="sk-body"/><text x="130" y="55" text-anchor="middle" class="sk-t">Umsatzerlöse</text><rect x="40" y="70" width="180" height="30" class="sk-body"/><text x="130" y="90" text-anchor="middle" class="sk-t">− Selbstkosten</text><rect x="40" y="175" width="180" height="30" class="fillacc"/><text x="130" y="195" text-anchor="middle" class="sk-t">= Betriebsergebnis</text><line x1="130" y1="100" x2="130" y2="173" class="sk-c"/><text x="390" y="22" text-anchor="middle" class="sk-t acc">Deckungsbeitragsrechnung</text><rect x="300" y="35" width="180" height="30" class="sk-body"/><text x="390" y="55" text-anchor="middle" class="sk-t">Umsatzerlöse</text><rect x="300" y="70" width="180" height="30" class="sk-body"/><text x="390" y="90" text-anchor="middle" class="sk-t">− variable Kosten</text><rect x="300" y="105" width="180" height="30" class="sk-body"/><text x="390" y="125" text-anchor="middle" class="sk-t acc">= Deckungsbeitrag</text><rect x="300" y="140" width="180" height="30" class="sk-body"/><text x="390" y="160" text-anchor="middle" class="sk-t">− Fixkosten (Block)</text><rect x="300" y="175" width="180" height="30" class="fillacc"/><text x="390" y="195" text-anchor="middle" class="sk-t">= Betriebsergebnis</text><line x1="220" y1="190" x2="300" y2="190" class="sk-c"/><text x="260" y="224" text-anchor="middle" class="sk-t">gleiches Ergebnis, andere Entscheidungsbasis</text>',cap:'Aufbau von Vollkosten- und einstufiger Deckungsbeitragsrechnung'}},
    {bsp:{t:'Beispiel: Vollkosten- gegen Deckungsbeitragsrechnung (drei Produkte)',b:['Fixkosten des Betriebs 330.000 €, in der Vollkostenrechnung im Verhältnis der variablen Kosten verteilt (51,5625 %).']}},
    {tab:[['Produkt','Menge','p €','kv €','db €','DB €','Fixanteil €','Vollkostenergebnis €'],['Pumpengehäuse','4.000','95','55','40','160.000','113.437,50','+46.562,50'],['Flansch','10.000','32','24','8','80.000','123.750,00','−43.750,00'],['Lagerbock','6.000','48','30','18','108.000','92.812,50','+15.187,50'],['Summe','','','','','348.000','330.000,00','+18.000,00']]},
    {p:'Interpretation: Nach Vollkosten scheint der Flansch ein Verlustbringer. Er erwirtschaftet aber 80.000 € Deckungsbeitrag. Ohne Flansch blieben die 330.000 € Fixkosten bestehen: Betriebsergebnis = 268.000 € − 330.000 € = −62.000 € statt +18.000 €. Also behalten und Preis bzw. Kosten verbessern.'},
    {bsp:{t:'Beispiel: Engpass auf dem Bearbeitungszentrum',b:['Kapazität im Planzeitraum 60.000 min. Bedarf je Stück: Pumpengehäuse 8 min, Flansch 1,5 min, Lagerbock 4 min; Absatzhöchstmengen wie oben (Bedarf gesamt 71.000 min > 60.000 min).','Relativer DB: Flansch 8 € : 1,5 min = 5,33 €/min; Pumpengehäuse 40 € : 8 min = 5,00 €/min; Lagerbock 18 € : 4 min = 4,50 €/min.','Programm nach relativem DB: 10.000 Flansche (15.000 min, DB 80.000 €), 4.000 Gehäuse (32.000 min, 160.000 €), Rest 13.000 min → 3.250 Lagerböcke (58.500 €). Summe 298.500 €.','Programm nach absolutem db (Gehäuse, Lagerbock, Flansch): 160.000 € + 108.000 € + 2.666 Flansche · 8 € = 289.328 €.','Interpretation: Die Engpassplanung bringt 9.172 € mehr Deckungsbeitrag – die Fixkosten bleiben gleich, also steigt das Ergebnis um denselben Betrag.']}},
    {falle:'Bei Engpässen nicht nach dem absoluten Stück-DB, sondern nach dem DB je Engpasseinheit (€/min) entscheiden. Produkte mit positivem DB nicht streichen, nur weil sie nach Vollkosten Verlust zeigen.'}
  ]},
  {t:'Gewinnschwelle, Zusatzaufträge und Preisuntergrenzen',h:'Deckungsbeitragsrechnung',pg:92,abb:[['Abb. 6.2 Break-even-Point',92]],b:[
    {p:'Für ein Einproduktunternehmen lässt sich aus der DB-Rechnung die Gewinnschwelle ableiten: die Menge, bei der der Deckungsbeitrag genau die Fixkosten deckt. Darunter liegt die Verlust-, darüber die Gewinnzone; bei linearen Verläufen liegt das Gewinnmaximum an der Kapazitätsgrenze.'},
    {fx:['Gewinn G = U − K = p · x − (Kf + kv · x)','']},
    {fx:['Gewinnschwelle (Break-even-Menge) xBE = Kf : (p − kv)','Break-even-Umsatz = xBE · p = Kf : DB-Quote']},
    {fx:['DB-Quote = DB : Umsatz · 100','Anteil des Umsatzes, der zur Fixkostendeckung bleibt']},
    {svg:{w:520,h:270,body:'<line x1="60" y1="240" x2="495" y2="240" class="sk-l" marker-end="url(#ar)"/><line x1="60" y1="240" x2="60" y2="20" class="sk-l" marker-end="url(#ar)"/><text x="68" y="30" class="sk-t">€</text><text x="495" y="262" text-anchor="end" class="sk-t">Menge x</text><line x1="60" y1="170" x2="460" y2="170" class="sk-c"/><text x="455" y="163" text-anchor="end" class="sk-t">Fixkosten</text><line x1="60" y1="170" x2="460" y2="70" class="sk-l thick"/><line x1="60" y1="240" x2="460" y2="30" class="sk-f"/><text x="455" y="120" text-anchor="end" class="sk-t">Gesamtkosten K</text><text x="455" y="24" text-anchor="end" class="sk-t acc">Erlöse U</text><circle cx="314.5" cy="106.4" r="5" class="fillacc"/><line x1="314.5" y1="106.4" x2="314.5" y2="240" class="sk-c"/><text x="314" y="256" text-anchor="middle" class="sk-t">xBE</text><text x="120" y="188" text-anchor="middle" class="sk-t">Verlust</text><text x="430" y="68" text-anchor="middle" class="sk-t">Gewinn</text>',cap:'Gewinnschwelle: Erlösgerade schneidet die Gesamtkostengerade'}},
    {tab:[['Entscheidung','Regel (kurzfristig, Fixkosten unverändert)'],['Zusatzauftrag bei freier Kapazität','annehmen, wenn Preis > kv (positiver db)'],['kurzfristige Preisuntergrenze','= variable Stückkosten'],['langfristige Preisuntergrenze','= Selbstkosten je Stück (Vollkosten)'],['Sortiment','Produkte mit positivem DB behalten'],['Engpass','Rangfolge nach relativem DB'],['Make-or-buy','Fremdpreis mit kv vergleichen']]},
    {bsp:{t:'Beispiel: Gewinnschwelle eines Kompressorventils',b:['Preis 80 €/Stück, variable Kosten 50 €/Stück, Fixkosten 60.000 €/Jahr, Kapazität 3.000 Stück.','db = 80 € − 50 € = 30 €; xBE = 60.000 € : 30 € = 2.000 Stück; Break-even-Umsatz = 160.000 €.','Bei 2.500 Stück: Gewinn = 2.500 · 30 € − 60.000 € = 15.000 €; bei 1.500 Stück: Verlust −15.000 €.','Interpretation: Ab dem 2.001. Stück trägt jedes Ventil 30 € zum Gewinn bei. Die Sicherheitsstrecke bei 2.500 Stück beträgt 20 %.']}},
    {bsp:{t:'Beispiel: Zusatzauftrag zum Sonderpreis',b:['Ein Kunde will 1.500 Lagerböcke zu 38 €/Stück (Listenpreis 48 €, kv 30 €, Selbstkosten nach Vollkosten 45,47 €). Freie Kapazität ist vorhanden.','Zusätzlicher DB = 1.500 · (38 € − 30 €) = 12.000 € → Ergebnisverbesserung um 12.000 €.','Interpretation: Kurzfristig annehmen. Risiken prüfen: Preisdruck bei Stammkunden, Kapazitätsbindung, falls später lukrativere Aufträge kommen.']}},
    {bsp:{t:'Beispiel: Mehrstufige Deckungsbeitragsrechnung',b:['Produktgruppe Pumpen: DB I der Produkte A 120.000 € und B 50.000 €; produktfixe Kosten (Sondervorrichtung von B) 60.000 € → DB II von B = −10.000 €.','Gruppenfixe Kosten (Pumpenmontage) 70.000 € → DB III der Gruppe = 170.000 € − 60.000 € − 70.000 € = 40.000 €.','Interpretation: B deckt nicht einmal seine eigenen Fixkosten; fallen diese bei Aufgabe von B weg, verbessert sich das Ergebnis um 10.000 €.']}},
    {merke:'Langfristig müssen alle Kosten gedeckt werden. Kurzfristige Entscheidungen auf Teilkostenbasis dürfen nicht zur Dauerpreispolitik werden.'}
  ]},
  {t:'Gliederung der Zeitarten',h:'Gliederung der Zeitarten',pg:98,abb:[['Abb. 7.1 Zeitgliederung für die Auftragszeit',98]],b:[
    {p:'Zeitarten kennzeichnen Ablaufabschnitte wie Vorgänge, Teilvorgänge, Vorgangsstufen und -elemente. REFA unterscheidet die Zeiten für den Menschen (Auftragszeit) und für das Betriebsmittel (Belegungszeit). Vorgabezeiten sind Basis für Kalkulation, Terminplanung, Kapazitätsplanung und Leistungslohn.'},
    {svg:{w:520,h:250,body:'<rect x="170" y="12" width="180" height="34" class="sk-body"/><text x="260" y="34" text-anchor="middle" class="sk-t acc">Auftragszeit T</text><line x1="260" y1="46" x2="260" y2="60" class="sk-l"/><line x1="120" y1="60" x2="380" y2="60" class="sk-l"/><line x1="120" y1="60" x2="120" y2="75" class="sk-l"/><line x1="380" y1="60" x2="380" y2="75" class="sk-l"/><rect x="40" y="75" width="160" height="34" class="sk-body"/><text x="120" y="97" text-anchor="middle" class="sk-t">Rüstzeit tr</text><rect x="280" y="75" width="200" height="34" class="sk-body"/><text x="380" y="97" text-anchor="middle" class="sk-t">Ausführungszeit ta = m · te</text><line x1="380" y1="109" x2="380" y2="135" class="sk-l"/><rect x="290" y="135" width="180" height="34" class="sk-body"/><text x="380" y="157" text-anchor="middle" class="sk-t">Zeit je Einheit te</text><line x1="380" y1="169" x2="380" y2="183" class="sk-l"/><line x1="200" y1="183" x2="440" y2="183" class="sk-l"/><line x1="200" y1="183" x2="200" y2="198" class="sk-l"/><line x1="320" y1="183" x2="320" y2="198" class="sk-l"/><line x1="440" y1="183" x2="440" y2="198" class="sk-l"/><rect x="145" y="198" width="110" height="34" class="sk-body"/><rect x="265" y="198" width="110" height="34" class="sk-body"/><rect x="385" y="198" width="110" height="34" class="sk-body"/><text x="200" y="220" text-anchor="middle" class="sk-t">Grundzeit tg</text><text x="320" y="220" text-anchor="middle" class="sk-t">Erholzeit ter</text><text x="440" y="220" text-anchor="middle" class="sk-t">Verteilzeit tv</text>',cap:'Gliederung der Auftragszeit (die Rüstzeit teilt sich ebenso in Rüstgrund-, Rüsterhol- und Rüstverteilzeit)'}},
    {fx:['Auftragszeit T = tr + ta = tr + m · te','tr = Rüstzeit, m = Menge, te = Zeit je Einheit']},
    {fx:['te = tg + ter + tv; tg = tt + tw','Grundzeit = Tätigkeitszeit + Wartezeit; dazu Erhol- und Verteilzeit']},
    {fx:['tr = trg + trer + trv','Rüstgrund-, Rüsterhol-, Rüstverteilzeit']},
    {fx:['Belegungszeit TbB = trB + taB = trB + m · teB','Zeit, in der das Betriebsmittel belegt ist; häufigster Praxisfall']},
    {fx:['tv = tg · zv : 100; ter = tg · zer : 100','Verteil- und Erholzeit meist als Prozentzuschlag auf die Grundzeit']},
    {bsp:{t:'Beispiel: Auftragszeit für 120 Schaltwellen',b:['Rüstzeit tr = 30 min, Grundzeit tg = 2,5 min/Stück, Verteilzeitzuschlag zv = 8 %, Erholzeitzuschlag zer = 4 %.','te = 2,5 min · (1 + 0,08 + 0,04) = 2,80 min','ta = 120 · 2,80 min = 336 min; T = 30 min + 336 min = 366 min = 6,1 h','Belegungszeit der Maschine: trB = 25 min, teB = 2,2 min → TbB = 25 + 120 · 2,2 = 289 min.','Bei Teilung in zwei Lose zu je 60 Stück: 2 · (30 + 60 · 2,8) = 396 min – die Rüstzeit fällt doppelt an.','Interpretation: Für den Lohn zählt T, für Maschinenkosten und Kapazitätsplanung TbB.']}},
    {falle:'Zuschläge beziehen sich auf die Grundzeit, nicht auf die schon erhöhte Zeit je Einheit. Und Rüstzeit nur einmal je Los ansetzen.'}
  ]},
  {t:'Leistungsgrad und Zeitgrad',h:'Leistungsgrad und Zeitgrad',pg:99,b:[
    {p:'Der Leistungsgrad beurteilt bei einer Zeitaufnahme, wie schnell und wirksam jemand im Vergleich zur Bezugs- bzw. Normalleistung arbeitet. Er wird nur bei vom Menschen beeinflussbaren Abläufen und laufend während der Aufnahme beurteilt – das setzt Erfahrung des Beobachters voraus. Der Zeitgrad vergleicht nachträglich Vorgabezeit und tatsächlich gebrauchte Zeit.'},
    {fx:['Leistungsgrad L in % = beobachtete Istleistung : Normalleistung · 100','']},
    {fx:['Normalzeit (Sollzeit) = gemessene Istzeit · L : 100','']},
    {fx:['Zeitgrad in % = Vorgabezeit : Istzeit · 100; Zeitgradfaktor = Zeitgrad : 100','für Auftrag, Person, Abteilung oder Periode']},
    {tab:[['Größe','wann?','wozu?'],['Leistungsgrad','während der Zeitaufnahme','Istzeiten auf Normalleistung umrechnen'],['Zeitgrad','nach Abschluss (Woche, Monat, Auftrag)','Leistung beurteilen, Akkordverdienst, Kapazitätsplanung']]},
    {bsp:{t:'Beispiel: Zeitaufnahme und Zeitgrad in der Montage',b:['Bei einer Zeitaufnahme werden für das Fügen eines Lagers im Mittel 6,0 min gemessen; der REFA-Beauftragte beurteilt den Leistungsgrad mit 120 %.','Normalzeit = 6,0 min · 120 : 100 = 7,2 min (bei Normalleistung würde der Vorgang 7,2 min dauern).','Wochenauswertung einer Monteurin: Vorgabezeit aller Aufträge 2.430 min, gebrauchte Zeit 2.160 min → Zeitgrad = 2.430 : 2.160 · 100 = 112,5 % (Faktor 1,125).','Interpretation: Ein dauerhaft sehr hoher Zeitgrad (über ca. 130 %) deutet auf zu großzügige Vorgabezeiten hin – Methodenänderung prüfen und Zeiten neu ermitteln (Betriebsrat einbeziehen).']}},
    {merke:'Zeitgrad lässt sich steigern durch weniger Verteilzeiten oder optimale Schnittdaten, nicht nur durch schnelleres Arbeiten.'}
  ]},
  {t:'Methoden der Datenermittlung',h:'Methoden der Datenermittlung',pg:100,b:[
    {p:'Vorgabezeiten werden je nach Fertigungsart, Genauigkeitsbedarf und Aufwand unterschiedlich ermittelt.'},
    {tab:[['Methode','Vorgehen','Einsatz'],['Zeitaufnahme (REFA)','Arbeitssystem beschreiben, Bezugsmengen und Einflussgrößen erfassen, Leistungsgrad beurteilen, Istzeiten messen (Stoppuhr, elektronisch) und auswerten','Serienfertigung, Grundlage für Planzeiten'],['Systeme vorbestimmter Zeiten','Bewegungselemente mit tabellierten Normzeiten: MTM (quantitative und qualitative Einflüsse, z. B. Körperhaltung), Work-Factor (nur messbare Einflüsse)','manuelle Abläufe planen, auch Einzelfertigung mit Bausteinen'],['Berechnen','Prozess- bzw. Hauptzeiten aus Weg, Drehzahl, Vorschub','Maschinenarbeit ohne menschlichen Einfluss'],['Schätzen','Erfahrung, schnell, nicht nachprüfbar','Einzelfertigung, kurzfristig'],['Vergleichen','Vergleich mit bekannten Abläufen; besser als Schätzen','ähnliche Teile'],['Planzeiten','Sollzeiten für wiederkehrende Abschnitte, Lücken durch Interpolation','ähnliche Aufgaben, Betriebsmittel oder Arbeitsgänge']]},
    {fx:['Hauptzeit th = L · i : (n · f)','L = Vorschubweg inkl. An- und Überlauf (mm), i = Anzahl Schnitte, n = Drehzahl (1/min), f = Vorschub (mm)']},
    {fx:['Verteilzeitprozentsatz zv = Summe Verteilzeiten : Summe Grundzeiten · 100','aus Verteilzeitaufnahme oder Multimomentaufnahme']},
    {tab:[['Verteilzeit','Beispiele'],['sachlich konstant (auftragsunabhängig)','Arbeitsplatz zu Schichtbeginn vorbereiten, aufräumen, planmäßiges Abschmieren'],['sachlich variabel (auftragsabhängig)','kurze Störungen, Werkzeugbruch, kleine Störungen an Betriebsmitteln beseitigen'],['persönlich','Toilettengang, persönliche Verrichtungen, Licht und Lüftung regeln'],['nicht zu verwenden','Nichteinhalten der Arbeitszeit, Privatgespräche, selbst verschuldete Mehrarbeit'],['fallweise zu verwenden','längerer Energieausfall, große Reparaturen, fehlende Materialbereitstellung']]},
    {ul:['Vorteile von Planzeiten: keine neuen Zeitaufnahmen bei wechselnden Teilen, planbare Abläufe, genauere und einfachere Vorkalkulation, Zeittabellen (Richtzeiten, Zeitnormen), klar beschriebener Gültigkeitsbereich','Schätzungen werden genauer, wenn in Teilzeiten geschätzt wird (Fehlerausgleich)','Hauptzeiten hängen außerdem ab von Werkstückaufspannung, Antriebsleistung, Werkstoff und Werkzeuggeometrie']},
    {bsp:{t:'Beispiel: Hauptzeit beim Längsdrehen und Verteilzeitzuschlag',b:['Welle Ø 40 mm, Drehlänge 120 mm + 2 mm Anlauf = 122 mm, 2 Schnitte, n = 800 1/min, f = 0,2 mm.','th = 122 mm · 2 : (800 1/min · 0,2 mm) = 1,525 min ≈ 1,53 min','Verteilzeitaufnahme über zwei Wochen: Verteilzeiten 540 min, Grundzeiten 6.750 min → zv = 540 : 6.750 · 100 = 8 %.','Interpretation: Mit höherem Vorschub (f = 0,25 mm) sänke th auf 1,22 min – wenn Oberfläche und Standzeit es zulassen. Der Meister prüft Schnittdaten mit der Arbeitsvorbereitung.']}},
    {merke:'MTM berücksichtigt messbare und zu beurteilende Einflussgrößen, Work-Factor nur messbare. Schätzen ist schnell, aber nicht nachprüfbar.'}
  ]},
  {t:'Multimomentaufnahme',h:'Multimomentaufnahme als Methode zur Ermittlung von Zeitanteilen',pg:102,b:[
    {p:'Die Multimomentaufnahme erfasst nach dem Zufallsprinzip in vielen kurzen Beobachtungen, wie häufig vorher festgelegte Ablauf- oder Zeitarten an einem oder mehreren Arbeitssystemen vorkommen. Sie läuft meist über mehrere Wochen; die Beobachtungen werden auf einem Aufnahmebogen notiert und hochgerechnet.'},
    {ul:['Einsatz: betriebliche Kennzahlen (Auslastungsgrad, Arbeitskräftebedarf, Tätigkeits- und Belastungsprofile), Untersuchungen zu Personaleinsatz, Materialfluss und Durchlaufzeiten','In der Praxis häufig zur Ermittlung von Verteilzeitzuschlägen','Vorteile: viele Arbeitsplätze gleichzeitig, geringer Aufwand, wenig Störung der Beschäftigten; Nachteil: keine Einzelzeiten, statistische Unsicherheit']},
    {fx:['Anteil p = Anzahl Beobachtungen der Ablaufart : Gesamtzahl der Beobachtungen','']},
    {fx:['Vertrauensbereich (95 %): f = ± 1,96 · √(p · (1 − p) : n); nötiger Umfang n = 1,96² · p · (1 − p) : f²','f als absolute Genauigkeit (Anteil)']},
    {bsp:{t:'Beispiel: Stillstandsanteil von sechs Drehmaschinen',b:['In vier Wochen 1.600 Zufallsbeobachtungen; 240-mal stand eine Maschine still.','p = 240 : 1.600 = 15 %','Genauigkeit f = 1,96 · √(0,15 · 0,85 : 1.600) = 0,0175 → Stillstand liegt mit 95 % Sicherheit zwischen 13,25 % und 16,75 %.','Für ± 2 Prozentpunkte hätten n = 1,96² · 0,15 · 0,85 : 0,02² ≈ 1.225 Beobachtungen genügt.','Interpretation: 15 % Stillstand bei 6 Maschinen · 3.500 h ≈ 3.150 Maschinenstunden im Jahr; Ursachen (Rüsten, Warten auf Material) gezielt mit einer Folgeaufnahme aufschlüsseln.']}},
    {merke:'Je mehr Beobachtungen, desto genauer – der Umfang wird vorab aus gewünschter Genauigkeit und geschätztem Anteil festgelegt.'}
  ]},
  {t:'Anforderungsermittlung',h:'Anforderungsermittlung',pg:103,abb:[['Abb. 7.2 Anforderungsarten',103]],b:[
    {p:'Die Anforderungsermittlung beschreibt Arbeitssysteme und analysiert und quantifiziert, welche Anforderungen sie an den Menschen stellen. Sie dient der anforderungsabhängigen Entgeltdifferenzierung, der Personalorganisation und der Arbeitsgestaltung.'},
    {tab:[['Vorgehen','Kennzeichen','Verfahren'],['summarisch','Arbeit als Ganzes bewertet, Können im Vordergrund, Einstufung in Lohngruppen','Rangfolge-, Lohngruppenverfahren'],['analytisch','Anforderungsarten einzeln erfasst und gewichtet','Genfer Schema, REFA-Verfahren (Rangreihe mit getrennter Gewichtung), Stufenwertzahlverfahren']]},
    {ol:['Arbeitsbeschreibung: Arbeitsaufgabe, Arbeitsablauf, Arbeitsmittel, Arbeitsgegenstand, Umgebung (der Mensch selbst wird nicht beschrieben)','Anforderungsanalyse: Anforderungsarten bestimmen – Kenntnisse, Geschicklichkeit, Verantwortung (für eigene Arbeit, Arbeit anderer, Sicherheit anderer), geistige Belastung, muskelmäßige Belastung (dynamisch, statisch, einseitig), Umgebungseinflüsse (Temperatur, Öl, Schmutz, Staub, Lärm, Blendung, Erkältungs- und Unfallgefahr, Schutzkleidung)','Quantifizierung: Anforderungswert = Rangplatz · Gewichtungsfaktor; Wertzahlsumme = Summe aller Anforderungswerte → Lohngruppe bzw. Lohn']},
    {fx:['Anforderungswert = Rangplatz-Nr. · Gewichtungsfaktor; Wertzahlsumme = Σ Anforderungswerte','']},
    {fx:['Stundenlohn = Grundlohn + Wertzahlsumme · Geldfaktor','']},
    {bsp:{t:'Beispiel: Arbeitsplatz CNC-Fräsen bewerten',b:['Anforderungswerte (Rangplatz · Gewicht):']}},
    {tab:[['Anforderungsart','Rangplatz','Gewicht','Wert'],['Fachkenntnisse','28','1,0','28'],['Geschicklichkeit','25','0,8','20'],['Verantwortung','20','0,6','12'],['geistige Belastung','15','0,6','9'],['muskelmäßige Belastung','10','0,5','5'],['Umgebung (Lärm, Öl)','16','0,5','8'],['Wertzahlsumme','','','82']]},
    {p:'Lohn = 14,00 € Grundlohn + 82 · 0,05 € = 18,10 €/h. Interpretation: Die Bewertung hängt am Arbeitsplatz, nicht an der Person – die individuelle Leistung wird getrennt über Leistungsentgelt berücksichtigt.'},
    {merke:'Summarisch = schnell, wenig differenziert. Analytisch = nachvollziehbar, aufwendig. In Tarifverträgen (z. B. ERA Metall- und Elektroindustrie) sind die Bewertungsverfahren festgelegt.'}
  ]},
  {t:'Entgeltmanagement',h:'Entgeltmanagement',pg:104,b:[
    {p:'Grundlage der Entlohnung sind Tarifverträge zwischen Arbeitgeberverbänden (oder einzelnen Arbeitgebern) und Gewerkschaften. Betriebsvereinbarungen regeln die Umsetzung vor Ort. Bei der betrieblichen Lohngestaltung hat der Betriebsrat ein Mitbestimmungsrecht (§ 87 Abs. 1 Nr. 10 und 11 BetrVG).'},
    {tab:[['Differenzierung','Maßstab'],['anforderungsabhängig','Anforderungen des Arbeitsplatzes (Arbeitsbewertung)'],['leistungsabhängig','individuelle Leistung und Leistungsfähigkeit (Akkord, Prämie, Leistungszulage)']]},
    {tab:[['Entlohnungsgrundsatz','Prinzip','Hinweis'],['Zeitentgelt','Entgelt nach Arbeitszeit, Leistung wird nicht gemessen','oft mit Leistungszulage aus Beurteilung'],['Prämienentgelt','Grundlohn + Prämie (Menge, Qualität, Ersparnis, Nutzung; kombinierbar)','Prämie kann linear, progressiv oder degressiv verlaufen'],['Akkordentgelt','Entgelt nach Menge: Geld- oder Zeitakkord, Einzel- oder Gruppenakkord','Vorgabezeiten müssen nachprüfbar sein']]},
    {bsp:{t:'Beispiel: Zeit-, Akkord- und Prämienlohn bei 8, 10 und 12 Stück/h',b:['Zeitlohn 17,50 €/h. Akkord: Grundlohn 17,50 €/h + 15 % Zuschlag = Akkordrichtsatz 20,125 €/h bei Normalleistung 10 Stück/h → Stückgeld 2,0125 €; garantierter Mindestlohn 17,50 €/h. Prämie: Grundlohn 12,00 €/h + 0,60 € je Stück.']}},
    {tab:[['Leistung','Zeitlohn €/h','Akkordlohn €/h','Prämienlohn €/h'],['8 St./h','17,50','17,50 (Garantie; rechnerisch 16,10)','16,80'],['10 St./h','17,50','20,13','18,00'],['12 St./h','17,50','24,15','19,20']]},
    {p:'Interpretation: Akkord belohnt Mehrleistung am stärksten, ist aber nur bei voll beeinflussbarer, gut messbarer Arbeit fair. Prämienlohn eignet sich, wenn auch Qualität oder Materialersparnis zählen sollen; Zeitlohn bei Qualitätsarbeit und nicht messbarer Leistung. Lohnstückkosten: im Akkord konstant (2,01 €), im Zeitlohn sinkend mit der Leistung.'},
    {falle:'Bei Minderleistung im Akkord greift der garantierte Mindestverdienst – rechnerische Werte unter dem Garantielohn werden nicht ausgezahlt.'}
  ]},
  {t:'Kennzahlen und Prozessbewertung',h:'Kennzahlen und Prozessbewertung',pg:105,b:[
    {p:'Kennzahlen sind nach REFA Verhältniszahlen, die eine Aussage über einen Sachverhalt machen. Beobachtungs- und Bezugszahl müssen sachlich zusammenhängen. Die Meisterin legt für ihren Bereich Kennzahlen fest, beurteilt sie regelmäßig und reagiert sofort auf negative Tendenzen.'},
    {fx:['Kennzahl = Beobachtungszahl : Bezugszahl','']},
    {fx:['Nutzungsgrad = Fertigungszeiten : (Fertigungszeiten + Hilfszeiten) · 100','weniger Hilfszeiten → höherer Nutzungsgrad']},
    {fx:['Laufzeitgrad = Maschinenlaufzeit : (Arbeitszeit − Rüstzeiten) · 100','Störgrößen senken erhöht Laufzeit und Produktivität']},
    {fx:['Kapazitätsauslastungsgrad = Kapazitätsbedarf : Kapazitätsbestand · 100','Bestand = Betriebszeit · Anzahl Anlagen · Verfügbarkeit']},
    {tab:[['Kennzahl','Beispielwert','Signal'],['Ausschussquote','2,4 % der gefertigten Teile','über Ziel 2 % → Ursachen (Werkzeug, Material)'],['Nutzungsgrad','82,7 %','Hilfszeiten (Suchen, Warten) analysieren'],['Laufzeitgrad','80,0 %','Störungen und Kleinstillstände'],['Kapazitätsauslastung','86,8 %','Puffer für Eilaufträge'],['Instandhaltungskosten je Maschinenstunde','3,90 €','Trend beobachten']]},
    {bsp:{t:'Beispiel: Kennzahlen eines Fertigungsbereichs',b:['Nutzungsgrad: In einer Schicht 6,2 h Fertigungszeit und 1,3 h Hilfszeiten → 6,2 : 7,5 · 100 = 82,7 %.','Laufzeitgrad: Arbeitszeit 8,0 h, Rüsten 0,5 h, Maschinenlaufzeit 6,0 h → 6,0 : 7,5 · 100 = 80,0 %.','Kapazität additive Fertigung: 2 Anlagen, 91 Tage rund um die Uhr, Verfügbarkeit 95 % → 2 · 91 · 24 h · 0,95 = 4.149,6 h; Bedarf 3.600 h → Auslastung 86,8 %.','Interpretation: Laufzeitgrad 80 % zeigt 1,5 h Verlust je Schicht durch Störungen – mit Rüstoptimierung (SMED) und vorbeugender Wartung lässt sich die Kapazität ohne Investition erhöhen.']}},
    {merke:'Kennzahlen nur vergleichen, wenn sie gleich definiert sind. Eine Kennzahl allein beweist nichts – Trends und Ursachen zählen.'}
  ]}

 ]};
